import React, { useRef, useEffect, useState } from 'react';
import { ArrowLeft, Camera, Info } from 'lucide-react';

interface ScanningPageProps {
  onBack: () => void;
  onCapture: () => void;
}

const ScanningPage: React.FC<ScanningPageProps> = ({ onBack, onCapture }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => {
    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' } 
        });
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
      } catch (err) {
        console.error("Camera access denied", err);
      }
    }
    setupCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, []);

  return (
    <div className="flex-1 flex flex-col bg-[#F8FAFC]">
      {/* Header UI Overlay */}
      <div className="p-6 flex justify-between items-center z-10">
        <button 
          onClick={onBack}
          className="flex items-center gap-2 px-4 py-2 glass-card rounded-xl text-slate-700 font-bold text-sm shadow-sm"
        >
          <ArrowLeft size={16} />
          Dashboard
        </button>
        <div className="flex items-center gap-2 px-3 py-1.5 glass-card rounded-full shadow-sm">
          <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
          <span className="text-[10px] font-bold text-slate-800 tracking-wider uppercase">Neural Engine: Online</span>
        </div>
      </div>

      <div className="flex-1 flex items-center justify-center p-4 relative">
        <div className="relative w-full max-w-2xl aspect-[4/5] bg-slate-900 rounded-[40px] overflow-hidden vision-shadow border-[12px] border-white">
          {/* Tag Overlay */}
          <div className="absolute top-0 left-1/2 -translate-x-1/2 z-20">
             <div className="bg-[#5551FF] text-white text-[10px] font-black px-4 py-1.5 rounded-b-xl uppercase tracking-tighter">
                Vision AI Pro 2.0
             </div>
          </div>

          {/* Camera Feed */}
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            className="w-full h-full object-cover grayscale-[0.2] brightness-110" 
          />

          {/* Scan UI Elements */}
          <div className="absolute inset-0 border-[40px] border-black/10 pointer-events-none" />
          <div className="scan-line" />

          {/* Corner Markers */}
          <div className="absolute top-10 left-10 w-8 h-8 border-t-4 border-l-4 border-white/60 rounded-tl-lg" />
          <div className="absolute top-10 right-10 w-8 h-8 border-t-4 border-r-4 border-white/60 rounded-tr-lg" />
          <div className="absolute bottom-10 left-10 w-8 h-8 border-b-4 border-l-4 border-white/60 rounded-bl-lg" />
          <div className="absolute bottom-10 right-10 w-8 h-8 border-b-4 border-r-4 border-white/60 rounded-br-lg" />

          {/* Metadata Overlay */}
          <div className="absolute bottom-6 left-6 text-white/50 text-[10px] font-mono">
            LOC: 121.09 / -44.22
          </div>
          <div className="absolute bottom-6 right-6 text-white/50 text-[10px] font-mono">
            ENC: BASE64 / JPEG
          </div>
        </div>
      </div>

      {/* Control UI Overlay */}
      <div className="pb-12 flex flex-col items-center gap-8">
        <button 
          onClick={onCapture}
          className="w-20 h-20 bg-slate-900 rounded-full flex items-center justify-center vision-shadow ring-8 ring-slate-100 transition-transform active:scale-90"
        >
          <Camera size={32} className="text-white" />
        </button>

        <div className="text-center">
          <h3 className="text-2xl font-black text-slate-800 mb-1">Area Deteksi Presisi</h3>
          <p className="text-sm text-slate-400 max-w-xs px-4">
            AI akan mendeteksi seluruh barang di dalam kotak secara instan.
          </p>
        </div>

        <div className="bg-blue-50 px-6 py-2.5 rounded-full flex items-center gap-3 border border-blue-100">
          <Info size={16} className="text-[#5551FF]" />
          <span className="text-[10px] font-black text-[#5551FF] uppercase tracking-wider">
            Letakkan Produk Anda Menghadap Ke Kamera
          </span>
        </div>
      </div>
    </div>
  );
};

export default ScanningPage;

import React, { useEffect, useState } from 'react';
import { ArrowLeft, QrCode } from 'lucide-react';

interface PaymentQRISProps {
  onBack: () => void;
  onSuccess: () => void;
  total: number;
}

const PaymentQRIS: React.FC<PaymentQRISProps> = ({ onBack, onSuccess, total }) => {
  const [dots, setDots] = useState('.');

  useEffect(() => {
    const interval = setInterval(() => {
      setDots(prev => prev.length >= 3 ? '.' : prev + '.');
    }, 500);

    const timer = setTimeout(() => {
      onSuccess();
    }, 5000); // Simulate processing

    return () => {
      clearInterval(interval);
      clearTimeout(timer);
    };
  }, []);

  return (
    <div className="flex-1 w-full bg-[#4B5563] flex flex-col items-center justify-center p-6">
      <div className="w-full max-w-md bg-white rounded-[56px] vision-shadow p-10 flex flex-col items-center relative overflow-hidden">
        <button 
          onClick={onBack}
          className="absolute top-8 left-8 p-3 rounded-full hover:bg-slate-50 text-slate-400 transition-colors"
        >
          <ArrowLeft size={24} />
        </button>

        <div className="mt-12 mb-8 bg-blue-50 px-6 py-2 rounded-2xl flex items-center gap-3">
          <QrCode size={18} className="text-[#5551FF]" />
          <span className="text-[10px] font-black text-[#5551FF] uppercase tracking-[0.2em]">SCAN & BAYAR</span>
        </div>

        <h2 className="text-4xl font-black text-slate-900 mb-4 text-center">QRIS Pembayaran</h2>
        <p className="text-slate-400 font-medium text-center mb-12 max-w-[280px]">
          Gunakan m-Banking atau e-Wallet favorit Anda untuk memproses transaksi.
        </p>

        <div className="relative p-8 bg-slate-50 rounded-[48px] mb-12 vision-shadow">
          <div className="bg-white p-4 rounded-3xl">
            <img 
              src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=VISIONPAY_ORDER_${Math.random()}`} 
              alt="QRIS Code" 
              className="w-48 h-48"
