          <div className="absolute -bottom-4 left-1/2 -translate-x-1/2 glass-card px-4 py-3 rounded-2xl shadow-lg border border-slate-100 flex items-center gap-3 min-w-[160px]">
            <span className="w-1.5 h-4 bg-[#5551FF] rounded-full animate-pulse" />
            <div className="flex flex-col">
              <span className="text-[8px] font-black text-slate-900 uppercase tracking-tighter leading-none">MENUNGGU</span>
              <span className="text-[8px] font-black text-slate-900 uppercase tracking-tighter leading-none">SINYAL</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3 mb-16">
          <div className="flex gap-1">
            <span className={`w-1.5 h-1.5 rounded-full bg-[#5551FF] transition-opacity ${dots.length >= 1 ? 'opacity-100' : 'opacity-30'}`} />
            <span className={`w-1.5 h-1.5 rounded-full bg-[#5551FF] transition-opacity ${dots.length >= 2 ? 'opacity-100' : 'opacity-30'}`} />
            <span className={`w-1.5 h-1.5 rounded-full bg-[#5551FF] transition-opacity ${dots.length >= 3 ? 'opacity-100' : 'opacity-30'}`} />
          </div>
          <span className="text-[10px] font-black text-[#5551FF] uppercase tracking-[0.2em]">MEMVERIFIKASI PEMBAYARAN</span>
        </div>

        <div className="w-full flex justify-between items-end border-t border-slate-100 pt-8">
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-400 uppercase tracking-[0.2em]">TOTAL TAGIHAN</span>
            <span className="text-3xl font-black text-slate-900">Rp {total.toLocaleString('id-ID')}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PaymentQRIS;

