import React, { useState, useCallback, useEffect } from 'react';
import { ViewState, CartItem } from './types';
import LandingPage from './components/LandingPage';
import ScanningPage from './components/ScanningPage';
import CartPage from './components/CartPage';
import PaymentQRIS from './components/PaymentQRIS';
import PaymentCash from './components/PaymentCash';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';

const INITIAL_CART: CartItem[] = [
  { id: '1', name: 'Tumbler with flower pattern', price: 75000, quantity: 1 },
  { id: '2', name: 'Black and white patterned pillow', price: 50000, quantity: 1 },
  { id: '3', name: 'Yellow plush toy', price: 40000, quantity: 1 },
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [membershipCode, setMembershipCode] = useState<string>('');

  const handleStartShopping = () => {
    setCart([]); 
    setView(ViewState.SCANNING);
  };

  const handleFinishScanning = () => {
    // Simulasi deteksi AI: Memberikan item contoh ke keranjang
    setCart(INITIAL_CART);
    setView(ViewState.CART);
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => 
      item.id === id 
        ? { ...item, quantity: Math.max(1, item.quantity + delta) }
        : item
    ));
  };

  const handleRemoveItem = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const handleConfirmPayment = (method: 'QRIS' | 'CASH') => {
    if (method === 'QRIS') setView(ViewState.PAYMENT_QRIS);
    else setView(ViewState.PAYMENT_CASH);
  };

  const renderView = () => {
    const totalWithTax = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0) * 1.11;

    switch (view) {
      case ViewState.LANDING:
        return <LandingPage onStart={handleStartShopping} />;
      case ViewState.SCANNING:
        return <ScanningPage onBack={() => setView(ViewState.LANDING)} onCapture={handleFinishScanning} />;
      case ViewState.CART:
        return (
          <CartPage 
            cart={cart} 
            membershipCode={membershipCode}
            setMembershipCode={setMembershipCode}
            onUpdateQuantity={handleUpdateQuantity}
            onRemoveItem={handleRemoveItem}
            onReset={() => setView(ViewState.LANDING)}
            onConfirm={handleConfirmPayment}
          />
        );
      case ViewState.PAYMENT_QRIS:
        return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => setView(ViewState.SUCCESS)} total={totalWithTax} />;
      case ViewState.PAYMENT_CASH:
        return <PaymentCash onBack={() => setView(ViewState.CART)} onSuccess={() => setView(ViewState.SUCCESS)} total={totalWithTax} />;
      case ViewState.SUCCESS:
        return <SuccessPage onFinish={() => setView(ViewState.LANDING)} total={totalWithTax} />;
      default:
        return <LandingPage onStart={handleStartShopping} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Layout hideHeaderFooter={view === ViewState.SCANNING || view === ViewState.PAYMENT_QRIS || view === ViewState.PAYMENT_CASH || view === ViewState.SUCCESS}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { ArrowLeft, Camera, Info } from 'lucide-react';

interface ScanningPageProps {
  onBack: () => void;
  onCapture: () => void;
}

const ScanningPage: React.FC<ScanningPageProps> = ({ onBack, onCapture }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => {
    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' } 
        });
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
      } catch (err) {
        console.error("Camera access denied", err);
      }
    }
    setupCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, []);

  return (
    <div className="flex-1 flex flex-col bg-[#F8FAFC] w-full h-screen">
      {/* Header UI Overlay */}
      <div className="p-6 flex justify-between items-center z-10">
        <button 
          onClick={onBack}
          className="flex items-center gap-2 px-4 py-2 glass-card rounded-xl text-slate-700 font-bold text-sm shadow-sm"
        >
          <ArrowLeft size={16} />
          Kembali
        </button>
        <div className="flex items-center gap-2 px-3 py-1.5 glass-card rounded-full shadow-sm">
          <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
          <span className="text-[10px] font-bold text-slate-800 tracking-wider uppercase">AI Sensor: Aktif</span>
        </div>
      </div>

      <div className="flex-1 flex items-center justify-center p-4 relative">
        <div className="relative w-full max-w-lg aspect-[3/4] bg-slate-900 rounded-[40px] overflow-hidden vision-shadow border-[8px] border-white">
          {/* Tag Overlay */}
          <div className="absolute top-0 left-1/2 -translate-x-1/2 z-20">
             <div className="bg-[#5551FF] text-white text-[10px] font-black px-4 py-1.5 rounded-b-xl uppercase tracking-tighter">
                Vision Engine 2.5
             </div>
          </div>

          {/* Camera Feed */}
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            className="w-full h-full object-cover brightness-110" 
          />

          {/* Scan UI Elements */}
          <div className="scan-line" />

          {/* Corner Markers */}
          <div className="absolute top-10 left-10 w-8 h-8 border-t-4 border-l-4 border-white/60 rounded-tl-lg" />
          <div className="absolute top-10 right-10 w-8 h-8 border-t-4 border-r-4 border-white/60 rounded-tr-lg" />
          <div className="absolute bottom-10 left-10 w-8 h-8 border-b-4 border-l-4 border-white/60 rounded-bl-lg" />
          <div className="absolute bottom-10 right-10 w-8 h-8 border-b-4 border-r-4 border-white/60 rounded-br-lg" />
        </div>
      </div>

      {/* Control UI Overlay */}
      <div className="pb-12 flex flex-col items-center gap-6">
        <div className="flex flex-col items-center gap-3">
          <button 
            onClick={onCapture}
            className="w-24 h-24 bg-[#5551FF] rounded-full flex items-center justify-center vision-shadow ring-8 ring-blue-100 transition-all active:scale-90 hover:bg-[#4440FF]"
          >
            <Camera size={40} className="text-white" />
          </button>
          <span className="text-sm font-black text-[#5551FF] uppercase tracking-widest animate-pulse">Ketuk untuk Deteksi</span>
        </div>

        <div className="bg-white/80 backdrop-blur-md px-6 py-3 rounded-2xl flex items-center gap-3 border border-slate-100 shadow-sm">
          <Info size={16} className="text-slate-400" />
          <span className="text-[11px] font-bold text-slate-500 uppercase tracking-tight">
            Pastikan semua barang terlihat jelas di layar
          </span>
        </div>
      </div>
    </div>
  );
};

export default ScanningPage;

export enum ViewState {
  LANDING = 'LANDING',
  SELECT_INPUT = 'SELECT_INPUT',
  SCANNING_AI = 'SCANNING_AI',
  SCANNING_BARCODE = 'SCANNING_BARCODE',
  CART = 'CART',
  MEMBERSHIP_SCAN = 'MEMBERSHIP_SCAN',
  PAYMENT_QRIS = 'PAYMENT_QRIS',
  PAYMENT_CASH = 'PAYMENT_CASH',
  SUCCESS = 'SUCCESS'
}

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

import React, { useState } from 'react';
import { ViewState, CartItem } from './types';
import LandingPage from './components/LandingPage';
import SelectInputPage from './components/SelectInputPage';
import ScanningPage from './components/ScanningPage';
import BarcodeScannerPage from './components/BarcodeScannerPage';
import CartPage from './components/CartPage';
import MembershipPage from './components/MembershipPage';
import PaymentQRIS from './components/PaymentQRIS';
import PaymentCash from './components/PaymentCash';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';

const INITIAL_CART: CartItem[] = [
  { id: '1', name: 'Tumbler with flower pattern', price: 75000, quantity: 1 },
  { id: '2', name: 'Black and white patterned pillow', price: 50000, quantity: 1 },
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [discountAmount, setDiscountAmount] = useState<number>(0);

  const handleStart = () => setView(ViewState.SELECT_INPUT);

  const handleFinishScanning = () => {
    setCart(INITIAL_CART);
    setView(ViewState.CART);
  };

  const handleMembershipResult = (memberActive: boolean) => {
    setIsMember(memberActive);
    if (memberActive) {
      const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
      setDiscountAmount(subtotal * 0.10); // Diskon 10% untuk member
    } else {
      setDiscountAmount(0);
    }
    setView(ViewState.CART); // Kembali ke cart untuk pilih pembayaran setelah membership
  };

  const handleConfirmPayment = (method: 'QRIS' | 'CASH') => {
    if (method === 'QRIS') setView(ViewState.PAYMENT_QRIS);
    else setView(ViewState.PAYMENT_CASH);
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const tax = (subtotal - discountAmount) * 0.11;
    const finalTotal = (subtotal - discountAmount) + tax;

    switch (view) {
      case ViewState.LANDING:
        return <LandingPage onStart={handleStart} />;
      case ViewState.SELECT_INPUT:
        return (
          <SelectInputPage 
            onSelectAI={() => setView(ViewState.SCANNING_AI)} 
            onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)}
            onBack={() => setView(ViewState.LANDING)}
          />
        );
      case ViewState.SCANNING_AI:
        return <ScanningPage onBack={() => setView(ViewState.SELECT_INPUT)} onCapture={handleFinishScanning} />;
      case ViewState.SCANNING_BARCODE:
        return <BarcodeScannerPage onBack={() => setView(ViewState.SELECT_INPUT)} onFinish={handleFinishScanning} />;
      case ViewState.CART:
        return (
          <CartPage 
            cart={cart} 
            isMember={isMember}
            discountAmount={discountAmount}
            onUpdateQuantity={(id, delta) => setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(1, item.quantity + delta) } : item))}
            onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))}
            onReset={() => { setView(ViewState.LANDING); setIsMember(false); setDiscountAmount(0); }}
            onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)}
            onConfirm={handleConfirmPayment}
          />
        );
      case ViewState.MEMBERSHIP_SCAN:
        return <MembershipPage onSkip={() => handleMembershipResult(false)} onDetected={() => handleMembershipResult(true)} />;
      case ViewState.PAYMENT_QRIS:
        return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => setView(ViewState.SUCCESS)} total={finalTotal} />;
      case ViewState.PAYMENT_CASH:
        return <PaymentCash onBack={() => setView(ViewState.CART)} onSuccess={() => setView(ViewState.SUCCESS)} total={finalTotal} />;
      case ViewState.SUCCESS:
        return <SuccessPage onFinish={() => { setView(ViewState.LANDING); setIsMember(false); setDiscountAmount(0); }} total={finalTotal} />;
      default:
        return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.SCANNING_AI, ViewState.SCANNING_BARCODE, ViewState.MEMBERSHIP_SCAN, ViewState.PAYMENT_QRIS, ViewState.PAYMENT_CASH, ViewState.SUCCESS].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

