import React, { useState } from 'react';
import { ArrowLeft, Barcode, Check } from 'lucide-react';

interface BarcodeScannerPageProps {
  onBack: () => void;
  onFinish: () => void;
}

const BarcodeScannerPage: React.FC<BarcodeScannerPageProps> = ({ onBack, onFinish }) => {
  const [scannedItems, setScannedItems] = useState<number>(0);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);

  const handleSimulateScan = () => {
    setIsProcessing(true);
    setTimeout(() => {
      setScannedItems(prev => prev + 1);
      setIsProcessing(false);
    }, 600);
  };

  return (
    <div className="flex-1 w-full flex flex-col bg-slate-50">
      <div className="p-6 flex justify-between items-center">
        <button onClick={onBack} className="flex items-center gap-2 px-4 py-2 glass-card rounded-xl text-slate-700 font-bold">
          <ArrowLeft size={16} /> Kembali
        </button>
        <div className="px-4 py-2 bg-slate-900 text-white rounded-xl font-black text-xs uppercase tracking-widest">
          Scanner Mode
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-6 text-center">
        <div className="relative mb-12">
          <div className={`w-64 h-64 bg-white rounded-[48px] vision-shadow flex flex-col items-center justify-center border-4 ${isProcessing ? 'border-[#5551FF]' : 'border-transparent'} transition-colors`}>
            <Barcode size={100} className={isProcessing ? 'text-[#5551FF] animate-pulse' : 'text-slate-300'} />
            <div className="mt-4 text-[10px] font-black text-slate-400 tracking-[0.3em]">SIAP SCAN</div>
          </div>
          {scannedItems > 0 && (
            <div className="absolute -top-4 -right-4 w-12 h-12 bg-green-500 rounded-full flex items-center justify-center text-white font-black text-lg vision-shadow border-4 border-white animate-bounce">
              {scannedItems}
            </div>
          )}
        </div>

        <h2 className="text-3xl font-black text-slate-900 mb-2">Scan Barcode Anda</h2>
        <p className="text-slate-400 mb-12 max-w-xs">Dekatkan barcode produk ke sensor pemindai di depan Anda.</p>

        <div className="flex flex-col gap-4 w-full max-w-xs">
          <button 
            onClick={handleSimulateScan}
            className="py-4 bg-white border-2 border-slate-200 rounded-3xl font-bold text-slate-600 hover:border-[#5551FF] hover:text-[#5551FF] transition-all active:scale-95"
          >
            Simulasi Scan Barang
          </button>

          <button 
            onClick={onFinish}
            disabled={scannedItems === 0}
            className="py-5 bg-[#5551FF] text-white rounded-3xl font-black text-lg vision-shadow hover:bg-[#4440FF] transition-all active:scale-95 disabled:opacity-50"
          >
            Selesai & Ke Keranjang
          </button>
        </div>
      </div>
    </div>
  );
};

