interface VoucherSelectionPageProps {
  isMember: boolean;
  totalPoints: number;
  onSelect: (voucher: Voucher | null) => void;
  onBack: () => void;
}

// Mock user data for demonstration
const MOCK_USER = {
  name: 'Budi Santoso',
  totalBalance: 12450,
  tier: 'Platinum', // Silver, Gold, Platinum
};

const AVAILABLE_VOUCHERS: Voucher[] = [
  {
    id: 'V-MEMBER-10',
    title: 'Member Special 10%',
    description: 'Diskon 10% untuk semua item tanpa minimum belanja.',
