    value: 10,
    isMemberOnly: true
  },
  {
    id: 'V-NEW-USER',
    title: 'Hemat Belanja',
    description: 'Potongan Rp 15.000 untuk transaksi pertama hari ini.',
    discountType: 'FIXED',
    value: 15000,
    isMemberOnly: false
  },
  {
    id: 'V-CASHBACK-5',
    title: 'VisionPay Rewards',
    description: 'Diskon Rp 5.000 khusus pengguna baru aplikasi.',
    discountType: 'FIXED',
    value: 5000,
    isMemberOnly: false
  },
  {
    id: 'V-MEMBER-PLATINUM',
