    minTransaction: 100000,
    isMemberOnly: true
  }
];

const VoucherSelectionPage: React.FC<VoucherSelectionPageProps> = ({ isMember, totalPoints, onSelect, onBack }) => {
  const getTierColor = (tier: string) => {
    switch (tier.toLowerCase()) {
      case 'platinum': return 'from-indigo-600 to-slate-900 text-white';
      case 'gold': return 'from-amber-400 to-amber-600 text-white';
      case 'silver': return 'from-slate-300 to-slate-500 text-white';
      default: return 'from-slate-100 to-slate-200 text-slate-600';
    }
  };

  const getTierBadge = (tier: string) => {
    switch (tier.toLowerCase()) {
      case 'platinum': return <Crown size={14} className="text-indigo-200" />;
      case 'gold': return <Star size={14} className="text-amber-100" />;
      default: return <Award size={14} className="text-slate-100" />;
