                      <span className="text-[10px] font-black uppercase tracking-widest">{MOCK_USER.tier}</span>
                    </div>
                  </div>

                  <div className="flex items-baseline gap-2 mt-2">
                    <span className="text-white/60 text-xs font-bold uppercase tracking-widest">Saldo Poin:</span>
                    <span className="text-2xl font-black">{MOCK_USER.totalBalance.toLocaleString('id-ID')}</span>
