        {totalPoints > 0 && (
          <div className="mb-8 bg-amber-50 rounded-[32px] p-6 border-2 border-amber-200/50 vision-shadow overflow-hidden relative group">
            <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:scale-125 transition-transform duration-1000">
              <Sparkles size={120} className="text-amber-500" />
            </div>
            <div className="relative flex items-center gap-6">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-amber-500 shadow-sm border border-amber-100">
                <Coins size={32} />
              </div>
              <div>
                <span className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none">POIN TRANSAKSI INI</span>
                <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-900">{totalPoints.toLocaleString('id-ID')}</span>
                  <span className="text-sm font-bold text-slate-500">Points</span>
                </div>
                <p className="text-xs text-slate-400 mt-1 font-medium">
                  {isMember 
                    ? `Poin akan ditambahkan ke saldo ${MOCK_USER.tier} Anda setelah pembayaran.` 
                    : 'Scan membership untuk mengklaim poin dari belanjaan ini.'}
                </p>
              </div>
              {!isMember && (
                <div className="ml-auto">
                   <span className="px-3 py-1 bg-slate-900 text-white text-[8px] font-black rounded-full uppercase tracking-widest">LOCKED</span>
                </div>
              )}
            </div>
          </div>
        )}

        {isMember && (
          <div className="flex items-center gap-2 mb-6 ml-2">
            <Star size={16} className="text-[#5551FF]" fill="currentColor" />
            <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">Pilih Penawaran Khusus Member</h4>
          </div>
        )}

        <div className="grid grid-cols-1 gap-4 mb-12">
          {AVAILABLE_VOUCHERS.map((voucher) => {
            const isDisabled = voucher.isMemberOnly && !isMember;

            return (
              <button
                key={voucher.id}
                disabled={isDisabled}
                onClick={() => onSelect(voucher)}
                className={`group relative text-left p-6 rounded-[32px] border-2 transition-all flex items-center gap-6 overflow-hidden
                  ${isDisabled 
                    ? 'bg-slate-50 border-slate-100 grayscale opacity-60 cursor-not-allowed' 
                    : 'bg-white border-transparent hover:border-[#5551FF] vision-shadow active:scale-[0.98]'}`}
              >
                {/* Icon Section */}
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center shrink-0
                  ${voucher.isMemberOnly ? 'bg-amber-50 text-amber-500' : 'bg-blue-50 text-[#5551FF]'}`}>
                  {voucher.discountType === 'PERCENT' ? <Percent size={32} /> : <Gift size={32} />}
                </div>

                {/* Content Section */}
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <h4 className="font-black text-slate-900 text-lg uppercase tracking-tight">{voucher.title}</h4>
                    {voucher.isMemberOnly && (
                      <span className="px-2 py-0.5 bg-amber-100 text-amber-600 text-[8px] font-black rounded-md uppercase">MEMBER ONLY</span>
                    )}
                  </div>
                  <p className="text-sm text-slate-400 font-medium leading-tight mb-2">
                    {voucher.description}
                  </p>
                  <div className="flex items-center gap-4">
                    <span className="text-xs font-black text-[#5551FF] uppercase tracking-wider">
                      {voucher.discountType === 'PERCENT' ? `Hemat ${voucher.value}%` : `Hemat Rp ${voucher.value.toLocaleString('id-ID')}`}
                    </span>
                    {voucher.minTransaction && (
                      <span className="text-[10px] text-slate-400 font-bold uppercase italic">
                        Min. Trx Rp {voucher.minTransaction.toLocaleString('id-ID')}
                      </span>
                    )}
                  </div>
                </div>

                {/* Action Indicator */}
                {!isDisabled && (
                  <div className="opacity-0 group-hover:opacity-100 transition-opacity pr-2">
                    <CheckCircle2 size={32} className="text-[#5551FF]" />
                  </div>
                )}
              </button>
            );
          })}
        </div>

        <button 
          onClick={() => onSelect(null)}
          className="w-full py-5 border-2 border-dashed border-slate-200 text-slate-400 font-black rounded-[32px] hover:border-[#5551FF] hover:text-[#5551FF] transition-all flex items-center justify-center gap-2 group"
        >
          <Zap size={18} className="group-hover:animate-pulse" />
          LANJUT TANPA VOUCHER
        </button>
      </div>
    </div>
  );
};

export default VoucherSelectionPage;

