import React, { useState } from 'react';
import { ViewState, CartItem, Voucher, RedeemableItem } from './types';
import LandingPage from './components/LandingPage';
import SelectInputPage from './components/SelectInputPage';
import ScanningPage from './components/ScanningPage';
import BarcodeScannerPage from './components/BarcodeScannerPage';
import CartPage from './components/CartPage';
import MembershipPage from './components/MembershipPage';
import VoucherSelectionPage from './components/VoucherSelectionPage';
import PaymentQRIS from './components/PaymentQRIS';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';

const INITIAL_CART: CartItem[] = [
  { id: '1', name: 'Tumbler with flower pattern', price: 75000, quantity: 1, points: 350 },
  { id: '2', name: 'Black and white patterned pillow', price: 50000, quantity: 1, points: 150 },
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);

  const handleStart = () => setView(ViewState.SELECT_INPUT);

  const handleFinishScanning = () => {
    setCart(INITIAL_CART);
    setView(ViewState.CART);
  };

  const handleMembershipResult = (memberActive: boolean) => {
    setIsMember(memberActive);
    setView(ViewState.SELECT_VOUCHER);
  };

  const handleApplyVoucher = (voucher: Voucher | null) => {
    setSelectedVoucher(voucher);
    setView(ViewState.CART);
  };

  const handleRedeemGift = (item: RedeemableItem) => {
    const giftItem: CartItem = {
      id: `gift-${item.id}-${Date.now()}`,
      name: `🎁 [HADIAH] ${item.name}`,
      price: 0,
      quantity: 1,
      isGift: true
    };
    setCart(prev => [...prev, giftItem]);
    // In a real app, you would also deduct points from user profile here.
  };

  const handleConfirmPayment = () => {
    setView(ViewState.PAYMENT_QRIS);
  };

  const calculateDiscount = () => {
    if (!selectedVoucher) return 0;
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

    if (selectedVoucher.discountType === 'PERCENT') {
      return subtotal * (selectedVoucher.value / 100);
    } else {
      return selectedVoucher.value;
    }
  };

  const calculateTotalPoints = () => {
    return cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const discountAmount = calculateDiscount();
    const tax = (subtotal - discountAmount) * 0.11;
    const finalTotal = (subtotal - discountAmount) + tax;
    const totalPoints = calculateTotalPoints();

    switch (view) {
      case ViewState.LANDING:
        return <LandingPage onStart={handleStart} />;
      case ViewState.SELECT_INPUT:
        return (
          <SelectInputPage 
            onSelectAI={() => setView(ViewState.SCANNING_AI)} 
            onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)}
            onBack={() => setView(ViewState.LANDING)}
          />
        );
      case ViewState.SCANNING_AI:
        return <ScanningPage onBack={() => setView(ViewState.SELECT_INPUT)} onCapture={handleFinishScanning} />;
      case ViewState.SCANNING_BARCODE:
        return <BarcodeScannerPage onBack={() => setView(ViewState.SELECT_INPUT)} onFinish={handleFinishScanning} />;
      case ViewState.CART:
        return (
          <CartPage 
            cart={cart} 
            isMember={isMember}
            selectedVoucher={selectedVoucher}
            discountAmount={discountAmount}
            onUpdateQuantity={(id, delta) => setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(1, item.quantity + delta) } : item))}
            onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))}
            onReset={() => { setView(ViewState.LANDING); setIsMember(false); setSelectedVoucher(null); }}
            onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)}
            onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)}
            onConfirm={handleConfirmPayment}
          />
        );
      case ViewState.MEMBERSHIP_SCAN:
        return <MembershipPage onSkip={() => handleMembershipResult(false)} onDetected={() => handleMembershipResult(true)} />;
      case ViewState.SELECT_VOUCHER:
        return (
          <VoucherSelectionPage 
            isMember={isMember} 
            totalPoints={totalPoints} 
            onSelect={handleApplyVoucher} 
            onRedeem={handleRedeemGift}
            onBack={() => setView(ViewState.CART)} 
          />
        );
      case ViewState.PAYMENT_QRIS:
        return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => setView(ViewState.SUCCESS)} total={finalTotal} />;
      case ViewState.SUCCESS:
        return <SuccessPage onFinish={() => { setView(ViewState.LANDING); setIsMember(false); setSelectedVoucher(null); }} total={finalTotal} />;
      default:
        return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.SCANNING_AI, ViewState.SCANNING_BARCODE, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ViewState, CartItem, Voucher, RedeemableItem } from './types';
