import React, { useState } from 'react';
import { ShoppingCart, Trash2, Plus, Minus, QrCode, RotateCcw, ArrowRight, Ticket, Check, Users, UserPlus, Sparkles, Coins } from 'lucide-react';
import { CartItem, Voucher } from '../types';

interface CartPageProps {
  cart: CartItem[];
  isMember: boolean;
  selectedVoucher: Voucher | null;
  discountAmount: number;
  pointsDiscount?: number;
  onUpdateQuantity: (id: string, delta: number) => void;
  onRemoveItem: (id: string) => void;
  onReset: () => void;
  onGoToMembership: () => void;
  onGoToVouchers: () => void;
  onConfirm: () => void;
}

const CartPage: React.FC<CartPageProps> = ({ 
  cart, isMember, selectedVoucher, discountAmount, pointsDiscount = 0, onUpdateQuantity, onRemoveItem, onReset, onGoToMembership, onGoToVouchers, onConfirm 
}) => {
  const [affiliateCode, setAffiliateCode] = useState('');
  const [isAffiliateApplied, setIsAffiliateApplied] = useState(false);

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalDiscount = discountAmount + pointsDiscount;
  const tax = Math.max(0, (subtotal - totalDiscount) * 0.11);
  const total = Math.max(0, (subtotal - totalDiscount) + tax);

  const handleApplyAffiliate = () => {
    if (affiliateCode.trim().length > 0) {
      setIsAffiliateApplied(true);
    }
  };

  const getMembershipCardContent = () => {
    if (!isMember) {
      return {
        bg: 'bg-slate-900 text-white shadow-xl shadow-slate-200',
        iconBg: 'bg-slate-800 text-[#5551FF]',
        icon: <Ticket size={32} />,
        title: 'VisionPay Membership',
        desc: 'Punya kartu member? Scan untuk dapatkan diskon & gunakan poin cashback.',
        button: (
          <button 
            onClick={onGoToMembership}
            className="px-6 py-3 bg-[#5551FF] hover:bg-[#4440FF] rounded-2xl font-black text-xs uppercase tracking-widest transition-all shrink-0"
          >
            Scan Member
          </button>
        )
      };
    }

    return {
      bg: 'bg-indigo-600 text-white shadow-xl shadow-indigo-200',
      iconBg: 'bg-white/20',
      icon: <Sparkles size={32} />,
      title: 'Portal Member Aktif',
      desc: pointsDiscount > 0 
        ? `Poin cashback Rp ${pointsDiscount.toLocaleString('id-ID')} telah digunakan.` 
        : 'Atur penggunaan poin dan voucher di menu reward.',
      button: (
        <button 
          onClick={onGoToVouchers}
          className="px-6 py-3 bg-white text-indigo-600 hover:bg-indigo-50 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shrink-0"
        >
          Menu Reward
        </button>
      )
    };
  };

  const card = getMembershipCardContent();

  return (
    <div className="w-full flex flex-col gap-8 max-w-5xl animate-in fade-in duration-500">
      <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
        <div className="lg:col-span-3 space-y-6">
          <div className="glass-card rounded-[40px] p-8 vision-shadow">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl font-black text-slate-800">Keranjang Belanja</h2>
              <span className="px-4 py-1.5 bg-slate-100 text-slate-500 text-[10px] font-black rounded-full uppercase tracking-widest">
                {cart.length} ITEMS
              </span>
            </div>

            <div className="space-y-4 max-h-[420px] overflow-y-auto pr-2">
              {cart.map(item => (
                <div key={item.id} className="bg-white p-6 rounded-[24px] flex items-center justify-between border border-slate-50 shadow-sm">
                  <div className="flex items-center gap-4">
                    <div>
                      <span className="block text-slate-800 font-bold text-lg">{item.name}</span>
                      <span className="text-[#5551FF] font-black text-sm">
                        Rp {item.price.toLocaleString('id-ID')}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-center gap-6">
                    <div className="flex items-center gap-4 bg-slate-50 px-3 py-2 rounded-2xl">
                      <button onClick={() => onUpdateQuantity(item.id, -1)} className="text-slate-400 hover:text-slate-800 transition-colors"><Minus size={16}/></button>
                      <span className="w-8 text-center font-black text-lg text-slate-900">{item.quantity}</span>
                      <button onClick={() => onUpdateQuantity(item.id, 1)} className="text-slate-400 hover:text-slate-800 transition-colors"><Plus size={16}/></button>
                    </div>
                    <button onClick={() => onRemoveItem(item.id)} className="text-red-200 hover:text-red-500 transition-colors"><Trash2 size={20}/></button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className={`rounded-[40px] p-8 flex items-center gap-6 transition-all duration-500 ${card.bg}`}>
            <div className={`w-16 h-16 rounded-[24px] flex items-center justify-center shrink-0 ${card.iconBg}`}>
              {card.icon}
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="font-black text-lg truncate">{card.title}</h3>
              <p className="opacity-80 text-sm leading-tight">
                {card.desc}
              </p>
            </div>
            {card.button}
          </div>

          <div className="glass-card rounded-[40px] p-8 vision-shadow border border-slate-100 flex flex-col sm:flex-row items-center gap-6">
            <div className={`w-16 h-16 rounded-[24px] flex items-center justify-center shrink-0 ${isAffiliateApplied ? 'bg-indigo-500 text-white' : 'bg-indigo-50 text-indigo-500'}`}>
              {isAffiliateApplied ? <Check size={32} /> : <Users size={32} />}
            </div>
            <div className="flex-1 w-full">
              <div className="flex justify-between items-center mb-1">
                <h3 className="font-black text-slate-800 text-lg">Kode Affiliasi</h3>
                {isAffiliateApplied && (
                  <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">TERPASANG</span>
                )}
              </div>
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={affiliateCode}
                  onChange={(e) => setAffiliateCode(e.target.value)}
                  disabled={isAffiliateApplied}
                  placeholder="Masukkan kode..."
                  className={`flex-1 bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3 text-sm font-bold focus:outline-none focus:border-indigo-500 transition-all ${isAffiliateApplied ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'text-slate-700'}`}
                />
                {!isAffiliateApplied ? (
                  <button onClick={handleApplyAffiliate} className="px-6 py-3 bg-indigo-500 hover:bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest transition-all">Terapkan</button>
                ) : (
                  <button onClick={() => {setIsAffiliateApplied(false); setAffiliateCode('');}} className="px-6 py-3 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-2xl font-black text-xs uppercase tracking-widest transition-all">Hapus</button>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="lg:col-span-2">
          <div className="glass-card rounded-[40px] p-8 vision-shadow border-2 border-white h-full flex flex-col">
            <h2 className="text-2xl font-black text-slate-800 mb-8">Ringkasan</h2>

            <div className="space-y-4 mb-8">
              <div className="flex justify-between text-slate-500 font-medium">
                <span>Subtotal</span>
                <span className="font-bold text-slate-800">Rp {subtotal.toLocaleString('id-ID')}</span>
              </div>
              {selectedVoucher && discountAmount > 0 && (
                <div className="flex justify-between text-indigo-600 font-medium">
                  <div className="flex items-center gap-2"><Ticket size={14}/> <span>Voucher</span></div>
                  <span className="font-black">- Rp {discountAmount.toLocaleString('id-ID')}</span>
                </div>
              )}
              {isMember && pointsDiscount > 0 && (
                <div className="flex justify-between text-amber-600 font-medium">
                  <div className="flex items-center gap-2"><Coins size={14}/> <span>Poin Cashback</span></div>
                  <span className="font-black">- Rp {pointsDiscount.toLocaleString('id-ID')}</span>
                </div>
              )}
              <div className="flex justify-between text-slate-500 font-medium">
                <span>Pajak (11%)</span>
                <span className="font-bold text-slate-800">Rp {tax.toLocaleString('id-ID')}</span>
              </div>
              <div className="pt-4 border-t border-slate-100 flex justify-between items-end">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">TOTAL AKHIR</span>
                <span className="text-3xl font-black text-[#5551FF]">Rp {total.toLocaleString('id-ID')}</span>
              </div>
            </div>

            <div className="mt-auto space-y-4">
              <div className="bg-blue-50/50 p-4 rounded-2xl border border-blue-100 flex items-center gap-3 mb-6">
                <QrCode size={20} className="text-[#5551FF]" />
                <span className="text-[10px] font-black text-[#5551FF] uppercase tracking-wider">Metode: QRIS</span>
              </div>
              <button onClick={onConfirm} className="w-full py-5 bg-[#5551FF] hover:bg-[#4440FF] text-white rounded-[32px] font-black text-lg transition-all vision-shadow active:scale-95 flex items-center justify-center gap-3">
                BAYAR SEKARANG <ArrowRight size={20} />
              </button>
              <button onClick={onReset} className="w-full py-4 text-slate-400 font-bold text-sm">Batal & Ulangi</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

