  const totalDiscount = discountAmount + pointsDiscount;
  const tax = Math.max(0, (subtotal - totalDiscount) * 0.11);
  const total = Math.max(0, (subtotal - totalDiscount) + tax);

  const handleApplyAffiliate = () => {
    if (affiliateCode.trim().length > 0) {
      setIsAffiliateApplied(true);
    }
