          <div className="glass-card rounded-[40px] p-8 vision-shadow">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl font-black text-slate-800">Keranjang Belanja</h2>
              <span className="px-4 py-1.5 bg-slate-100 text-slate-500 text-[10px] font-black rounded-full uppercase tracking-widest">
                {cart.length} ITEMS
              </span>
            </div>

            <div className="space-y-4 max-h-[420px] overflow-y-auto pr-2">
              {cart.map(item => {
                const isMaxStock = item.quantity >= item.stock;
                const isLowStock = item.stock <= 2;

                return (
                  <div key={item.id} className="bg-white p-6 rounded-[24px] flex flex-col gap-4 border border-slate-50 shadow-sm">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div>
