                          <div className="flex items-center gap-3">
                            <span className="text-[#5551FF] font-black text-sm">
                              Rp {item.price.toLocaleString('id-ID')}
                            </span>
                            <span className={`text-[10px] font-black px-2 py-0.5 rounded-md uppercase tracking-wider ${isMaxStock ? 'bg-red-50 text-red-500' : 'bg-slate-100 text-slate-400'}`}>
                              Stok: {item.stock}
                            </span>
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-6">
                        <div className="flex items-center gap-4 bg-slate-50 px-3 py-2 rounded-2xl">
                          <button 
                            onClick={() => onUpdateQuantity(item.id, -1)} 
                            className="text-slate-400 hover:text-slate-800 transition-colors"
                          >
                            <Minus size={16}/>
                          </button>
                          <span className="w-8 text-center font-black text-lg text-slate-900">{item.quantity}</span>
                          <button 
                            onClick={() => onUpdateQuantity(item.id, 1)} 
