                BAYAR SEKARANG <ArrowRight size={20} />
              </button>
              <button onClick={onReset} className="w-full py-4 text-slate-400 font-bold text-sm">Batal & Ulangi</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CartPage;

export enum ViewState {
  LANDING = 'LANDING',
  SELECT_INPUT = 'SELECT_INPUT',
  SCANNING_AI = 'SCANNING_AI',
  SCANNING_BARCODE = 'SCANNING_BARCODE',
  CART = 'CART',
  MEMBERSHIP_SCAN = 'MEMBERSHIP_SCAN',
  SELECT_VOUCHER = 'SELECT_VOUCHER',
  PAYMENT_QRIS = 'PAYMENT_QRIS',
  SUCCESS = 'SUCCESS'
}

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
  points?: number;
}

export interface Voucher {
  id: string;
  title: string;
  description: string;
  discountType: 'PERCENT' | 'FIXED';
  value: number;
  minTransaction?: number;
  isMemberOnly: boolean;
}

