export default VoucherSelectionPage;

export enum ViewState {
  LANDING = 'LANDING',
  SELECT_INPUT = 'SELECT_INPUT',
  SCANNING_AI = 'SCANNING_AI',
  SCANNING_BARCODE = 'SCANNING_BARCODE',
  CART = 'CART',
  MEMBERSHIP_SCAN = 'MEMBERSHIP_SCAN',
  SELECT_VOUCHER = 'SELECT_VOUCHER',
  PAYMENT_QRIS = 'PAYMENT_QRIS',
  SUCCESS = 'SUCCESS'
}

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
  points?: number;
}

export interface Voucher {
  id: string;
  title: string;
  description: string;
  discountType: 'PERCENT' | 'FIXED';
  value: number;
  minTransaction?: number;
  isMemberOnly: boolean;
}

export interface TransactionData {
  transactionId: string;
  customerType: 'MEMBER' | 'GUEST';
  items: string;
  subtotal: number;
  voucherName: string;
  voucherDiscount: number;
  pointsDiscount: number;
  tax: number;
  totalPaid: number;
  pointsEarned: number;
}

import React, { useState } from 'react';
import { ViewState, CartItem, Voucher, TransactionData } from './types';
import LandingPage from './components/LandingPage';
import SelectInputPage from './components/SelectInputPage';
import ScanningPage from './components/ScanningPage';
import BarcodeScannerPage from './components/BarcodeScannerPage';
import CartPage from './components/CartPage';
import MembershipPage from './components/MembershipPage';
import VoucherSelectionPage from './components/VoucherSelectionPage';
import PaymentQRIS from './components/PaymentQRIS';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';

const INITIAL_CART: CartItem[] = [
  { id: '1', name: 'Tumbler with flower pattern', price: 75000, quantity: 1, points: 350 },
  { id: '2', name: 'Black and white patterned pillow', price: 50000, quantity: 1, points: 150 },
];

const MOCK_MEMBER_POINTS = 12450;
// GANTI URL INI dengan URL Web App dari Google Apps Script Anda
const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/XXXXX/exec";

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);
  const [usePoints, setUsePoints] = useState<boolean>(false);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);

  const handleStart = () => setView(ViewState.SELECT_INPUT);

  const handleFinishScanning = () => {
    setCart(INITIAL_CART);
    setView(ViewState.CART);
  };

  const handleMembershipResult = (memberActive: boolean) => {
    setIsMember(memberActive);
    setView(ViewState.SELECT_VOUCHER);
  };

  const handleApplyVoucher = (voucher: Voucher | null) => {
    setSelectedVoucher(voucher);
    setView(ViewState.CART);
  };

  const syncTransaction = async (total: number, tax: number, subtotal: number, discount: number, ptsDisc: number, pointsEarned: number) => {
    setIsSyncing(true);
    const transactionId = `#VP-${Math.floor(1000 + Math.random() * 9000)}`;

    const data: TransactionData = {
      transactionId,
      customerType: isMember ? 'MEMBER' : 'GUEST',
      items: cart.map(i => `${i.name} (x${i.quantity})`).join(', '),
      subtotal,
      voucherName: selectedVoucher?.title || "N/A",
      voucherDiscount: discount,
      pointsDiscount: ptsDisc,
      tax,
      totalPaid: total,
      pointsEarned
    };

    try {
      // Kita gunakan mode 'no-cors' jika hanya ingin mengirim data tanpa butuh response detail dari Apps Script
      await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      });
    } catch (error) {
      console.error("Gagal mengirim data ke Spreadsheet:", error);
    } finally {
      setIsSyncing(false);
      setView(ViewState.SUCCESS);
    }
  };

  const calculateDiscount = () => {
    if (!selectedVoucher) return 0;
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return selectedVoucher.discountType === 'PERCENT' 
      ? subtotal * (selectedVoucher.value / 100) 
      : selectedVoucher.value;
  };

  const calculateTotalPoints = () => {
    return cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = item.quantity + delta;
        return newQty >= 1 ? { ...item, quantity: newQty } : item;
      }
      return item;
    }));
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const voucherDiscount = calculateDiscount();
    const pointsDiscount = (isMember && usePoints) ? MOCK_MEMBER_POINTS : 0;
    const totalReduction = Math.min(subtotal, voucherDiscount + pointsDiscount);
    const tax = (subtotal - totalReduction) * 0.11;
    const finalTotal = (subtotal - totalReduction) + tax;
    const newCashback = calculateTotalPoints();

    switch (view) {
      case ViewState.LANDING:
        return <LandingPage onStart={handleStart} />;
      case ViewState.SELECT_INPUT:
        return <SelectInputPage onSelectAI={() => setView(ViewState.SCANNING_AI)} onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)} onBack={() => setView(ViewState.LANDING)} />;
      case ViewState.SCANNING_AI:
        return <ScanningPage onBack={() => setView(ViewState.SELECT_INPUT)} onCapture={handleFinishScanning} />;
      case ViewState.SCANNING_BARCODE:
        return <BarcodeScannerPage onBack={() => setView(ViewState.SELECT_INPUT)} onFinish={handleFinishScanning} />;
      case ViewState.CART:
        return <CartPage cart={cart} isMember={isMember} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} pointsDiscount={pointsDiscount} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onReset={() => { setView(ViewState.LANDING); setIsMember(false); setSelectedVoucher(null); setUsePoints(false); }} onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)} onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)} onConfirm={() => setView(ViewState.PAYMENT_QRIS)} />;
      case ViewState.MEMBERSHIP_SCAN:
        return <MembershipPage onSkip={() => handleMembershipResult(false)} onDetected={() => handleMembershipResult(true)} />;
      case ViewState.SELECT_VOUCHER:
        return <VoucherSelectionPage isMember={isMember} totalPoints={newCashback} usePoints={usePoints} onTogglePoints={setUsePoints} onSelect={handleApplyVoucher} onBack={() => setView(ViewState.CART)} />;
      case ViewState.PAYMENT_QRIS:
        return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => syncTransaction(finalTotal, tax, subtotal, voucherDiscount, pointsDiscount, newCashback)} total={finalTotal} />;
      case ViewState.SUCCESS:
        return <SuccessPage onFinish={() => { setView(ViewState.LANDING); setIsMember(false); setSelectedVoucher(null); setUsePoints(false); }} total={finalTotal} isSyncing={isSyncing} />;
      default:
        return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.SCANNING_AI, ViewState.SCANNING_BARCODE, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

