function doPost(e) {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const sheet = ss.getActiveSheet();

    // Daftar Header Baru yang Lebih Lengkap
    const headers = [
      "Waktu Transaksi", 
      "ID Transaksi", 
      "Tipe Pelanggan", 
      "Nama Pelanggan", // Kolom baru
      "Daftar Barang", 
      "Metode Bayar",   // Kolom baru
      "Subtotal (Rp)", 
      "Nama Voucher", 
      "Diskon Voucher (Rp)", 
      "Potongan Poin (Rp)", 
      "Pajak 11% (Rp)", 
      "Total Bayar (Rp)", 
      "Poin Didapat"
    ];

    // Cek apakah header sudah ada, jika belum (atau jumlah kolom berbeda), buat/update header
    if (sheet.getLastRow() === 0 || sheet.getLastColumn() !== headers.length) {
      if (sheet.getLastRow() > 0) sheet.deleteRow(1); // Hapus header lama jika jumlah kolom berubah
      sheet.insertRowBefore(1);
      sheet.getRange(1, 1, 1, headers.length).setValues([headers]);

      // Styling Header
      const range = sheet.getRange(1, 1, 1, headers.length);
      range.setFontWeight("bold");
      range.setBackground("#5551FF");
      range.setFontColor("white");
      range.setHorizontalAlignment("center");
      sheet.setFrozenRows(1);
    }

    // Parsing data JSON dari App.tsx
    const data = JSON.parse(e.postData.contents);

    // Masukkan data transaksi sesuai urutan header
    sheet.appendRow([
      new Date(),              // Waktu Transaksi
      data.transactionId,      // ID Transaksi
      data.customerType,       // MEMBER / GUEST
      data.customerName,       // Nama Pelanggan (Budi Santoso / Guest)
      data.items,              // Daftar barang (Teks)
      data.paymentMethod,      // QRIS / Cash
      data.subtotal,           // Subtotal
      data.voucherName,        // Nama Voucher
      data.voucherDiscount,    // Diskon Voucher
      data.pointsDiscount,     // Potongan Poin
      data.tax,                // Pajak
      data.totalPaid,          // Total Lunas
      data.pointsEarned        // Cashback Poin
    ]);

    // Format angka mata uang otomatis untuk kolom G sampai L (Subtotal - Total Bayar)
    const lastRow = sheet.getLastRow();
    const currencyRange = sheet.getRange(lastRow, 7, 1, 6);
    currencyRange.setNumberFormat("#,##0");

    // Auto-resize kolom agar rapi
    sheet.autoResizeColumns(1, headers.length);

    return ContentService.createTextOutput(JSON.stringify({ "status": "success" }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({ "status": "error", "message": error.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

