];

const MOCK_MEMBER_POINTS = 12450;
const MOCK_MEMBER_NAME = "Budi Santoso";

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbz57e2ffo0taa89oR5WfGRgtSWLtHPKOshknSl4mouPzRl7EAHyRdt_CBMukbL3X7Tz/exec";

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);
  const [usePoints, setUsePoints] = useState<boolean>(false);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);

  const handleStart = () => setView(ViewState.SELECT_INPUT);

  const handleFinishScanning = () => {
    setCart(INITIAL_CART);
    setView(ViewState.CART);
  };

  const handleMembershipResult = (memberActive: boolean) => {
    setIsMember(memberActive);
    setView(ViewState.SELECT_VOUCHER);
  };

  const handleApplyVoucher = (voucher: Voucher | null) => {
    setSelectedVoucher(voucher);
    setView(ViewState.CART);
  };

  const syncTransaction = async (total: number, tax: number, subtotal: number, discount: number, ptsDisc: number, pointsEarned: number, method: string = "QRIS") => {
    setIsSyncing(true);
    const transactionId = `#VP-${Math.floor(1000 + Math.random() * 9000)}`;

    // Menyiapkan rincian item dalam bentuk array objek agar bisa dipisah tabel di backend
    const itemsDetail = cart.map(item => ({
      name: item.name,
      price: item.price,
      qty: item.quantity,
      total: item.price * item.quantity
    }));

    const data = {
      transactionId,
      customerType: isMember ? 'MEMBER' : 'GUEST',
      customerName: isMember ? MOCK_MEMBER_NAME : "Guest Pelanggan",
      items: itemsDetail, // Sekarang mengirim array objek
      subtotal,
      voucherName: selectedVoucher?.title || "N/A",
      voucherDiscount: discount,
      pointsDiscount: ptsDisc,
      tax,
      totalPaid: total,
      pointsEarned,
      paymentMethod: method
    };

    try {
      await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(data)
      });
    } catch (error) {
      console.error("Gagal mengirim data:", error);
    } finally {
      setTimeout(() => {
        setIsSyncing(false);
        setView(ViewState.SUCCESS);
      }, 1500);
    }
  };

  const calculateDiscount = () => {
    if (!selectedVoucher) return 0;
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return selectedVoucher.discountType === 'PERCENT' 
      ? subtotal * (selectedVoucher.value / 100) 
      : selectedVoucher.value;
  };

  const calculateTotalPoints = () => {
    return cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = item.quantity + delta;
        return newQty >= 1 ? { ...item, quantity: newQty } : item;
      }
      return item;
    }));
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const voucherDiscount = calculateDiscount();
    const pointsDiscount = (isMember && usePoints) ? MOCK_MEMBER_POINTS : 0;
    const totalReduction = Math.min(subtotal, voucherDiscount + pointsDiscount);
    const tax = (subtotal - totalReduction) * 0.11;
    const finalTotal = (subtotal - totalReduction) + tax;
    const newCashback = calculateTotalPoints();

    switch (view) {
      case ViewState.LANDING:
        return <LandingPage onStart={handleStart} />;
      case ViewState.SELECT_INPUT:
        return <SelectInputPage onSelectAI={() => setView(ViewState.SCANNING_AI)} onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)} onBack={() => setView(ViewState.LANDING)} />;
      case ViewState.SCANNING_AI:
        return <ScanningPage onBack={() => setView(ViewState.SELECT_INPUT)} onCapture={handleFinishScanning} />;
      case ViewState.SCANNING_BARCODE:
        return <BarcodeScannerPage onBack={() => setView(ViewState.SELECT_INPUT)} onFinish={handleFinishScanning} />;
      case ViewState.CART:
        return <CartPage cart={cart} isMember={isMember} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} pointsDiscount={pointsDiscount} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onReset={() => { setView(ViewState.LANDING); setIsMember(false); setSelectedVoucher(null); setUsePoints(false); }} onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)} onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)} onConfirm={() => setView(ViewState.PAYMENT_QRIS)} />;
      case ViewState.MEMBERSHIP_SCAN:
        return <MembershipPage onSkip={() => handleMembershipResult(false)} onDetected={() => handleMembershipResult(true)} />;
      case ViewState.SELECT_VOUCHER:
        return <VoucherSelectionPage isMember={isMember} totalPoints={newCashback} usePoints={usePoints} onTogglePoints={setUsePoints} onSelect={handleApplyVoucher} onBack={() => setView(ViewState.CART)} />;
      case ViewState.PAYMENT_QRIS:
        return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => syncTransaction(finalTotal, tax, subtotal, voucherDiscount, pointsDiscount, newCashback, "QRIS")} total={finalTotal} />;
      case ViewState.SUCCESS:
        return <SuccessPage onFinish={() => { setView(ViewState.LANDING); setIsMember(false); setSelectedVoucher(null); setUsePoints(false); }} total={finalTotal} isSyncing={isSyncing} />;
      default:
        return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.SCANNING_AI, ViewState.SCANNING_BARCODE, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

/**
 * VisionPay Multi-Table Sync System v3.0
 */

function doPost(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // Ambil atau buat sheet
  let sheetOrder = ss.getSheetByName("Transactions") || ss.insertSheet("Transactions");
  let sheetDetails = ss.getSheetByName("Transaction_Details") || ss.insertSheet("Transaction_Details");

  try {
    const data = JSON.parse(e.postData.contents);
    const timestamp = new Date();

    // 1. PROSES TABEL TRANSAKSI (RINGKASAN)
    if (sheetOrder.getLastRow() === 0) {
      const hOrder = ["Waktu", "ID Transaksi", "Customer", "Tipe", "Metode", "Subtotal", "Voucher", "Disc Voucher", "Disc Poin", "Pajak", "Total Akhir", "Poin Earned"];
      sheetOrder.appendRow(hOrder);
      styleHeader(sheetOrder, hOrder.length, "#5551FF");
    }

    sheetOrder.appendRow([
      timestamp,
      data.transactionId,
      data.customerName,
      data.customerType,
      data.paymentMethod,
      data.subtotal,
      data.voucherName,
      data.voucherDiscount,
      data.pointsDiscount,
      data.tax,
      data.totalPaid,
      data.pointsEarned
    ]);

    // 2. PROSES TABEL DETAILS (RINCIAN BARANG)
    if (sheetDetails.getLastRow() === 0) {
      const hDetails = ["ID Transaksi", "Nama Barang", "Harga Satuan", "Qty", "Total"];
      sheetDetails.appendRow(hDetails);
      styleHeader(sheetDetails, hDetails.length, "#0F172A");
    }

    // Input setiap barang dalam array ke baris terpisah
    if (data.items && Array.isArray(data.items)) {
      data.items.forEach(function(item) {
        sheetDetails.appendRow([
          data.transactionId,
          item.name,
          item.price,
          item.qty,
          item.total
        ]);
      });
    }

    // Formatting angka di kedua sheet
    sheetOrder.getRange(sheetOrder.getLastRow(), 6, 1, 7).setNumberFormat("#,##0");
    sheetDetails.getRange(sheetDetails.getLastRow() - data.items.length + 1, 3, data.items.length, 3).setNumberFormat("#,##0");

    return ContentService.createTextOutput(JSON.stringify({ "status": "success" }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({ "status": "error", "message": error.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function styleHeader(sheet, colCount, bgColor) {
  const range = sheet.getRange(1, 1, 1, colCount);
  range.setFontWeight("bold").setBackground(bgColor).setFontColor("white").setHorizontalAlignment("center");
  sheet.setFrozenRows(1);
}

function doGet() {
  return HtmlService.createHtmlOutput("VisionPay Multi-Table Active");
}

/**
 * VisionPay Professional Sync System v4.0
 * Includes: Transactions, Details, and Member Database Management
 */

function doPost(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheetOrder = ss.getSheetByName("Transactions") || ss.insertSheet("Transactions");
  const sheetDetails = ss.getSheetByName("Transaction_Details") || ss.insertSheet("Transaction_Details");
  const sheetMembers = ss.getSheetByName("Members") || ss.insertSheet("Members");

  try {
    const data = JSON.parse(e.postData.contents);
    const action = data.action || "SYNC_TRANSACTION";

    // --- ACTION: GET_MEMBER_INFO ---
    if (action === "GET_MEMBER") {
      const memberId = data.memberId;
      const membersData = sheetMembers.getDataRange().getValues();

      // Cari member berdasarkan ID (Kolom A)
      for (let i = 1; i < membersData.length; i++) {
        if (membersData[i][0].toString() === memberId) {
          return ContentService.createTextOutput(JSON.stringify({
            status: "success",
            member: {
              id: membersData[i][0],
              name: membersData[i][1],
              tier: membersData[i][2],
              points: membersData[i][3]
            }
          })).setMimeType(ContentService.MimeType.JSON);
        }
      }
      return ContentService.createTextOutput(JSON.stringify({ status: "error", message: "Member tidak ditemukan" }))
        .setMimeType(ContentService.MimeType.JSON);
    }

    // --- ACTION: SYNC_TRANSACTION ---
    if (action === "SYNC_TRANSACTION") {
      const timestamp = new Date();

      // 1. Inisialisasi Header jika kosong
      if (sheetOrder.getLastRow() === 0) {
        const hOrder = ["Waktu", "ID Transaksi", "ID Member", "Nama", "Tipe", "Metode", "Subtotal", "Disc Voucher", "Disc Poin", "Pajak", "Total Akhir", "Poin Earned"];
        sheetOrder.appendRow(hOrder);
        styleHeader(sheetOrder, hOrder.length, "#5551FF");
      }
      if (sheetDetails.getLastRow() === 0) {
        const hDetails = ["ID Transaksi", "Nama Barang", "Harga Satuan", "Qty", "Total"];
        sheetDetails.appendRow(hDetails);
        styleHeader(sheetDetails, hDetails.length, "#0F172A");
      }
      if (sheetMembers.getLastRow() === 0) {
        const hMembers = ["ID Member", "Nama", "Tier", "Total Poin"];
        sheetMembers.appendRow(hMembers);
        // Tambahkan data awal contoh
        sheetMembers.appendRow(["VP-1001", "Budi Santoso", "Platinum", 15000]);
        sheetMembers.appendRow(["VP-1002", "Siti Aminah", "Gold", 5000]);
        styleHeader(sheetMembers, hMembers.length, "#10B981");
      }

      // 2. Simpan Transaksi Utama
      sheetOrder.appendRow([
        timestamp, data.transactionId, data.memberId || "GUEST",
        data.customerName, data.customerType, data.paymentMethod,
        data.subtotal, data.voucherDiscount, data.pointsDiscount,
        data.tax, data.totalPaid, data.pointsEarned
      ]);

      // 3. Simpan Detail Barang
      if (data.items && Array.isArray(data.items)) {
        data.items.forEach(item => {
          sheetDetails.appendRow([data.transactionId, item.name, item.price, item.qty, item.total]);
        });
      }

      // 4. UPDATE SALDO POIN MEMBER (Jika ada member)
      if (data.customerType === "MEMBER" && data.memberId) {
        const memberRows = sheetMembers.getDataRange().getValues();
        for (let j = 1; j < memberRows.length; j++) {
          if (memberRows[j][0].toString() === data.memberId) {
            const currentPoints = memberRows[j][3];
            const newBalance = currentPoints - (data.pointsDiscount || 0) + (data.pointsEarned || 0);
            sheetMembers.getRange(j + 1, 4).setValue(newBalance);
            break;
          }
        }
      }

      // Formatting
      sheetOrder.getRange(sheetOrder.getLastRow(), 7, 1, 5).setNumberFormat("#,##0");
      sheetDetails.getRange(sheetDetails.getLastRow() - data.items.length + 1, 3, data.items.length, 3).setNumberFormat("#,##0");

      return ContentService.createTextOutput(JSON.stringify({ status: "success" }))
        .setMimeType(ContentService.MimeType.JSON);
    }

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: error.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function styleHeader(sheet, colCount, bgColor) {
  const range = sheet.getRange(1, 1, 1, colCount);
  range.setFontWeight("bold").setBackground(bgColor).setFontColor("white").setHorizontalAlignment("center");
  sheet.setFrozenRows(1);
}

function doGet() {
  return HtmlService.createHtmlOutput("VisionPay Member System Active");
}

import React, { useState } from 'react';
import { ViewState, CartItem, Voucher } from './types';
import LandingPage from './components/LandingPage';
import SelectInputPage from './components/SelectInputPage';
import ScanningPage from './components/ScanningPage';
import BarcodeScannerPage from './components/BarcodeScannerPage';
import CartPage from './components/CartPage';
import MembershipPage from './components/MembershipPage';
import VoucherSelectionPage from './components/VoucherSelectionPage';
import PaymentQRIS from './components/PaymentQRIS';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';

// URL Google App Script Anda
const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbz57e2ffo0taa89oR5WfGRgtSWLtHPKOshknSl4mouPzRl7EAHyRdt_CBMukbL3X7Tz/exec";

interface MemberData {
  id: string;
  name: string;
  tier: string;
  points: number;
}

const INITIAL_CART: CartItem[] = [
  { id: '1', name: 'Tumbler with flower pattern', price: 75000, quantity: 1, points: 350 },
  { id: '2', name: 'Black and white patterned pillow', price: 50000, quantity: 1, points: 150 },
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [memberInfo, setMemberInfo] = useState<MemberData | null>(null);
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);
  const [usePoints, setUsePoints] = useState<boolean>(false);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);
  const [isCheckingMember, setIsCheckingMember] = useState<boolean>(false);

  const handleStart = () => setView(ViewState.SELECT_INPUT);

  const handleFinishScanning = () => {
    setCart(INITIAL_CART);
    setView(ViewState.CART);
  };

  const handleFindMember = async (id: string = "VP-1001") => {
    setIsCheckingMember(true);
    try {
      // Dalam demo ini kita hardcode ID atau bisa dari input scan
      const response = await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors', // Kita gunakan no-cors karena Apps Script sering bermasalah dengan CORS preflight
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: "GET_MEMBER", memberId: id })
      });

      // Catatan: Karena no-cors, kita tidak bisa membaca response JSON secara langsung di browser.
      // Di aplikasi nyata, kita gunakan ID mock jika no-cors, atau proxy.
      // Untuk simulasi ini, kita buat seolah-olah berhasil menemukan Budi.
      setMemberInfo({
        id: id,
        name: "Budi Santoso",
        tier: "Platinum",
        points: 12450
      });
      setIsMember(true);
    } catch (error) {
      console.error("Member check failed", error);
    } finally {
      setIsCheckingMember(false);
      setView(ViewState.SELECT_VOUCHER);
    }
  };

  const handleApplyVoucher = (voucher: Voucher | null) => {
    setSelectedVoucher(voucher);
    setView(ViewState.CART);
  };

  const syncTransaction = async (total: number, tax: number, subtotal: number, discount: number, ptsDisc: number, pointsEarned: number, method: string = "QRIS") => {
    setIsSyncing(true);
    const transactionId = `#VP-${Math.floor(1000 + Math.random() * 9000)}`;

    const itemsDetail = cart.map(item => ({
      name: item.name,
      price: item.price,
      qty: item.quantity,
      total: item.price * item.quantity
    }));

    const data = {
      action: "SYNC_TRANSACTION",
      transactionId,
      memberId: memberInfo?.id || null,
      customerType: isMember ? 'MEMBER' : 'GUEST',
      customerName: isMember ? memberInfo?.name : "Guest Pelanggan",
      items: itemsDetail,
      subtotal,
      voucherDiscount: discount,
      pointsDiscount: ptsDisc,
      tax,
      totalPaid: total,
      pointsEarned,
      paymentMethod: method
    };

    try {
      await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(data)
      });
    } catch (error) {
      console.error("Gagal mengirim data:", error);
    } finally {
      setTimeout(() => {
        setIsSyncing(false);
        setView(ViewState.SUCCESS);
      }, 1500);
    }
  };

  const calculateDiscount = () => {
    if (!selectedVoucher) return 0;
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return selectedVoucher.discountType === 'PERCENT' 
      ? subtotal * (selectedVoucher.value / 100) 
      : selectedVoucher.value;
  };

  const calculateTotalPoints = () => {
    return cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = item.quantity + delta;
        return newQty >= 1 ? { ...item, quantity: newQty } : item;
      }
      return item;
    }));
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const voucherDiscount = calculateDiscount();
    const pointsDiscount = (isMember && usePoints && memberInfo) ? memberInfo.points : 0;
    const totalReduction = Math.min(subtotal, voucherDiscount + pointsDiscount);
    const tax = (subtotal - totalReduction) * 0.11;
    const finalTotal = (subtotal - totalReduction) + tax;
    const newCashback = calculateTotalPoints();

    switch (view) {
      case ViewState.LANDING:
        return <LandingPage onStart={handleStart} />;
      case ViewState.SELECT_INPUT:
        return <SelectInputPage onSelectAI={() => setView(ViewState.SCANNING_AI)} onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)} onBack={() => setView(ViewState.LANDING)} />;
      case ViewState.SCANNING_AI:
        return <ScanningPage onBack={() => setView(ViewState.SELECT_INPUT)} onCapture={handleFinishScanning} />;
      case ViewState.SCANNING_BARCODE:
        return <BarcodeScannerPage onBack={() => setView(ViewState.SELECT_INPUT)} onFinish={handleFinishScanning} />;
      case ViewState.CART:
        return <CartPage cart={cart} isMember={isMember} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} pointsDiscount={pointsDiscount} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onReset={() => { setView(ViewState.LANDING); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); setUsePoints(false); }} onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)} onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)} onConfirm={() => setView(ViewState.PAYMENT_QRIS)} />;
      case ViewState.MEMBERSHIP_SCAN:
        return <MembershipPage onSkip={() => { setIsMember(false); setView(ViewState.SELECT_VOUCHER); }} onDetected={() => handleFindMember("VP-1001")} />;
      case ViewState.SELECT_VOUCHER:
        return <VoucherSelectionPage isMember={isMember} memberData={memberInfo} totalPoints={newCashback} usePoints={usePoints} onTogglePoints={setUsePoints} onSelect={handleApplyVoucher} onBack={() => setView(ViewState.CART)} />;
      case ViewState.PAYMENT_QRIS:
        return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => syncTransaction(finalTotal, tax, subtotal, voucherDiscount, pointsDiscount, newCashback, "QRIS")} total={finalTotal} />;
      case ViewState.SUCCESS:
        return <SuccessPage onFinish={() => { setView(ViewState.LANDING); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); setUsePoints(false); }} total={finalTotal} isSyncing={isSyncing} />;
      default:
        return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.SCANNING_AI, ViewState.SCANNING_BARCODE, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

