          </div>
        </div>

        <div className="flex flex-col gap-4 w-full">
          <button 
            onClick={onDetected}
            disabled={isChecking}
            className="w-full py-5 bg-[#5551FF] hover:bg-[#4440FF] text-white rounded-[32px] font-black text-lg transition-all vision-shadow active:scale-95 flex items-center justify-center gap-3 disabled:opacity-50"
          >
            {isChecking ? 'Mencocokkan...' : 'Simulasi Scan Member'}
            {!isChecking && <ArrowRight size={20} />}
          </button>

          <button 
            onClick={onSkip}
            disabled={isChecking}
            className="w-full py-5 bg-white/5 hover:bg-white/10 text-slate-400 rounded-[32px] font-bold transition-all flex items-center justify-center gap-2 disabled:opacity-30"
          >
            <X size={18} />
            Tidak Punya Member / Skip
          </button>
        </div>
      </div>
    </div>
  );
};

