function doPost(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheetOrder = ss.getSheetByName("Transactions") || ss.insertSheet("Transactions");
  const sheetDetails = ss.getSheetByName("Transaction_Details") || ss.insertSheet("Transaction_Details");
  const sheetMembers = ss.getSheetByName("Members") || ss.insertSheet("Members");

  try {
    const data = JSON.parse(e.postData.contents);
    const action = data.action || "SYNC_TRANSACTION";

    // --- ACTION: GET_MEMBER_INFO ---
    if (action === "GET_MEMBER") {
      const memberId = data.memberId;
      const membersData = sheetMembers.getDataRange().getValues();

      for (let i = 1; i < membersData.length; i++) {
