import React, { useState } from 'react';
import { ViewState, CartItem, Voucher } from './types';
import LandingPage from './components/LandingPage';
import SelectInputPage from './components/SelectInputPage';
import ScanningPage from './components/ScanningPage';
import BarcodeScannerPage from './components/BarcodeScannerPage';
import CartPage from './components/CartPage';
import MembershipPage from './components/MembershipPage';
import VoucherSelectionPage from './components/VoucherSelectionPage';
import PaymentQRIS from './components/PaymentQRIS';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';

// PASTIKAN URL INI SAMA DENGAN URL DEPLOYMENT APPS SCRIPT ANDA
const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbz57e2ffo0taa89oR5WfGRgtSWLtHPKOshknSl4mouPzRl7EAHyRdt_CBMukbL3X7Tz/exec";

interface MemberData {
  id: string;
  name: string;
  tier: string;
  points: number;
}

const INITIAL_CART: CartItem[] = [
  { id: '1', name: 'Tumbler with flower pattern', price: 75000, quantity: 1, points: 350 },
  { id: '2', name: 'Black and white patterned pillow', price: 50000, quantity: 1, points: 150 },
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [memberInfo, setMemberInfo] = useState<MemberData | null>(null);
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);
  const [usePoints, setUsePoints] = useState<boolean>(false);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);
  const [isCheckingMember, setIsCheckingMember] = useState<boolean>(false);

  const handleStart = () => setView(ViewState.SELECT_INPUT);

  const handleFinishScanning = () => {
    setCart(INITIAL_CART);
    setView(ViewState.CART);
  };

  const handleFindMember = async (id: string = "VP-1001") => {
    setIsCheckingMember(true);

    // Simulasi delay pengecekan
    setTimeout(async () => {
      try {
        // Cek ke Google Sheets (Opsional: Member tetap bisa lanjut meski fetch gagal)
        fetch(GOOGLE_SHEET_WEBAPP_URL, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'text/plain' },
          body: JSON.stringify({ action: "GET_MEMBER", memberId: id })
        });

        setMemberInfo({
          id: id,
          name: "Budi Santoso",
          tier: "Platinum",
          points: 12450
        });
        setIsMember(true);
      } catch (error) {
        console.error("Member check error", error);
      } finally {
        setIsCheckingMember(false);
        setView(ViewState.SELECT_VOUCHER);
      }
    }, 800);
  };

  const handleApplyVoucher = (voucher: Voucher | null) => {
    setSelectedVoucher(voucher);
  };

  const syncTransaction = async (total: number, tax: number, subtotal: number, discount: number, ptsDisc: number, pointsEarned: number, method: string = "QRIS") => {
    setIsSyncing(true);
    const transactionId = `VP-${Math.floor(1000 + Math.random() * 9000)}`;

    // Data untuk sheet 'Orders'
    const itemsSummary = cart.map(item => `${item.name} x${item.quantity}`).join(', ');

    // Data untuk sheet 'Transaction_Details'
    const itemsDetail = cart.map(item => ({
      name: item.name,
      price: item.price,
      qty: item.quantity,
      total: item.price * item.quantity
    }));

    const payload = {
      action: "SYNC_TRANSACTION",
      transactionId,
      memberId: memberInfo?.id || null,
      customerType: isMember ? 'MEMBER' : 'GUEST',
      customerName: isMember ? memberInfo?.name : "Pelanggan Guest",
      itemsSummary: itemsSummary,
      items: itemsDetail, 
      subtotal,
      voucherDiscount: discount,
      pointsDiscount: ptsDisc,
      tax,
      totalPaid: total,
      pointsEarned,
      paymentMethod: method
    };

    try {
      await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });
    } catch (error) {
      console.error("Sync Error:", error);
    } finally {
      // Berikan waktu sedikit agar animasi terlihat
      setTimeout(() => {
        setIsSyncing(false);
        setView(ViewState.SUCCESS);
      }, 1500);
    }
  };

  const calculateDiscount = () => {
    if (!selectedVoucher) return 0;
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return selectedVoucher.discountType === 'PERCENT' 
      ? subtotal * (selectedVoucher.value / 100) 
      : selectedVoucher.value;
  };

  const calculateTotalPoints = () => {
    return cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = item.quantity + delta;
        return newQty >= 1 ? { ...item, quantity: newQty } : item;
      }
      return item;
    }));
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const voucherDiscount = calculateDiscount();
    const pointsDiscount = (isMember && usePoints && memberInfo) ? memberInfo.points : 0;
    const totalReduction = Math.min(subtotal, voucherDiscount + pointsDiscount);
    const tax = Math.max(0, (subtotal - totalReduction) * 0.11);
    const finalTotal = Math.max(0, (subtotal - totalReduction) + tax);
    const newCashback = calculateTotalPoints();

    switch (view) {
      case ViewState.LANDING:
        return <LandingPage onStart={handleStart} />;
      case ViewState.SELECT_INPUT:
        return <SelectInputPage onSelectAI={() => setView(ViewState.SCANNING_AI)} onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)} onBack={() => setView(ViewState.LANDING)} />;
      case ViewState.SCANNING_AI:
        return <ScanningPage onBack={() => setView(ViewState.SELECT_INPUT)} onCapture={handleFinishScanning} />;
      case ViewState.SCANNING_BARCODE:
        return <BarcodeScannerPage onBack={() => setView(ViewState.SELECT_INPUT)} onFinish={handleFinishScanning} />;
      case ViewState.CART:
        return <CartPage cart={cart} isMember={isMember} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} pointsDiscount={pointsDiscount} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onReset={() => { setView(ViewState.LANDING); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); setUsePoints(false); }} onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)} onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)} onConfirm={() => setView(ViewState.PAYMENT_QRIS)} />;
      case ViewState.MEMBERSHIP_SCAN:
        return <MembershipPage isChecking={isCheckingMember} onSkip={() => { setIsMember(false); setView(ViewState.SELECT_VOUCHER); }} onDetected={() => handleFindMember("VP-1001")} />;
      case ViewState.SELECT_VOUCHER:
        return <VoucherSelectionPage isMember={isMember} memberData={memberInfo} totalPoints={newCashback} usePoints={usePoints} selectedVoucherId={selectedVoucher?.id} onTogglePoints={setUsePoints} onSelect={handleApplyVoucher} onBack={() => setView(ViewState.CART)} />;
      case ViewState.PAYMENT_QRIS:
        return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => syncTransaction(finalTotal, tax, subtotal, voucherDiscount, pointsDiscount, newCashback, "QRIS")} total={finalTotal} />;
      case ViewState.SUCCESS:
        return <SuccessPage onFinish={() => { setView(ViewState.LANDING); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); setUsePoints(false); }} total={finalTotal} isSyncing={isSyncing} />;
      default:
        return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.SCANNING_AI, ViewState.SCANNING_BARCODE, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

