      case ViewState.SELECT_INPUT:
        return <SelectInputPage onSelectAI={() => setView(ViewState.SCANNING_AI)} onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)} onBack={() => setView(ViewState.LANDING)} />;
      case ViewState.SCANNING_AI:
