      case ViewState.SCANNING_BARCODE:
        return <BarcodeScannerPage onBack={() => setView(ViewState.SELECT_INPUT)} onFinish={handleFinishScanning} />;
      case ViewState.CART:
        return <CartPage cart={cart} isMember={isMember} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} pointsDiscount={pointsDiscount} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onReset={() => { setView(ViewState.LANDING); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); setUsePoints(false); }} onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)} onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)} onConfirm={() => setView(ViewState.PAYMENT_QRIS)} />;
      case ViewState.MEMBERSHIP_SCAN:
        return <MembershipPage isChecking={isCheckingMember} onSkip={() => { setIsMember(false); setView(ViewState.SELECT_VOUCHER); }} onDetected={() => handleFindMember("VP-1001")} />;
      case ViewState.SELECT_VOUCHER:
        return <VoucherSelectionPage isMember={isMember} memberData={memberInfo} totalPoints={newCashback} usePoints={usePoints} selectedVoucherId={selectedVoucher?.id} onTogglePoints={setUsePoints} onSelect={handleApplyVoucher} onBack={() => setView(ViewState.CART)} />;
      case ViewState.PAYMENT_QRIS:
