      case ViewState.SUCCESS:
        return <SuccessPage onFinish={() => { setView(ViewState.LANDING); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); setUsePoints(false); }} total={finalTotal} isSyncing={isSyncing} />;
      default:
        return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.SCANNING_AI, ViewState.SCANNING_BARCODE, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

