import React, { useState } from 'react';
import { ViewState, CartItem, Voucher, Product } from './types';
import LandingPage from './components/LandingPage';
import SelectInputPage from './components/SelectInputPage';
import ScanningPage from './components/ScanningPage';
import BarcodeScannerPage from './components/BarcodeScannerPage';
import CartPage from './components/CartPage';
import MembershipPage from './components/MembershipPage';
import VoucherSelectionPage from './components/VoucherSelectionPage';
import PaymentQRIS from './components/PaymentQRIS';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';
import CashierPOS from './components/CashierPOS';

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

interface MemberData {
  id: string;
  name: string;
  tier: string;
  points: number;
}

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.POS); // Langsung ke POS sebagai default kasir
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [memberInfo, setMemberInfo] = useState<MemberData | null>(null);
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);
  const [usePoints, setUsePoints] = useState<boolean>(false);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);
  const [isCheckingMember, setIsCheckingMember] = useState<boolean>(false);

  const handleStart = () => setView(ViewState.POS);

  const handleAddToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) {
        return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { id: product.id, name: product.name, price: product.price, quantity: 1, points: product.points }];
    });
  };

  const handleFinishScanning = (items: CartItem[]) => {
    // Gabungkan item hasil scan ke keranjang yang sudah ada
    setCart(prev => {
      let newCart = [...prev];
      items.forEach(item => {
        const existing = newCart.find(i => i.id === item.id);
        if (existing) {
          existing.quantity += item.quantity;
        } else {
          newCart.push(item);
        }
      });
      return newCart;
    });
    setView(ViewState.POS);
  };

  const handleFindMember = async (id: string = "VP-1001") => {
    setIsCheckingMember(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      setMemberInfo({ id, name: "Budi Santoso", tier: "Platinum", points: 12450 });
      setIsMember(true);
      setView(ViewState.SELECT_VOUCHER);
    } catch (error) {
      console.error(error);
    } finally {
      setIsCheckingMember(false);
    }
  };

  const syncTransaction = async (total: number, tax: number, subtotal: number, discount: number, ptsDisc: number, pointsEarned: number, method: string = "QRIS") => {
    setIsSyncing(true);
    const transactionId = `VP-${Math.floor(1000 + Math.random() * 9000)}`;
    const itemsSummary = cart.map(item => `${item.name} (${item.quantity}x)`).join(', ');
    const itemsDetail = cart.map(item => ({ 
      name: item.name, 
      price: item.price, 
      qty: item.quantity, 
      total: item.price * item.quantity 
    }));

    const payload = {
      action: "SYNC_TRANSACTION",
      transactionId,
      memberId: memberInfo?.id || "",
      customerType: isMember ? 'MEMBER' : 'GUEST',
      customerName: isMember ? memberInfo?.name : "Pelanggan Guest",
      itemsSummary,
      items: itemsDetail,
      subtotal,
      voucherName: selectedVoucher?.title || "-",
      voucherDiscount: discount,
      pointsDiscount: ptsDisc,
      tax,
      totalPaid: total,
      pointsEarned,
      paymentMethod: method
    };

    try {
      await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });
    } catch (error) {
      console.error("Sync Error:", error);
    } finally {
      setTimeout(() => {
        setIsSyncing(false);
        setView(ViewState.SUCCESS);
      }, 1000);
    }
  };

  const calculateDiscount = () => {
    if (!selectedVoucher) return 0;
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return selectedVoucher.discountType === 'PERCENT' ? subtotal * (selectedVoucher.value / 100) : selectedVoucher.value;
  };

  const calculateTotalPoints = () => cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(1, item.quantity + delta) } : item).filter(item => item.quantity > 0));
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const voucherDiscount = calculateDiscount();
    const pointsDiscount = (isMember && usePoints && memberInfo) ? memberInfo.points : 0;
    const totalReduction = Math.min(subtotal, voucherDiscount + pointsDiscount);
    const tax = Math.max(0, (subtotal - totalReduction) * 0.11);
    const finalTotal = Math.max(0, (subtotal - totalReduction) + tax);
    const newCashback = calculateTotalPoints();

    switch (view) {
      case ViewState.POS: return (
        <CashierPOS 
          cart={cart} 
          onAddToCart={handleAddToCart}
          onUpdateQuantity={handleUpdateQuantity}
          onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))}
          onScanAI={() => setView(ViewState.SCANNING_AI)}
          onCheckout={() => setView(ViewState.CART)}
          isMember={isMember}
          memberInfo={memberInfo}
          selectedVoucher={selectedVoucher}
          discountAmount={voucherDiscount}
        />
      );
      case ViewState.LANDING: return <LandingPage onStart={handleStart} />;
      case ViewState.SELECT_INPUT: return <SelectInputPage onSelectAI={() => setView(ViewState.SCANNING_AI)} onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)} onBack={() => setView(ViewState.POS)} />;
      case ViewState.SCANNING_AI: return <ScanningPage onBack={() => setView(ViewState.POS)} onCapture={handleFinishScanning} />;
      case ViewState.CART: return <CartPage cart={cart} isMember={isMember} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} pointsDiscount={pointsDiscount} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onReset={() => setView(ViewState.POS)} onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)} onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)} onConfirm={() => setView(ViewState.PAYMENT_QRIS)} />;
      case ViewState.MEMBERSHIP_SCAN: return <MembershipPage isChecking={isCheckingMember} onSkip={() => setView(ViewState.SELECT_VOUCHER)} onDetected={() => handleFindMember()} />;
      case ViewState.SELECT_VOUCHER: return <VoucherSelectionPage isMember={isMember} memberData={memberInfo} totalPoints={newCashback} usePoints={usePoints} selectedVoucherId={selectedVoucher?.id} onTogglePoints={setUsePoints} onSelect={setSelectedVoucher} onBack={() => setView(ViewState.POS)} />;
      case ViewState.PAYMENT_QRIS: return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => syncTransaction(finalTotal, tax, subtotal, voucherDiscount, pointsDiscount, newCashback, "QRIS")} total={finalTotal} />;
      case ViewState.SUCCESS: return <SuccessPage onFinish={() => { setCart([]); setView(ViewState.POS); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); }} total={finalTotal} isSyncing={isSyncing} />;
      default: return <CashierPOS cart={cart} onAddToCart={handleAddToCart} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onScanAI={() => setView(ViewState.SCANNING_AI)} onCheckout={() => setView(ViewState.CART)} isMember={isMember} memberInfo={memberInfo} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.SCANNING_AI, ViewState.SCANNING_BARCODE, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS].includes(view)}>
        <div className="w-full flex justify-center pt-8">
          {renderView()}
        </div>
      </Layout>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { Camera, Sparkles, ShoppingCart, Trash2, CreditCard, Loader2, BrainCircuit, Scan, ShieldCheck, Info } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { CartItem, Product } from '../types';

interface VisionPOSProps {
  onCheckout: (items: CartItem[]) => void;
  onBack: () => void;
}

const PRODUCT_CATALOG = `
  1. Tumbler Flower - ID: 1 - Harga: 75000 - Poin: 350
  2. Patterned Pillow - ID: 2 - Harga: 50000 - Poin: 150
  3. Stainless Fork - ID: 3 - Harga: 15000 - Poin: 50
  4. Coffee Mug - ID: 4 - Harga: 35000 - Poin: 100
`;

const VisionPOS: React.FC<VisionPOSProps> = ({ onCheckout, onBack }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [lastDetected, setLastDetected] = useState<string>("");

  useEffect(() => {
    async function startCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: 1920, height: 1080 } 
        });
        setStream(s);
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        console.error("Camera access failed", err);
      }
    }
    startCamera();
    return () => stream?.getTracks().forEach(t => t.stop());
  }, []);

  const analyzeFrame = async () => {
    if (!videoRef.current || !canvasRef.current || isAnalyzing) return;

    setIsAnalyzing(true);
    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.drawImage(video, 0, 0);

    const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: `Identify items from this catalog: ${PRODUCT_CATALOG}. 
                       Return ONLY a JSON array: [{"id": "...", "name": "...", "price": 0, "quantity": 1, "points": 0}]. 
                       If multiple items seen, list all. If none, return [].` }
            ]
          }
        ],
        config: { responseMimeType: "application/json" }
      });

      const detected: CartItem[] = JSON.parse(response.text || "[]");
      if (detected.length > 0) {
        setCart(prev => {
          let updated = [...prev];
          detected.forEach(item => {
            const idx = updated.findIndex(i => i.id === item.id);
            if (idx > -1) updated[idx].quantity += 1;
            else updated.push(item);
          });
          return updated;
        });
        setLastDetected(detected.map(d => d.name).join(", "));
      }
    } catch (error) {
      console.error("AI Error:", error);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  return (
    <div className="fixed inset-0 bg-slate-950 flex overflow-hidden font-['Plus_Jakarta_Sans']">
      <canvas ref={canvasRef} className="hidden" />

      {/* Left: AI VISION HUB */}
      <div className="flex-1 relative flex flex-col">
        {/* Camera Feed */}
        <video 
          ref={videoRef} 
          autoPlay 
          playsInline 
          className="absolute inset-0 w-full h-full object-cover opacity-60" 
        />

        {/* HUD OVERLAY */}
        <div className="absolute inset-0 pointer-events-none border-[20px] border-slate-950/20">
          <div className="absolute top-10 left-10 flex items-center gap-4">
             <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center vision-shadow animate-pulse">
                <BrainCircuit className="text-white" size={24} />
             </div>
             <div>
                <h1 className="text-white font-black text-xl tracking-tighter uppercase">Gemini Vision 3.0</h1>
                <p className="text-blue-400 text-[10px] font-bold tracking-[0.3em] uppercase">Neural Engine Active</p>
             </div>
          </div>

          {/* Targeting Brackets */}
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 border-2 border-blue-500/30 rounded-full animate-ping opacity-20" />
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[400px] h-[400px]">
             <div className="absolute top-0 left-0 w-16 h-16 border-t-4 border-l-4 border-blue-500 rounded-tl-3xl" />
             <div className="absolute top-0 right-0 w-16 h-16 border-t-4 border-r-4 border-blue-500 rounded-tr-3xl" />
             <div className="absolute bottom-0 left-0 w-16 h-16 border-b-4 border-l-4 border-blue-500 rounded-bl-3xl" />
             <div className="absolute bottom-0 right-0 w-16 h-16 border-b-4 border-r-4 border-blue-500 rounded-br-3xl" />
          </div>

          <div className="scan-line" />
        </div>

        {/* Bottom Controls */}
        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex flex-col items-center gap-6 z-20">
          {lastDetected && (
            <div className="bg-green-500/20 backdrop-blur-xl border border-green-500/50 px-6 py-2 rounded-full flex items-center gap-3 animate-bounce">
              <ShieldCheck className="text-green-400" size={16} />
              <span className="text-green-400 font-black text-[10px] uppercase tracking-widest">Terdeteksi: {lastDetected}</span>
            </div>
          )}

          <button 
            onClick={analyzeFrame}
            disabled={isAnalyzing}
            className={`w-28 h-28 rounded-full flex items-center justify-center transition-all active:scale-90
              ${isAnalyzing ? 'bg-slate-800' : 'bg-blue-600 hover:bg-blue-500 vision-shadow ring-8 ring-blue-600/20'}
            `}
          >
            {isAnalyzing ? (
              <Loader2 className="text-white animate-spin" size={40} />
            ) : (
              <Scan className="text-white" size={40} />
            )}
          </button>

          <span className="text-white/40 text-[10px] font-black uppercase tracking-[0.4em]">
            {isAnalyzing ? 'Menganalisis...' : 'Ketuk untuk Scan AI'}
          </span>
        </div>
      </div>

      {/* Right: FLOATING CART PANEL */}
      <div className="w-[450px] bg-slate-950/40 backdrop-blur-3xl border-l border-white/10 flex flex-col z-30">
        <div className="p-8 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center text-blue-400">
              <ShoppingCart size={20} />
            </div>
            <h2 className="text-white font-black text-xl tracking-tight">AI Basket</h2>
          </div>
          <button onClick={onBack} className="text-white/30 hover:text-white transition-colors">
            <Info size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-4 opacity-20">
              <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center">
                <Sparkles size={32} className="text-white" />
              </div>
              <p className="text-white text-xs font-black uppercase tracking-widest">Siap Deteksi Barang</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="bg-white/5 border border-white/5 p-5 rounded-3xl flex items-center gap-4 group transition-all hover:bg-white/10">
                <div className="flex-1">
                  <h4 className="text-white font-bold text-sm">{item.name}</h4>
                  <p className="text-blue-400 font-black text-xs mt-1">Rp {item.price.toLocaleString('id-ID')}</p>
                </div>
                <div className="flex items-center gap-3 bg-white/5 rounded-xl px-2 py-1">
                  <span className="text-white font-black text-sm">{item.quantity}x</span>
                </div>
                <button 
                  onClick={() => setCart(prev => prev.filter(i => i.id !== item.id))}
                  className="text-white/10 group-hover:text-red-500 transition-colors"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))
          )}
        </div>

        <div className="p-8 bg-black/40 border-t border-white/5">
          <div className="flex justify-between items-end mb-8">
             <div>
                <p className="text-white/40 text-[10px] font-black uppercase tracking-widest mb-1">Total Bill</p>
                <p className="text-white font-black text-3xl">Rp {subtotal.toLocaleString('id-ID')}</p>
             </div>
             <div className="text-right">
                <p className="text-blue-500 text-[9px] font-black uppercase tracking-widest">Points Earned</p>
                <p className="text-white font-bold">+{cart.reduce((s, i) => s + (i.points || 0), 0)}</p>
             </div>
          </div>

          <button 
            disabled={cart.length === 0}
            onClick={() => onCheckout(cart)}
            className="w-full py-6 bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 disabled:text-slate-500 text-white rounded-[32px] font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-blue-600/20 flex items-center justify-center gap-3 active:scale-95"
          >
            <CreditCard size={18} />
            Selesaikan Transaksi
          </button>
        </div>
      </div>
    </div>
  );
};

