import React, { useState } from 'react';
import { ViewState, CartItem, Voucher } from './types';
import LandingPage from './components/LandingPage';
import VisionPOS from './components/VisionPOS';
import CartPage from './components/CartPage';
import MembershipPage from './components/MembershipPage';
import VoucherSelectionPage from './components/VoucherSelectionPage';
import PaymentQRIS from './components/PaymentQRIS';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

interface MemberData {
  id: string;
  name: string;
  tier: string;
  points: number;
}

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [memberInfo, setMemberInfo] = useState<MemberData | null>(null);
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);
  const [usePoints, setUsePoints] = useState<boolean>(false);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);
  const [isCheckingMember, setIsCheckingMember] = useState<boolean>(false);

  const handleStart = () => setView(ViewState.POS);

  const handleFinishVisionScan = (items: CartItem[]) => {
    setCart(items);
    setView(ViewState.CART);
  };

  const handleFindMember = async (id: string = "VP-1001") => {
    setIsCheckingMember(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      setMemberInfo({ id, name: "Budi Santoso", tier: "Platinum", points: 12450 });
      setIsMember(true);
      setView(ViewState.SELECT_VOUCHER);
    } catch (error) {
      console.error(error);
    } finally {
      setIsCheckingMember(false);
    }
  };

  const syncTransaction = async (total: number, tax: number, subtotal: number, discount: number, ptsDisc: number, pointsEarned: number, method: string = "QRIS") => {
    setIsSyncing(true);
    const transactionId = `VP-${Math.floor(1000 + Math.random() * 9000)}`;
    const itemsSummary = cart.map(item => `${item.name} (${item.quantity}x)`).join(', ');
    const itemsDetail = cart.map(item => ({ 
      name: item.name, 
      price: item.price, 
      qty: item.quantity, 
      total: item.price * item.quantity 
    }));

    const payload = {
      action: "SYNC_TRANSACTION",
      transactionId,
      memberId: memberInfo?.id || "",
      customerType: isMember ? 'MEMBER' : 'GUEST',
      customerName: isMember ? memberInfo?.name : "Pelanggan Guest",
      itemsSummary,
      items: itemsDetail,
      subtotal,
      voucherName: selectedVoucher?.title || "-",
      voucherDiscount: discount,
      pointsDiscount: ptsDisc,
      tax,
      totalPaid: total,
      pointsEarned,
      paymentMethod: method
    };

    try {
      await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });
    } catch (error) {
      console.error("Sync Error:", error);
    } finally {
      setTimeout(() => {
        setIsSyncing(false);
        setView(ViewState.SUCCESS);
      }, 1000);
    }
  };

  const calculateDiscount = () => {
    if (!selectedVoucher) return 0;
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return selectedVoucher.discountType === 'PERCENT' ? subtotal * (selectedVoucher.value / 100) : selectedVoucher.value;
  };

  const calculateTotalPoints = () => cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(1, item.quantity + delta) } : item).filter(item => item.quantity > 0));
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const voucherDiscount = calculateDiscount();
    const pointsDiscount = (isMember && usePoints && memberInfo) ? memberInfo.points : 0;
    const totalReduction = Math.min(subtotal, voucherDiscount + pointsDiscount);
    const tax = Math.max(0, (subtotal - totalReduction) * 0.11);
    const finalTotal = Math.max(0, (subtotal - totalReduction) + tax);
    const newCashback = calculateTotalPoints();

    switch (view) {
      case ViewState.LANDING: return <LandingPage onStart={handleStart} />;
      case ViewState.POS: return <VisionPOS onBack={() => setView(ViewState.LANDING)} onCheckout={handleFinishVisionScan} />;
      case ViewState.CART: return <CartPage cart={cart} isMember={isMember} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} pointsDiscount={pointsDiscount} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onReset={() => setView(ViewState.LANDING)} onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)} onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)} onConfirm={() => setView(ViewState.PAYMENT_QRIS)} />;
      case ViewState.MEMBERSHIP_SCAN: return <MembershipPage isChecking={isCheckingMember} onSkip={() => setView(ViewState.SELECT_VOUCHER)} onDetected={() => handleFindMember()} />;
      case ViewState.SELECT_VOUCHER: return <VoucherSelectionPage isMember={isMember} memberData={memberInfo} totalPoints={newCashback} usePoints={usePoints} selectedVoucherId={selectedVoucher?.id} onTogglePoints={setUsePoints} onSelect={setSelectedVoucher} onBack={() => setView(ViewState.CART)} />;
      case ViewState.PAYMENT_QRIS: return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => syncTransaction(finalTotal, tax, subtotal, voucherDiscount, pointsDiscount, newCashback, "QRIS")} total={finalTotal} />;
      case ViewState.SUCCESS: return <SuccessPage onFinish={() => { setCart([]); setView(ViewState.LANDING); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); }} total={finalTotal} isSyncing={isSyncing} />;
      default: return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617]">
      <Layout hideHeaderFooter={[ViewState.POS, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { Camera, Sparkles, ShoppingCart, Trash2, CreditCard, Loader2, BrainCircuit, Scan, ShieldCheck, Info, X } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { CartItem, Product } from '../types';

interface VisionPOSProps {
  onCheckout: (items: CartItem[]) => void;
  onBack: () => void;
}

const PRODUCT_CATALOG = `
  1. Tumbler Flower - ID: 1 - Harga: 75000 - Poin: 350
  2. Patterned Pillow - ID: 2 - Harga: 50000 - Poin: 150
  3. Stainless Fork - ID: 3 - Harga: 15000 - Poin: 50
  4. Coffee Mug - ID: 4 - Harga: 35000 - Poin: 100
`;

const VisionPOS: React.FC<VisionPOSProps> = ({ onCheckout, onBack }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [lastDetected, setLastDetected] = useState<string>("");

  useEffect(() => {
    async function startCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: 1920, height: 1080 } 
        });
        setStream(s);
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        console.error("Camera access failed", err);
      }
    }
    startCamera();
    return () => stream?.getTracks().forEach(t => t.stop());
  }, []);

  const analyzeFrame = async () => {
    if (!videoRef.current || !canvasRef.current || isAnalyzing) return;

    setIsAnalyzing(true);
    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.drawImage(video, 0, 0);

    const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: `Identify items from this catalog: ${PRODUCT_CATALOG}. 
                       Return ONLY a JSON array: [{"id": "...", "name": "...", "price": 0, "quantity": 1, "points": 0}]. 
                       If multiple items seen, list all. If none, return [].` }
            ]
          }
        ],
        config: { responseMimeType: "application/json" }
      });

      const detected: CartItem[] = JSON.parse(response.text || "[]");
      if (detected.length > 0) {
        setCart(prev => {
          let updated = [...prev];
          detected.forEach(item => {
            const idx = updated.findIndex(i => i.id === item.id);
            if (idx > -1) updated[idx].quantity += 1;
            else updated.push(item);
          });
          return updated;
        });
        setLastDetected(detected.map(d => d.name).join(", "));
        setTimeout(() => setLastDetected(""), 3000);
      }
    } catch (error) {
      console.error("AI Error:", error);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  return (
    <div className="fixed inset-0 bg-[#F8FAFC] flex overflow-hidden font-['Plus_Jakarta_Sans']">
      <canvas ref={canvasRef} className="hidden" />

      {/* Left: AI VISION HUB */}
      <div className="flex-1 relative flex flex-col bg-white">
        {/* Camera Feed */}
        <video 
          ref={videoRef} 
          autoPlay 
          playsInline 
          className="absolute inset-0 w-full h-full object-cover opacity-90" 
        />

        {/* HUD OVERLAY */}
        <div className="absolute inset-0 pointer-events-none border-[24px] border-white/40">
          <div className="absolute top-10 left-10 flex items-center gap-4 bg-white/80 backdrop-blur-md p-4 rounded-[24px] shadow-sm border border-slate-100">
             <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center vision-shadow">
                <BrainCircuit className="text-white" size={24} />
             </div>
             <div>
                <h1 className="text-slate-900 font-black text-xl tracking-tighter uppercase leading-none">Vision AI Hub</h1>
                <p className="text-blue-600 text-[10px] font-black tracking-[0.2em] uppercase mt-1">Gemini Pro Active</p>
             </div>
          </div>

          {/* Targeting Brackets */}
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[450px] h-[450px]">
             <div className="absolute top-0 left-0 w-20 h-20 border-t-[6px] border-l-[6px] border-blue-600 rounded-tl-[40px]" />
             <div className="absolute top-0 right-0 w-20 h-20 border-t-[6px] border-r-[6px] border-blue-600 rounded-tr-[40px]" />
             <div className="absolute bottom-0 left-0 w-20 h-20 border-b-[6px] border-l-[6px] border-blue-600 rounded-bl-[40px]" />
             <div className="absolute bottom-0 right-0 w-20 h-20 border-b-[6px] border-r-[6px] border-blue-600 rounded-br-[40px]" />

             {/* Center Reticle */}
             <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 border-2 border-blue-600 rounded-full animate-ping" />
          </div>

          <div className="scan-line !bg-blue-600/50" />
        </div>

        {/* Back Button */}
        <button 
          onClick={onBack}
          className="absolute top-10 right-10 w-12 h-12 bg-white/80 backdrop-blur-md rounded-2xl flex items-center justify-center text-slate-400 hover:text-red-500 transition-all shadow-sm border border-slate-100 pointer-events-auto"
        >
          <X size={24} />
        </button>

        {/* Bottom Controls */}
        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex flex-col items-center gap-6 z-20 w-full px-12">
          {lastDetected && (
            <div className="bg-green-50 text-green-600 border border-green-200 px-8 py-3 rounded-full flex items-center gap-3 animate-in slide-in-from-bottom duration-300 shadow-xl shadow-green-500/10">
              <ShieldCheck size={20} />
              <span className="font-black text-xs uppercase tracking-widest">Berhasil Menambahkan: {lastDetected}</span>
            </div>
          )}

          <div className="flex items-center gap-8">
            <button 
              onClick={analyzeFrame}
              disabled={isAnalyzing}
              className={`w-28 h-28 rounded-full flex items-center justify-center transition-all active:scale-95 shadow-2xl
                ${isAnalyzing ? 'bg-slate-200 text-slate-400' : 'bg-blue-600 hover:bg-blue-700 text-white vision-shadow ring-[12px] ring-blue-600/10'}
              `}
            >
              {isAnalyzing ? (
                <Loader2 className="animate-spin" size={40} />
              ) : (
                <Scan size={44} />
              )}
            </button>
          </div>

          <div className="bg-white/90 backdrop-blur-md px-8 py-2.5 rounded-full shadow-sm border border-slate-100">
             <span className="text-slate-500 text-[11px] font-black uppercase tracking-[0.3em]">
               {isAnalyzing ? 'Sedang Memproses...' : 'Arahkan & Ketuk Untuk Scan'}
             </span>
          </div>
        </div>
      </div>

      {/* Right: FLOATING CART PANEL */}
      <div className="w-[480px] bg-white flex flex-col z-30 shadow-[-20px_0_50px_rgba(0,0,0,0.02)] border-l border-slate-100">
        <div className="p-10 border-b border-slate-50 flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-blue-50 rounded-2xl flex items-center justify-center text-blue-600">
              <ShoppingCart size={24} />
            </div>
            <div>
               <h2 className="text-slate-900 font-black text-2xl tracking-tight">Keranjang AI</h2>
               <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Sistem Kasir Otomatis</p>
            </div>
          </div>
          <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-4 py-1.5 rounded-full uppercase tracking-widest">
            {cart.length} ITEM
          </span>
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-6">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-6">
              <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center">
                <Sparkles size={40} className="text-slate-200" />
              </div>
              <div className="space-y-2">
                <p className="text-slate-900 font-black text-sm uppercase tracking-widest">Siap Deteksi</p>
                <p className="text-slate-400 text-xs max-w-[200px] leading-relaxed">Letakkan belanjaan Anda di depan kamera untuk memulai.</p>
              </div>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="bg-slate-50 border border-slate-100 p-6 rounded-[32px] flex items-center gap-5 group transition-all hover:bg-white hover:shadow-xl hover:shadow-slate-200/50 hover:border-blue-100">
                <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center text-blue-600 shadow-sm">
                   <Scan size={24} />
                </div>
                <div className="flex-1">
                  <h4 className="text-slate-900 font-black text-sm leading-tight">{item.name}</h4>
                  <div className="flex items-center gap-2 mt-1">
                     <span className="text-blue-600 font-black text-xs">Rp {item.price.toLocaleString('id-ID')}</span>
                     <span className="text-slate-300 text-[10px]">•</span>
                     <span className="text-slate-400 font-bold text-[10px] uppercase">Qty: {item.quantity}</span>
                  </div>
                </div>
                <button 
                  onClick={() => setCart(prev => prev.filter(i => i.id !== item.id))}
                  className="w-10 h-10 rounded-full flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 transition-all"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            ))
          )}
        </div>

        <div className="p-10 bg-[#F8FAFC] border-t border-slate-100">
          <div className="flex justify-between items-end mb-10">
             <div>
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Total Tagihan</p>
                <p className="text-slate-900 font-black text-4xl tracking-tighter">Rp {subtotal.toLocaleString('id-ID')}</p>
             </div>
             <div className="text-right">
                <div className="flex items-center gap-1.5 text-blue-600 font-black text-[10px] uppercase tracking-widest mb-1">
                   <Sparkles size={12} /> Poin Reward
                </div>
                <p className="text-slate-900 font-black text-xl">+{cart.reduce((s, i) => s + (i.points || 0), 0)}</p>
             </div>
          </div>

          <button 
            disabled={cart.length === 0}
            onClick={() => onCheckout(cart)}
            className="w-full py-6 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 disabled:text-slate-400 text-white rounded-[32px] font-black text-sm uppercase tracking-[0.2em] transition-all shadow-xl shadow-blue-600/20 flex items-center justify-center gap-3 active:scale-95"
          >
            <CreditCard size={20} />
            Konfirmasi & Bayar
          </button>

          <div className="mt-6 flex items-center justify-center gap-2 text-slate-400">
             <Info size={14} />
             <span className="text-[10px] font-bold uppercase tracking-tight">Pajak 11% akan dihitung di tahap akhir</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default VisionPOS;

