// Katalog dengan deskripsi visual membantu AI mengenali objek lebih baik
const PRODUCT_CATALOG = `
  1. Tumbler Flower - ID: 1 - Harga: 75000 - Poin: 350 - Deskripsi: Botol minum atau tumbler dengan motif/corak bunga berwarna-warni.
  2. Patterned Pillow - ID: 2 - Harga: 50000 - Poin: 150 - Deskripsi: Bantal sofa dengan pola geometris atau corak hitam putih/berwarna.
