            var ptsSekarang = Number(memberRows[j][3]) || 0;
            var ptsUpdate = ptsSekarang - (Number(rawData.pointsDiscount) || 0) + (Number(rawData.pointsEarned) || 0);
            sheetMembers.getRange(j + 1, 4).setValue(ptsUpdate);
            break;
          }
        }
      }
      return ContentService.createTextOutput(JSON.stringify({ status: "success", message: "Transaksi Berhasil" })).setMimeType(ContentService.MimeType.JSON);
    }

    if (action === "ADD_PRODUCT") {
      sheetProducts.appendRow([
        pastikanString(rawData.id),
        pastikanString(rawData.nama),
        Number(rawData.harga),
        Number(rawData.poin),
        pastikanString(rawData.deskripsi),
        pastikanString(rawData.kategori),
        pastikanString(rawData.foto) // Menyimpan URL Foto
      ]);
      return ContentService.createTextOutput(JSON.stringify({ status: "success", message: "Produk Berhasil Ditambahkan" })).setMimeType(ContentService.MimeType.JSON);
    }

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: err.toString() })).setMimeType(ContentService.MimeType.JSON);
  }
}

function doGet(e) {
  var ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  var action = e.parameter.action;

  if (action === "GET_PRODUCTS") {
    var sheet = ss.getSheetByName("Products");
    if (!sheet) return ContentService.createTextOutput(JSON.stringify([])).setMimeType(ContentService.MimeType.JSON);

    var data = sheet.getDataRange().getValues();
    var headers = data[0];
    var products = [];

    for (var i = 1; i < data.length; i++) {
      var obj = {};
      headers.forEach(function(header, index) {
        var key = header.toLowerCase().replace(/ /g, "_");
        obj[key] = data[i][index];
      });
      products.push(obj);
    }
    return ContentService.createTextOutput(JSON.stringify(products)).setMimeType(ContentService.MimeType.JSON);
  }

  return HtmlService.createHtmlOutput("VisionPay API Ready");
}

import React, { useRef, useEffect, useState } from 'react';
import { Camera, Sparkles, ShoppingCart, Trash2, CreditCard, Loader2, BrainCircuit, Scan, ShieldCheck, AlertCircle, RefreshCw, X, Package } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { CartItem } from '../types';

interface VisionPOSProps {
  onCheckout: (items: CartItem[]) => void;
  onBack: () => void;
}

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

const VisionPOS: React.FC<VisionPOSProps> = ({ onCheckout, onBack }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isLoadingProducts, setIsLoadingProducts] = useState(true);
  const [dynamicCatalog, setDynamicCatalog] = useState<string>("");
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [lastDetected, setLastDetected] = useState<string>("");
  const [statusMsg, setStatusMsg] = useState<string>("Inisialisasi...");
  const [showError, setShowError] = useState(false);

  const fetchProducts = async () => {
    setIsLoadingProducts(true);
    setStatusMsg("Sinkronisasi Katalog...");
    try {
      const response = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=GET_PRODUCTS`);
      const products = await response.json();

      if (products.length > 0) {
        // Kita kirim deskripsi & nama produk ke AI. 
        // URL Foto tidak dikirim ke AI (karena AI tidak bisa buka URL luar saat runtime), 
        // tapi disimpan untuk UI Kasir.
        const catalogText = products.map((p: any) => 
          `- ID: ${p.id}, Nama: ${p.nama}, Harga: ${p.harga}, Poin: ${p.poin}, Deskripsi: ${p.deskripsi}, FotoURL: ${p.foto || p.image_url || ''}`
        ).join("\n");
        setDynamicCatalog(catalogText);
        setStatusMsg("Katalog Aktif");
      } else {
        setStatusMsg("Sheet Produk Kosong");
      }
    } catch (err) {
      console.error("Fetch failed", err);
      setStatusMsg("Katalog Offline");
    } finally {
      setIsLoadingProducts(false);
    }
  };

  useEffect(() => {
    fetchProducts();
    async function startCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
        });
        setStream(s);
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        console.error("Camera error", err);
        setStatusMsg("Kamera Error");
      }
    }
    startCamera();
    return () => stream?.getTracks().forEach(t => t.stop());
  }, []);

  const analyzeFrame = async () => {
    if (!videoRef.current || !canvasRef.current || isAnalyzing || isLoadingProducts) return;

    setIsAnalyzing(true);
    setShowError(false);
    setStatusMsg("Menganalisis Visual...");

    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.drawImage(video, 0, 0);

    const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: `Tugas: Deteksi barang belanjaan. 
                       Gunakan katalog di bawah sebagai referensi tunggal.

                       KATALOG (Setiap ID UNIK):
                       ${dynamicCatalog}

                       INSTRUKSI KETAT:
                       1. Perhatikan LOGO, TEKS MERK, WARNA, dan BENTUK spesifik pada gambar.
                       2. Bandingkan dengan field 'Deskripsi' di katalog untuk menentukan ID yang benar.
                       3. Jika ada dua barang mirip, pilih yang paling sesuai dengan tulisan/merk yang terlihat.
                       4. Kembalikan HANYA JSON array: [{"id": "...", "name": "...", "price": 0, "quantity": 1, "points": 0, "imageUrl": "URL_DARI_KATALOG"}].
                       5. Jika tidak yakin atau barang tidak ada di daftar, kembalikan [].` }
            ]
          }
        ],
        config: { 
          responseMimeType: "application/json",
          temperature: 0.1, // Rendah agar konsisten
        }
      });

      const detected: CartItem[] = JSON.parse(response.text || "[]");

      if (detected.length > 0) {
        setCart(prev => {
          let updated = [...prev];
          detected.forEach(item => {
            const idx = updated.findIndex(i => i.id === item.id);
            if (idx > -1) updated[idx].quantity += item.quantity;
            else updated.push(item);
          });
          return updated;
        });
        setLastDetected(detected.map(d => d.name).join(", "));
        setStatusMsg("Produk Ditemukan!");
        setTimeout(() => setLastDetected(""), 3000);
      } else {
        setStatusMsg("Barang Tidak Terdaftar");
        setShowError(true);
      }
    } catch (error) {
      console.error("AI Error:", error);
      setStatusMsg("Gagal Identifikasi");
    } finally {
      setIsAnalyzing(false);
      setTimeout(() => setStatusMsg("Siap Scan"), 2000);
    }
  };

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  return (
    <div className="fixed inset-0 bg-[#F8FAFC] flex overflow-hidden font-['Plus_Jakarta_Sans']">
      <canvas ref={canvasRef} className="hidden" />

      {/* Left: AI HUD */}
      <div className="flex-1 relative flex flex-col bg-white">
        <video ref={videoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover grayscale-[0.2]" />

        {/* HUD OVERLAY */}
        <div className="absolute inset-0 pointer-events-none border-[32px] border-white/20">
          <div className="absolute top-10 left-10 flex items-center gap-4 bg-white/90 backdrop-blur-xl p-4 rounded-[28px] shadow-2xl border border-white pointer-events-auto">
             <div className="w-12 h-12 bg-[#5551FF] rounded-2xl flex items-center justify-center shadow-lg shadow-blue-500/20">
                <BrainCircuit className="text-white" size={24} />
             </div>
             <div className="pr-4">
                <h1 className="text-slate-900 font-black text-xl tracking-tighter uppercase leading-none">Vision AI System</h1>
                <p className="text-[#5551FF] text-[9px] font-black tracking-[0.2em] uppercase mt-1">
                  {isLoadingProducts ? 'Syncing...' : 'Catalog Verified'}
                </p>
             </div>
             <button onClick={fetchProducts} className="p-2 hover:bg-slate-100 rounded-xl text-slate-400 transition-colors">
                <RefreshCw size={18} className={isLoadingProducts ? 'animate-spin' : ''} />
             </button>
          </div>

          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[480px] h-[480px]">
             <div className="absolute top-0 left-0 w-24 h-24 border-t-[8px] border-l-[8px] border-[#5551FF] rounded-tl-[50px] opacity-60" />
             <div className="absolute top-0 right-0 w-24 h-24 border-t-[8px] border-r-[8px] border-[#5551FF] rounded-tr-[50px] opacity-60" />
             <div className="absolute bottom-0 left-0 w-24 h-24 border-b-[8px] border-l-[8px] border-[#5551FF] rounded-bl-[50px] opacity-60" />
             <div className="absolute bottom-0 right-0 w-24 h-24 border-b-[8px] border-r-[8px] border-[#5551FF] rounded-br-[50px] opacity-60" />
          </div>
          <div className="scan-line !bg-[#5551FF]/40" />
        </div>

        <button onClick={onBack} className="absolute top-10 right-10 w-12 h-12 bg-white/90 backdrop-blur-xl rounded-2xl flex items-center justify-center text-slate-400 hover:text-red-500 transition-all shadow-xl pointer-events-auto">
          <X size={24} />
        </button>

        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex flex-col items-center gap-6 z-20 w-full px-12">
          {lastDetected && (
            <div className="bg-green-500 text-white px-10 py-4 rounded-full flex items-center gap-3 animate-in slide-in-from-bottom duration-500 shadow-2xl">
              <ShieldCheck size={20} />
              <span className="font-black text-sm uppercase tracking-widest">Matched: {lastDetected}</span>
            </div>
          )}

          {showError && (
            <div className="bg-amber-500 text-white px-10 py-4 rounded-full flex items-center gap-3 animate-in fade-in duration-300 shadow-2xl">
              <AlertCircle size={20} />
              <span className="font-black text-sm uppercase tracking-widest">Item Not in Catalog</span>
            </div>
          )}

          <button 
            onClick={analyzeFrame}
            disabled={isAnalyzing || isLoadingProducts}
            className={`w-28 h-28 rounded-full flex items-center justify-center transition-all active:scale-90 shadow-2xl
              ${isAnalyzing ? 'bg-slate-100 text-slate-300' : 'bg-[#5551FF] hover:bg-[#4440FF] text-white ring-[14px] ring-blue-500/10'}
            `}
          >
            {isAnalyzing ? <Loader2 className="animate-spin" size={44} /> : <Scan size={48} />}
          </button>

          <div className="bg-slate-900/80 backdrop-blur-xl px-8 py-3 rounded-2xl border border-white/10 shadow-2xl">
             <span className="text-white text-[11px] font-black uppercase tracking-[0.4em]">{statusMsg}</span>
          </div>
        </div>
      </div>

      {/* Right: SMART CART (With Image Mapping) */}
      <div className="w-[520px] bg-white flex flex-col z-30 shadow-[-40px_0_80px_rgba(0,0,0,0.05)] border-l border-slate-100">
        <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
          <div className="flex items-center gap-5">
            <div className="w-14 h-14 bg-[#5551FF]/10 rounded-[22px] flex items-center justify-center text-[#5551FF]">
              <ShoppingCart size={28} />
            </div>
            <div>
               <h2 className="text-slate-900 font-black text-2xl tracking-tight">AI Checkout</h2>
               <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Verifikasi Visual Aktif</p>
            </div>
          </div>
          <div className="px-5 py-2 bg-slate-900 rounded-full text-white font-black text-[11px] uppercase tracking-widest">
            {cart.length} ITEMS
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-white">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-8 opacity-40">
              <div className="w-32 h-32 bg-slate-50 rounded-[48px] flex items-center justify-center border-2 border-dashed border-slate-200">
                <Package size={48} className="text-slate-200" />
              </div>
              <div className="space-y-3">
                <p className="text-slate-900 font-black text-base uppercase tracking-[0.2em]">Scan Belanjaan</p>
                <p className="text-slate-400 text-xs max-w-[240px] leading-relaxed mx-auto">Sistem akan mencocokkan benda di kamera dengan ID produk unik Anda.</p>
              </div>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={`${item.id}-${idx}`} className="group relative bg-white border border-slate-100 p-6 rounded-[36px] flex items-center gap-6 transition-all hover:shadow-2xl hover:shadow-slate-200/50 hover:border-blue-200 hover:-translate-y-1">
                {/* Visual Verification Image */}
                <div className="w-20 h-20 bg-slate-50 rounded-[24px] overflow-hidden flex items-center justify-center border border-slate-100 shadow-inner group-hover:scale-110 transition-transform duration-500">
                   {item.imageUrl ? (
                     <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" onError={(e) => (e.currentTarget.src = "")} />
                   ) : (
                     <Scan size={24} className="text-slate-200" />
                   )}
                </div>

                <div className="flex-1 min-w-0">
                  <h4 className="text-slate-900 font-black text-base leading-tight truncate">{item.name}</h4>
                  <div className="flex items-center gap-3 mt-1.5">
                     <span className="text-[#5551FF] font-black text-sm">Rp {item.price.toLocaleString('id-ID')}</span>
                     <div className="h-1 w-1 rounded-full bg-slate-200" />
                     <span className="text-slate-400 font-bold text-[11px] uppercase tracking-tighter">ID: {item.id}</span>
                  </div>
                </div>

                <div className="flex flex-col items-end gap-3">
                   <div className="bg-slate-50 px-3 py-1.5 rounded-xl font-black text-slate-900 text-sm border border-slate-100">
                      x{item.quantity}
                   </div>
                   <button 
                     onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))}
                     className="w-10 h-10 rounded-2xl flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 transition-all"
                   >
                     <Trash2 size={18} />
                   </button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-10 bg-slate-900 text-white rounded-t-[50px] shadow-2xl">
          <div className="flex justify-between items-end mb-10">
             <div className="space-y-1">
                <p className="text-white/40 text-[10px] font-black uppercase tracking-[0.3em]">Total Transaksi</p>
                <p className="text-white font-black text-4xl tracking-tighter">Rp {subtotal.toLocaleString('id-ID')}</p>
             </div>
             <div className="text-right">
                <div className="inline-flex items-center gap-2 bg-white/10 px-4 py-1.5 rounded-full text-blue-300 font-black text-[10px] uppercase tracking-widest mb-1 border border-white/5">
                   <Sparkles size={12} /> Cashback
                </div>
                <p className="text-white font-black text-xl">+{cart.reduce((s, i) => s + (i.points || 0), 0)} pts</p>
             </div>
          </div>

          <button 
            disabled={cart.length === 0}
            onClick={() => onCheckout(cart)}
            className="w-full py-6 bg-[#5551FF] hover:bg-[#4440FF] disabled:bg-white/10 disabled:text-white/20 text-white rounded-[32px] font-black text-sm uppercase tracking-[0.3em] transition-all shadow-xl shadow-blue-500/20 flex items-center justify-center gap-4 active:scale-[0.98]"
          >
            <CreditCard size={22} />
            Konfirmasi Pesanan
          </button>
        </div>
      </div>
    </div>
  );
};

export default VisionPOS;

export enum ViewState {
  LANDING = 'LANDING',
  SELECT_INPUT = 'SELECT_INPUT',
  SCANNING_AI = 'SCANNING_AI',
  SCANNING_BARCODE = 'SCANNING_BARCODE',
  CART = 'CART',
  MEMBERSHIP_SCAN = 'MEMBERSHIP_SCAN',
  SELECT_VOUCHER = 'SELECT_VOUCHER',
  PAYMENT_QRIS = 'PAYMENT_QRIS',
  SUCCESS = 'SUCCESS',
  POS = 'POS'
}

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
  imageUrl?: string;
}

export interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  imageUrl?: string;
  deskripsi?: string;
}

export interface Voucher {
  id: string;
  title: string;
  description: string;
  discountType: 'PERCENT' | 'FIXED';
  value: number;
  minTransaction?: number;
  isMemberOnly: boolean;
}

export interface TransactionData {
  transactionId: string;
  customerType: 'MEMBER' | 'GUEST';
  customerName: string;
  items: string;
  subtotal: number;
  voucherName: string;
  voucherDiscount: number;
  tax: number;
  totalPaid: number;
  paymentMethod: string;
}

import React, { useState } from 'react';
import { ViewState, CartItem, Voucher } from './types';
import LandingPage from './components/LandingPage';
import VisionPOS from './components/VisionPOS';
import SelectInputPage from './components/SelectInputPage';
import BarcodeScannerPage from './components/BarcodeScannerPage';
import CartPage from './components/CartPage';
import MembershipPage from './components/MembershipPage';
import VoucherSelectionPage from './components/VoucherSelectionPage';
import PaymentQRIS from './components/PaymentQRIS';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

interface MemberData {
  id: string;
  name: string;
  tier: string;
}

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [memberInfo, setMemberInfo] = useState<MemberData | null>(null);
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);
  const [isCheckingMember, setIsCheckingMember] = useState<boolean>(false);

  const handleStart = () => setView(ViewState.SELECT_INPUT);

  const handleFinishVisionScan = (items: CartItem[]) => {
    setCart(items);
    setView(ViewState.CART);
  };

  const handleFindMember = async (id: string = "VP-1001") => {
    setIsCheckingMember(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      setMemberInfo({ id, name: "Budi Santoso", tier: "Platinum" });
      setIsMember(true);
      setView(ViewState.SELECT_VOUCHER);
    } catch (error) {
      console.error(error);
    } finally {
      setIsCheckingMember(false);
    }
  };

  const syncTransaction = async (total: number, tax: number, subtotal: number, discount: number, method: string = "QRIS") => {
    setIsSyncing(true);
    const transactionId = `VP-${Math.floor(1000 + Math.random() * 9000)}`;
    const itemsSummary = cart.map(item => `${item.name} (${item.quantity}x)`).join(', ');
    const itemsDetail = cart.map(item => ({ 
      name: item.name, 
      price: item.price, 
      qty: item.quantity, 
      total: item.price * item.quantity 
    }));

    const payload = {
      action: "SYNC_TRANSACTION",
      transactionId,
      memberId: memberInfo?.id || "",
      customerType: isMember ? 'MEMBER' : 'GUEST',
      customerName: isMember ? memberInfo?.name : "Pelanggan Guest",
      itemsSummary,
      items: itemsDetail,
      subtotal,
      voucherName: selectedVoucher?.title || "-",
      voucherDiscount: discount,
      tax,
      totalPaid: total,
      paymentMethod: method
    };

    try {
      await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });
    } catch (error) {
      console.error("Sync Error:", error);
    } finally {
      setTimeout(() => {
        setIsSyncing(false);
        setView(ViewState.SUCCESS);
      }, 1000);
    }
  };

  const calculateDiscount = () => {
    if (!selectedVoucher) return 0;
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return selectedVoucher.discountType === 'PERCENT' ? subtotal * (selectedVoucher.value / 100) : selectedVoucher.value;
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(1, item.quantity + delta) } : item).filter(item => item.quantity > 0));
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const voucherDiscount = calculateDiscount();
    const totalReduction = Math.min(subtotal, voucherDiscount);
    const tax = Math.max(0, (subtotal - totalReduction) * 0.11);
    const finalTotal = Math.max(0, (subtotal - totalReduction) + tax);

    switch (view) {
      case ViewState.LANDING: 
        return <LandingPage onStart={handleStart} />;

      case ViewState.SELECT_INPUT:
        return (
          <SelectInputPage 
            onSelectAI={() => setView(ViewState.POS)} 
            onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)} 
            onBack={() => setView(ViewState.LANDING)} 
          />
        );

      case ViewState.SCANNING_BARCODE:
        return (
          <BarcodeScannerPage 
            onBack={() => setView(ViewState.SELECT_INPUT)} 
            onFinish={() => setView(ViewState.CART)} 
          />
        );

      case ViewState.POS: 
        return <VisionPOS onBack={() => setView(ViewState.SELECT_INPUT)} onCheckout={handleFinishVisionScan} />;

      case ViewState.CART: 
        return <CartPage cart={cart} isMember={isMember} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onReset={() => setView(ViewState.LANDING)} onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)} onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)} onConfirm={() => setView(ViewState.PAYMENT_QRIS)} />;

      case ViewState.MEMBERSHIP_SCAN: 
        return <MembershipPage isChecking={isCheckingMember} onSkip={() => setView(ViewState.SELECT_VOUCHER)} onDetected={() => handleFindMember()} />;

      case ViewState.SELECT_VOUCHER: 
        return <VoucherSelectionPage isMember={isMember} memberData={memberInfo} selectedVoucherId={selectedVoucher?.id} onSelect={setSelectedVoucher} onBack={() => setView(ViewState.CART)} />;

      case ViewState.PAYMENT_QRIS: 
        return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => syncTransaction(finalTotal, tax, subtotal, voucherDiscount, "QRIS")} total={finalTotal} />;

      case ViewState.SUCCESS: 
        return <SuccessPage onFinish={() => { setCart([]); setView(ViewState.LANDING); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); }} total={finalTotal} isSyncing={isSyncing} />;

      default: 
        return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.POS, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS, ViewState.SCANNING_BARCODE].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { Camera, ShoppingCart, Trash2, CreditCard, Loader2, BrainCircuit, Scan, ShieldCheck, AlertCircle, RefreshCw, X, Package } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { CartItem } from '../types';

interface VisionPOSProps {
  onCheckout: (items: CartItem[]) => void;
  onBack: () => void;
}

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

const VisionPOS: React.FC<VisionPOSProps> = ({ onCheckout, onBack }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isLoadingProducts, setIsLoadingProducts] = useState(true);
  const [dynamicCatalog, setDynamicCatalog] = useState<string>("");
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [lastDetected, setLastDetected] = useState<string>("");
  const [statusMsg, setStatusMsg] = useState<string>("Inisialisasi...");
  const [showError, setShowError] = useState(false);

  const fetchProducts = async () => {
    setIsLoadingProducts(true);
    setStatusMsg("Sinkronisasi Katalog...");
    try {
      const response = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=GET_PRODUCTS`);
      const products = await response.json();

      if (products.length > 0) {
        const catalogText = products.map((p: any) => 
          `- ID: ${p.id}, Nama: ${p.nama}, Harga: ${p.harga}, Deskripsi: ${p.deskripsi}, FotoURL: ${p.foto || p.image_url || ''}`
        ).join("\n");
        setDynamicCatalog(catalogText);
        setStatusMsg("Katalog Aktif");
      } else {
        setStatusMsg("Sheet Produk Kosong");
      }
    } catch (err) {
      console.error("Fetch failed", err);
      setStatusMsg("Katalog Offline");
    } finally {
      setIsLoadingProducts(false);
    }
  };

  useEffect(() => {
    fetchProducts();
    async function startCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
        });
        setStream(s);
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        console.error("Camera error", err);
        setStatusMsg("Kamera Error");
      }
    }
    startCamera();
    return () => stream?.getTracks().forEach(t => t.stop());
  }, []);

  const analyzeFrame = async () => {
    if (!videoRef.current || !canvasRef.current || isAnalyzing || isLoadingProducts) return;

    setIsAnalyzing(true);
    setShowError(false);
    setStatusMsg("Menganalisis Visual...");

    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.drawImage(video, 0, 0);

    const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: `Tugas: Deteksi barang belanjaan. 
                       Gunakan katalog di bawah sebagai referensi tunggal.

                       KATALOG (Setiap ID UNIK):
                       ${dynamicCatalog}

                       INSTRUKSI KETAT:
                       1. Perhatikan LOGO, TEKS MERK, WARNA, dan BENTUK spesifik pada gambar.
                       2. Bandingkan dengan field 'Deskripsi' di katalog untuk menentukan ID yang benar.
                       3. Jika ada dua barang mirip, pilih yang paling sesuai dengan tulisan/merk yang terlihat.
                       4. Kembalikan HANYA JSON array: [{"id": "...", "name": "...", "price": 0, "quantity": 1, "imageUrl": "URL_DARI_KATALOG"}].
                       5. Jika tidak yakin atau barang tidak ada di daftar, kembalikan [].` }
            ]
          }
        ],
        config: { 
          responseMimeType: "application/json",
          temperature: 0.1,
        }
      });

      const detected: CartItem[] = JSON.parse(response.text || "[]");

      if (detected.length > 0) {
        setCart(prev => {
          let updated = [...prev];
          detected.forEach(item => {
            const idx = updated.findIndex(i => i.id === item.id);
            if (idx > -1) updated[idx].quantity += item.quantity;
            else updated.push(item);
          });
          return updated;
        });
        setLastDetected(detected.map(d => d.name).join(", "));
        setStatusMsg("Produk Ditemukan!");
        setTimeout(() => setLastDetected(""), 3000);
      } else {
        setStatusMsg("Barang Tidak Terdaftar");
        setShowError(true);
      }
    } catch (error) {
      console.error("AI Error:", error);
      setStatusMsg("Gagal Identifikasi");
    } finally {
      setIsAnalyzing(false);
      setTimeout(() => setStatusMsg("Siap Scan"), 2000);
    }
  };

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  return (
    <div className="fixed inset-0 bg-[#F8FAFC] flex overflow-hidden font-['Plus_Jakarta_Sans']">
      <canvas ref={canvasRef} className="hidden" />

      <div className="flex-1 relative flex flex-col bg-white">
        <video ref={videoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover grayscale-[0.2]" />

        <div className="absolute inset-0 pointer-events-none border-[32px] border-white/20">
          <div className="absolute top-10 left-10 flex items-center gap-4 bg-white/90 backdrop-blur-xl p-4 rounded-[28px] shadow-2xl border border-white pointer-events-auto">
             <div className="w-12 h-12 bg-[#5551FF] rounded-2xl flex items-center justify-center shadow-lg shadow-blue-500/20">
                <BrainCircuit className="text-white" size={24} />
             </div>
             <div className="pr-4">
                <h1 className="text-slate-900 font-black text-xl tracking-tighter uppercase leading-none">Vision AI System</h1>
                <p className="text-[#5551FF] text-[9px] font-black tracking-[0.2em] uppercase mt-1">
                  {isLoadingProducts ? 'Syncing...' : 'Catalog Verified'}
                </p>
             </div>
             <button onClick={fetchProducts} className="p-2 hover:bg-slate-100 rounded-xl text-slate-400 transition-colors">
                <RefreshCw size={18} className={isLoadingProducts ? 'animate-spin' : ''} />
             </button>
          </div>

          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[480px] h-[480px]">
             <div className="absolute top-0 left-0 w-24 h-24 border-t-[8px] border-l-[8px] border-[#5551FF] rounded-tl-[50px] opacity-60" />
             <div className="absolute top-0 right-0 w-24 h-24 border-t-[8px] border-r-[8px] border-[#5551FF] rounded-tr-[50px] opacity-60" />
             <div className="absolute bottom-0 left-0 w-24 h-24 border-b-[8px] border-l-[8px] border-[#5551FF] rounded-bl-[50px] opacity-60" />
             <div className="absolute bottom-0 right-0 w-24 h-24 border-b-[8px] border-r-[8px] border-[#5551FF] rounded-br-[50px] opacity-60" />
          </div>
          <div className="scan-line !bg-[#5551FF]/40" />
        </div>

        <button onClick={onBack} className="absolute top-10 right-10 w-12 h-12 bg-white/90 backdrop-blur-xl rounded-2xl flex items-center justify-center text-slate-400 hover:text-red-500 transition-all shadow-xl pointer-events-auto">
          <X size={24} />
        </button>

        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex flex-col items-center gap-6 z-20 w-full px-12">
          {lastDetected && (
            <div className="bg-green-500 text-white px-10 py-4 rounded-full flex items-center gap-3 animate-in slide-in-from-bottom duration-500 shadow-2xl">
              <ShieldCheck size={20} />
              <span className="font-black text-sm uppercase tracking-widest">Matched: {lastDetected}</span>
            </div>
          )}

          {showError && (
            <div className="bg-amber-500 text-white px-10 py-4 rounded-full flex items-center gap-3 animate-in fade-in duration-300 shadow-2xl">
              <AlertCircle size={20} />
              <span className="font-black text-sm uppercase tracking-widest">Item Not in Catalog</span>
            </div>
          )}

          <button 
            onClick={analyzeFrame}
            disabled={isAnalyzing || isLoadingProducts}
            className={`w-28 h-28 rounded-full flex items-center justify-center transition-all active:scale-90 shadow-2xl
              ${isAnalyzing ? 'bg-slate-100 text-slate-300' : 'bg-[#5551FF] hover:bg-[#4440FF] text-white ring-[14px] ring-blue-500/10'}
            `}
          >
            {isAnalyzing ? <Loader2 className="animate-spin" size={44} /> : <Scan size={48} />}
          </button>

          <div className="bg-slate-900/80 backdrop-blur-xl px-8 py-3 rounded-2xl border border-white/10 shadow-2xl">
             <span className="text-white text-[11px] font-black uppercase tracking-[0.4em]">{statusMsg}</span>
          </div>
        </div>
      </div>

      <div className="w-[520px] bg-white flex flex-col z-30 shadow-[-40px_0_80px_rgba(0,0,0,0.05)] border-l border-slate-100">
        <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
          <div className="flex items-center gap-5">
            <div className="w-14 h-14 bg-[#5551FF]/10 rounded-[22px] flex items-center justify-center text-[#5551FF]">
              <ShoppingCart size={28} />
            </div>
            <div>
               <h2 className="text-slate-900 font-black text-2xl tracking-tight">AI Checkout</h2>
               <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Verifikasi Visual Aktif</p>
            </div>
          </div>
          <div className="px-5 py-2 bg-slate-900 rounded-full text-white font-black text-[11px] uppercase tracking-widest">
            {cart.length} ITEMS
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-white">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-8 opacity-40">
              <div className="w-32 h-32 bg-slate-50 rounded-[48px] flex items-center justify-center border-2 border-dashed border-slate-200">
                <Package size={48} className="text-slate-200" />
              </div>
              <div className="space-y-3">
                <p className="text-slate-900 font-black text-base uppercase tracking-[0.2em]">Scan Belanjaan</p>
                <p className="text-slate-400 text-xs max-w-[240px] leading-relaxed mx-auto">Sistem akan mencocokkan benda di kamera dengan ID produk unik Anda.</p>
              </div>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={`${item.id}-${idx}`} className="group relative bg-white border border-slate-100 p-6 rounded-[36px] flex items-center gap-6 transition-all hover:shadow-2xl hover:shadow-slate-200/50 hover:border-blue-200 hover:-translate-y-1">
                <div className="w-20 h-20 bg-slate-50 rounded-[24px] overflow-hidden flex items-center justify-center border border-slate-100 shadow-inner group-hover:scale-110 transition-transform duration-500">
                   {item.imageUrl ? (
                     <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" onError={(e) => (e.currentTarget.src = "")} />
                   ) : (
                     <Scan size={24} className="text-slate-200" />
                   )}
                </div>

                <div className="flex-1 min-w-0">
                  <h4 className="text-slate-900 font-black text-base leading-tight truncate">{item.name}</h4>
                  <div className="flex items-center gap-3 mt-1.5">
                     <span className="text-[#5551FF] font-black text-sm">Rp {item.price.toLocaleString('id-ID')}</span>
                     <div className="h-1 w-1 rounded-full bg-slate-200" />
                     <span className="text-slate-400 font-bold text-[11px] uppercase tracking-tighter">ID: {item.id}</span>
                  </div>
                </div>

                <div className="flex flex-col items-end gap-3">
                   <div className="bg-slate-50 px-3 py-1.5 rounded-xl font-black text-slate-900 text-sm border border-slate-100">
                      x{item.quantity}
                   </div>
                   <button 
                     onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))}
                     className="w-10 h-10 rounded-2xl flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 transition-all"
                   >
                     <Trash2 size={18} />
                   </button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-10 bg-slate-900 text-white rounded-t-[50px] shadow-2xl">
          <div className="flex justify-between items-end mb-10">
             <div className="space-y-1">
                <p className="text-white/40 text-[10px] font-black uppercase tracking-[0.3em]">Total Transaksi</p>
                <p className="text-white font-black text-4xl tracking-tighter">Rp {subtotal.toLocaleString('id-ID')}</p>
             </div>
          </div>

          <button 
            disabled={cart.length === 0}
            onClick={() => onCheckout(cart)}
            className="w-full py-6 bg-[#5551FF] hover:bg-[#4440FF] disabled:bg-white/10 disabled:text-white/20 text-white rounded-[32px] font-black text-sm uppercase tracking-[0.3em] transition-all shadow-xl shadow-blue-500/20 flex items-center justify-center gap-4 active:scale-[0.98]"
          >
            <CreditCard size={22} />
            Konfirmasi Pesanan
          </button>
        </div>
      </div>
    </div>
  );
};

