const VoucherSelectionPage: React.FC<VoucherSelectionPageProps> = ({ 
  isMember, memberData, selectedVoucherId, pointsUsed, onSelectPoints, onSelect, onBack, cart 
}) => {
  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalPointsPotential = cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);

  // Maksimal poin yang bisa digunakan adalah saldo member atau seharga subtotal
  const maxRedeemable = memberData ? Math.min(memberData.points, subtotal) : 0;

  const handleTogglePoints = () => {
    if (pointsUsed > 0) {
      onSelectPoints(0);
    } else {
      onSelectPoints(maxRedeemable);
    }
  };

  const getTierStyles = (tier: string = "Silver") => {
    switch (tier.toLowerCase()) {
      case 'platinum': 
        return {
          bg: 'bg-gradient-to-br from-slate-900 via-indigo-950 to-indigo-900',
          badge: 'bg-white/10 border-white/20 text-indigo-200',
          icon: <Crown size={16} />
        };
      case 'gold': 
        return {
          bg: 'bg-gradient-to-br from-amber-500 via-amber-600 to-amber-700',
          badge: 'bg-white/20 border-white/30 text-white',
          icon: <Star size={16} />
        };
      default: 
        return {
          bg: 'bg-gradient-to-br from-slate-500 via-slate-600 to-slate-700',
          badge: 'bg-white/20 border-white/30 text-white',
          icon: <Award size={16} />
        };
    }
  };

  const tier = getTierStyles(memberData?.tier);

  return (
    <div className="fixed inset-0 bg-[#F8FAFC] z-50 flex flex-col overflow-hidden">
      <div className="bg-white border-b border-slate-100 px-8 py-4 flex items-center justify-between z-20 shrink-0">
        <div className="flex items-center gap-6">
          <button onClick={onBack} className="w-10 h-10 rounded-full flex items-center justify-center border border-slate-200 text-slate-400 hover:bg-slate-50 transition-all">
            <ArrowLeft size={18} />
          </button>
          <div>
            <h1 className="text-lg font-black text-slate-900 leading-none uppercase tracking-tighter">Reward & Loyalty</h1>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Gunakan Keuntungan Member Anda</p>
          </div>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <aside className="w-[380px] border-r border-slate-100 bg-white flex flex-col overflow-hidden">
          <div className="flex-1 overflow-y-auto p-8 space-y-6">
            {isMember && memberData ? (
              <>
                <div className={`aspect-[1.6/1] w-full rounded-[32px] ${tier.bg} text-white p-6 vision-shadow relative overflow-hidden shrink-0`}>
                  <div className="relative h-full flex flex-col justify-between">
                      <div className="flex justify-between items-start">
                        <div className="w-8 h-8 rounded-lg bg-white/20 flex items-center justify-center backdrop-blur-md">
                          <User size={18} />
                        </div>
                        <div className={`px-3 py-1 rounded-full border text-[9px] font-black uppercase tracking-widest flex items-center gap-1.5 ${tier.badge}`}>
                          {tier.icon} {memberData.tier}
                        </div>
                      </div>
                      <div>
                        <h3 className="text-xl font-black mb-1 leading-none">{memberData.name}</h3>
                        <p className="text-[10px] font-mono opacity-50 tracking-widest">{memberData.id}</p>
                      </div>
                  </div>
                </div>

                <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-4">
                  <div className="flex justify-between items-center">
                    <div>
                       <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Saldo Poin Anda</p>
                       <p className="text-2xl font-black text-slate-900">{memberData.points.toLocaleString('id-ID')} <span className="text-[10px] text-slate-400">pts</span></p>
                    </div>
                    <div className="w-12 h-12 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-600 shadow-inner">
                       <Coins size={24} />
                    </div>
                  </div>

                  <div className="pt-4 border-t border-slate-200">
                    <button 
                      onClick={handleTogglePoints}
                      disabled={maxRedeemable === 0}
                      className={`w-full py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-2 shadow-lg
                        ${pointsUsed > 0 
                          ? 'bg-red-50 text-red-600 border border-red-100' 
                          : 'bg-[#5551FF] text-white hover:bg-[#4440FF] shadow-blue-500/20'}
                        ${maxRedeemable === 0 ? 'opacity-50 cursor-not-allowed grayscale' : ''}
                      `}
                    >
                      {pointsUsed > 0 ? (
                        <>Batalkan Poin</>
                      ) : (
                        <>Gunakan {maxRedeemable.toLocaleString('id-ID')} Poin</>
                      )}
                    </button>
                    {pointsUsed > 0 && (
                      <p className="text-center text-[10px] text-green-600 font-bold mt-3 animate-pulse">
                         ✓ Berhasil memotong Rp {pointsUsed.toLocaleString('id-ID')}
