                  <div>
                    <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Potensi Cashback</p>
                    <p className="text-lg font-black text-[#5551FF]">+{totalPointsPotential} <span className="text-[10px]">pts</span></p>
                  </div>
                  <Zap size={20} className="text-blue-400" />
                </div>
              </>
            ) : (
              <div className="aspect-[1.6/1] w-full rounded-[32px] bg-slate-50 border-2 border-dashed border-slate-200 p-8 flex flex-col items-center justify-center text-center shrink-0">
                <User size={32} className="text-slate-300 mb-2" />
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">GUEST MODE</p>
                <p className="text-[10px] text-slate-400 mt-2">Masuk member untuk menggunakan poin</p>
              </div>
            )}
          </div>

          <div className="p-8 border-t border-slate-100 bg-white">
            <button 
              onClick={onBack}
              className="w-full py-5 bg-slate-900 hover:bg-black text-white rounded-[24px] font-black text-sm uppercase tracking-widest transition-all vision-shadow flex items-center justify-center gap-3 active:scale-95"
            >
              Lanjutkan Ke Pembayaran
              <ArrowRight size={18} />
            </button>
          </div>
        </aside>

        <main className="flex-1 overflow-y-auto p-8 lg:p-12 space-y-12 bg-slate-50/30">
          <section className="animate-in slide-in-from-right duration-500">
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">Voucher Tersedia</h2>
              <div className="flex items-center gap-2 px-4 py-1.5 bg-white rounded-full border border-slate-200 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <Zap size={12} fill="currentColor" /> Hemat Maksimal
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {AVAILABLE_VOUCHERS.map((voucher) => {
                const isDisabled = voucher.isMemberOnly && !isMember;
                const isSelected = selectedVoucherId === voucher.id;

                return (
                  <button 
                    key={voucher.id} 
                    disabled={isDisabled} 
                    onClick={() => onSelect(isSelected ? null : voucher)} 
                    className={`group text-left rounded-[40px] transition-all flex flex-col h-full overflow-hidden border-2 relative
                      ${isDisabled ? 'bg-slate-50 border-slate-100 opacity-60 cursor-not-allowed' : 'bg-white border-white shadow-lg shadow-slate-200/50 active:scale-[0.98]'}
                      ${isSelected ? 'grayscale opacity-50 border-indigo-200 scale-[0.99]' : 'hover:border-indigo-500'}
                    `}
                  >
                    {isSelected && (
                      <div className="absolute inset-0 bg-white/10 z-10 flex items-center justify-center">
                         <div className="bg-slate-900 text-white px-6 py-2 rounded-full font-black text-[10px] uppercase tracking-widest flex items-center gap-2 shadow-2xl scale-110">
                           <Check size={14} className="text-indigo-400" /> Voucher Terpasang
                         </div>
                      </div>
                    )}

                    <div className={`px-8 py-5 flex items-center justify-between transition-colors ${isSelected ? 'bg-slate-400 text-white' : (voucher.isMemberOnly ? 'bg-indigo-600 text-white' : 'bg-slate-900 text-white')}`}>
                      <span className="text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
                        <Ticket size={12} /> {voucher.isMemberOnly ? 'Member Reward' : 'Promo Publik'}
                      </span>
                    </div>

                    <div className="p-8 flex-1 flex flex-col">
                      <div className="text-5xl font-black text-slate-900 mb-3 tracking-tighter">
                        {voucher.discountType === 'PERCENT' ? `${voucher.value}%` : `Rp ${voucher.value / 1000}k`} <span className="text-xl uppercase text-slate-300">Off</span>
                      </div>
                      <h5 className="font-black text-slate-900 text-base uppercase mb-2">{voucher.title}</h5>
                      <p className="text-sm text-slate-400 font-medium leading-relaxed mb-6">{voucher.description}</p>

                      <div className={`mt-auto pt-4 border-t border-slate-50 flex items-center font-bold text-xs uppercase tracking-widest transition-opacity
                        ${isSelected ? 'text-red-500 opacity-100' : 'text-indigo-500 opacity-0 group-hover:opacity-100'}
                      `}>
                        {isSelected ? (
                          <span className="flex items-center gap-2"><XCircle size={14}/> Batalkan Voucher</span>
                        ) : (
                          'Gunakan Voucher ini'
                        )}
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>
          </section>
        </main>
      </div>
    </div>
  );
};

export default VoucherSelectionPage;

