import React, { useState, useEffect } from 'react';
import { 
  Search, ShoppingCart, User, Package, 
  Plus, Minus, Trash2, Sparkles, 
  ChevronRight, CreditCard, Tag, Loader2, RefreshCw
} from 'lucide-react';
import { CartItem, Product, Voucher } from '../types';

interface CashierPOSProps {
  cart: CartItem[];
  onAddToCart: (product: any) => void;
  onUpdateQuantity: (id: string, delta: number) => void;
  onRemoveItem: (id: string) => void;
  onCheckout: () => void;
  onScanAI: () => void;
  isMember: boolean;
  memberInfo: any;
  selectedVoucher: Voucher | null;
  discountAmount: number;
}

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

const CashierPOS: React.FC<CashierPOSProps> = ({ 
  cart, onAddToCart, onUpdateQuantity, onRemoveItem, onCheckout, onScanAI,
  isMember, memberInfo, selectedVoucher, discountAmount
}) => {
  const [products, setProducts] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  const fetchProducts = async () => {
    setIsLoading(true);
    try {
      const response = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=GET_PRODUCTS`);
      const data = await response.json();
      setProducts(data);
    } catch (error) {
      console.error("Gagal mengambil produk:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  const filteredProducts = products.filter(p => 
    (activeCategory === 'All' || p.kategori === activeCategory) &&
    p.nama.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Ambil list kategori unik dari data produk
  const categories = ['All', ...new Set(products.map(p => p.kategori).filter(Boolean))];

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const tax = (subtotal - discountAmount) * 0.11;
  const total = (subtotal - discountAmount) + tax;

  return (
    <div className="flex w-full h-[calc(100vh-140px)] gap-6 animate-in fade-in duration-500">
      {/* Left: Product Catalog */}
      <div className="flex-1 flex flex-col gap-6 overflow-hidden">
        <div className="flex items-center gap-4 bg-white p-4 rounded-[24px] shadow-sm border border-slate-100">
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input 
              type="text" 
              placeholder="Cari nama produk di database..." 
              className="w-full pl-12 pr-4 py-3 bg-slate-50 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500/20 transition-all font-medium"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            onClick={fetchProducts}
            className="p-3 bg-slate-50 text-slate-400 hover:text-blue-500 rounded-xl transition-all"
            title="Refresh Produk"
          >
            <RefreshCw size={20} className={isLoading ? 'animate-spin' : ''} />
          </button>
          <button 
            onClick={onScanAI}
            className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-xl font-black text-sm uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
          >
            <Sparkles size={18} />
            Magic Scan
          </button>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-6 py-2.5 rounded-full text-xs font-black uppercase tracking-widest transition-all whitespace-nowrap
                ${activeCategory === cat ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-400 hover:bg-slate-50'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto pr-2 grid grid-cols-2 md:grid-cols-3 gap-4">
          {isLoading ? (
            <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-400">
              <Loader2 className="animate-spin mb-4" size={40} />
              <p className="font-bold text-sm uppercase tracking-widest">Menghubungkan ke Sheets...</p>
            </div>
          ) : filteredProducts.length === 0 ? (
            <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-300">
              <Package size={60} strokeWidth={1} />
              <p className="font-black text-xs uppercase tracking-widest mt-4">Produk tidak ditemukan</p>
            </div>
          ) : (
            filteredProducts.map(product => (
              <button
                key={product.id}
                onClick={() => onAddToCart({
                  id: product.id,
                  name: product.nama,
                  price: Number(product.harga),
                  points: Number(product.poin),
                  imageUrl: product.foto
                })}
                className="bg-white p-5 rounded-[32px] border border-slate-100 hover:border-blue-500 hover:shadow-xl hover:shadow-blue-500/5 transition-all text-left group flex flex-col items-center gap-3 active:scale-95"
              >
                <div className="w-full aspect-square bg-slate-50 rounded-2xl flex items-center justify-center overflow-hidden border border-slate-50 group-hover:scale-105 transition-all duration-500">
                  {product.foto ? (
                    <img src={product.foto} alt={product.nama} className="w-full h-full object-cover" onError={(e) => (e.currentTarget.src = "")} />
                  ) : (
                    <Package size={40} className="text-slate-200" />
                  )}
                </div>
                <div className="text-center w-full">
                  <h4 className="font-black text-slate-800 text-sm leading-tight mb-1 truncate px-2">{product.nama}</h4>
                  <div className="flex items-center justify-center gap-2">
                    <p className="text-blue-600 font-black text-xs">Rp {Number(product.harga).toLocaleString('id-ID')}</p>
                    <span className="text-[9px] font-bold text-amber-500 bg-amber-50 px-2 py-0.5 rounded-full">+{product.poin} pts</span>
                  </div>
                </div>
              </button>
            ))
          )}
        </div>
      </div>

