import VisionPOS from './components/VisionPOS';
import SelectInputPage from './components/SelectInputPage';
import BarcodeScannerPage from './components/BarcodeScannerPage';
import CartPage from './components/CartPage';
import MembershipPage from './components/MembershipPage';
import VoucherSelectionPage from './components/VoucherSelectionPage';
import PaymentQRIS from './components/PaymentQRIS';
import SuccessPage from './components/SuccessPage';
import Layout from './components/Layout';

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbwwhng1JBosu7PNworCfAe8uB8uKN-aLvWoBuHuHW9CwRpMrdHuPmkyHjpZeMoOC6VDdw/exec";

interface MemberData {
  id: string;
  name: string;
  tier: string;
  points: number;
}

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.LANDING);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isMember, setIsMember] = useState<boolean>(false);
  const [memberInfo, setMemberInfo] = useState<MemberData | null>(null);
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);
  const [pointsUsed, setPointsUsed] = useState<number>(0);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);
  const [isCheckingMember, setIsCheckingMember] = useState<boolean>(false);

  const handleStart = () => setView(ViewState.SELECT_INPUT);

  const handleFinishVisionScan = (items: CartItem[]) => {
    setCart(items);
    setView(ViewState.CART);
  };

  const handleFindMember = async (id: string = "VP-1001") => {
    setIsCheckingMember(true);
    try {
      const response = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=GET_MEMBER&id=${id}`);
      const result = await response.json();

      if (result.status === "success") {
        setMemberInfo(result.data);
        setIsMember(true);
        setView(ViewState.SELECT_VOUCHER);
      } else {
        alert("Member tidak ditemukan di database.");
      }
    } catch (error) {
      console.error("Member search error:", error);
      alert("Gagal menghubungi server database member.");
    } finally {
      setIsCheckingMember(false);
    }
  };

  const calculateDiscount = () => {
    if (!selectedVoucher) return 0;
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return selectedVoucher.discountType === 'PERCENT' ? subtotal * (selectedVoucher.value / 100) : selectedVoucher.value;
  };

  const syncTransaction = async (total: number, tax: number, subtotal: number, discount: number, method: string = "QRIS") => {
    setIsSyncing(true);
    const transactionId = `VP-${Math.floor(1000 + Math.random() * 9000)}`;
    const itemsSummary = cart.map(item => `${item.name} (${item.quantity}x)`).join(', ');
    const totalPointsEarned = cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);

    const itemsDetail = cart.map(item => ({ 
      name: item.name, 
      price: item.price, 
      qty: item.quantity, 
      total: item.price * item.quantity 
    }));

    const payload = {
      action: "SYNC_TRANSACTION",
      transactionId,
      memberId: memberInfo?.id || "",
      customerType: isMember ? 'MEMBER' : 'GUEST',
      customerName: isMember ? memberInfo?.name : "Pelanggan Guest",
      itemsSummary,
      items: itemsDetail,
      subtotal,
      voucherName: selectedVoucher?.title || "-",
      voucherDiscount: discount,
      pointsDiscount: pointsUsed,
      tax,
      totalPaid: total,
      pointsEarned: totalPointsEarned,
      paymentMethod: method
    };

    try {
      await fetch(GOOGLE_SHEET_WEBAPP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });
    } catch (error) {
      console.error("Sync Error:", error);
    } finally {
      setTimeout(() => {
        setIsSyncing(false);
        setView(ViewState.SUCCESS);
      }, 1000);
    }
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(1, item.quantity + delta) } : item).filter(item => item.quantity > 0));
  };

  const renderView = () => {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const voucherDiscount = calculateDiscount();
    const totalBeforeTax = Math.max(0, subtotal - voucherDiscount - pointsUsed);
    const tax = totalBeforeTax * 0.11;
    const finalTotal = totalBeforeTax + tax;

    switch (view) {
      case ViewState.LANDING: 
        return <LandingPage onStart={handleStart} />;

      case ViewState.SELECT_INPUT:
        return (
          <SelectInputPage 
            onSelectAI={() => setView(ViewState.POS)} 
            onSelectBarcode={() => setView(ViewState.SCANNING_BARCODE)} 
            onBack={() => setView(ViewState.LANDING)} 
          />
        );

      case ViewState.SCANNING_BARCODE:
        return (
          <BarcodeScannerPage 
            onBack={() => setView(ViewState.SELECT_INPUT)} 
            onFinish={() => setView(ViewState.CART)} 
          />
        );

      case ViewState.POS: 
        return <VisionPOS onBack={() => setView(ViewState.SELECT_INPUT)} onCheckout={handleFinishVisionScan} />;

      case ViewState.CART: 
        return <CartPage cart={cart} isMember={isMember} selectedVoucher={selectedVoucher} discountAmount={voucherDiscount} pointsUsed={pointsUsed} onUpdateQuantity={handleUpdateQuantity} onRemoveItem={(id) => setCart(prev => prev.filter(item => item.id !== id))} onReset={() => setView(ViewState.LANDING)} onGoToMembership={() => setView(ViewState.MEMBERSHIP_SCAN)} onGoToVouchers={() => setView(ViewState.SELECT_VOUCHER)} onConfirm={() => setView(ViewState.PAYMENT_QRIS)} />;

      case ViewState.MEMBERSHIP_SCAN: 
        return <MembershipPage isChecking={isCheckingMember} onSkip={() => setView(ViewState.SELECT_VOUCHER)} onDetected={() => handleFindMember()} />;

      case ViewState.SELECT_VOUCHER: 
        return <VoucherSelectionPage isMember={isMember} memberData={memberInfo} selectedVoucherId={selectedVoucher?.id} pointsUsed={pointsUsed} onSelectPoints={setPointsUsed} onSelect={setSelectedVoucher} onBack={() => setView(ViewState.CART)} cart={cart} />;

      case ViewState.PAYMENT_QRIS: 
        return <PaymentQRIS onBack={() => setView(ViewState.CART)} onSuccess={() => syncTransaction(finalTotal, tax, subtotal, voucherDiscount, "QRIS")} total={finalTotal} />;

      case ViewState.SUCCESS: 
        return <SuccessPage onFinish={() => { setCart([]); setView(ViewState.LANDING); setIsMember(false); setMemberInfo(null); setSelectedVoucher(null); setPointsUsed(0); }} total={finalTotal} isSyncing={isSyncing} />;

      default: 
        return <LandingPage onStart={handleStart} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Layout hideHeaderFooter={[ViewState.POS, ViewState.MEMBERSHIP_SCAN, ViewState.SELECT_VOUCHER, ViewState.PAYMENT_QRIS, ViewState.SUCCESS, ViewState.SCANNING_BARCODE].includes(view)}>
        {renderView()}
      </Layout>
    </div>
  );
};

export default App;

/**
 * VisionPay Sync System v8.0 - ROBUST TRANSACTION SYNC
 */

const SPREADSHEET_ID = "1PGUwYgrQFtpv2hHpr_sDAqdsp9pJFMQtGvzjn_u9LPQ";

function pastikanString(data) {
  if (data === null || data === undefined) return "";
  if (typeof data === 'object') return JSON.stringify(data);
  return data.toString();
}

function doPost(e) {
  var ss;
  try {
    ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: "ID Spreadsheet tidak valid" })).setMimeType(ContentService.MimeType.JSON);
  }

  var sheetOrders = ss.getSheetByName("Orders") || ss.insertSheet("Orders");
  var sheetDetails = ss.getSheetByName("Transaction_Details") || ss.insertSheet("Transaction_Details");
  var sheetMembers = ss.getSheetByName("Members") || ss.insertSheet("Members");

  try {
    var rawData = JSON.parse(e.postData.contents);
    var action = rawData.action;

    if (action === "SYNC_TRANSACTION") {
      // 1. Simpan ke Sheet Orders
      var barisUtama = [
        new Date(),
        pastikanString(rawData.transactionId),
        pastikanString(rawData.customerType),
        pastikanString(rawData.customerName),
        pastikanString(rawData.itemsSummary),
        pastikanString(rawData.paymentMethod),
        Number(rawData.subtotal) || 0,
        pastikanString(rawData.voucherName),
        Number(rawData.voucherDiscount) || 0,
        Number(rawData.pointsDiscount) || 0,
        Number(rawData.tax) || 0,
        Number(rawData.totalPaid) || 0,
        Number(rawData.pointsEarned) || 0
      ];
      sheetOrders.appendRow(barisUtama);

      // 2. Simpan ke Sheet Transaction_Details (Detail Barang)
      var items = rawData.items;
      // Jika items terkirim sebagai string (karena JSON.stringify ganda), parse kembali
      if (typeof items === 'string') {
        try { items = JSON.parse(items); } catch(e) {}
      }

      if (items && Array.isArray(items) && items.length > 0) {
        items.forEach(function(item) {
          sheetDetails.appendRow([
            pastikanString(rawData.transactionId), 
            pastikanString(item.name), 
            Number(item.price) || 0, 
            Number(item.qty) || 1, 
            Number(item.total) || 0,
            pastikanString(rawData.paymentMethod)
          ]);
        });
      }

      // 3. Update Poin Member
      if (rawData.customerType === "MEMBER" && rawData.memberId) {
        var memberRows = sheetMembers.getDataRange().getValues();
        for (var j = 1; j < memberRows.length; j++) {
          if (memberRows[j][0].toString() === rawData.memberId.toString()) {
            var ptsSekarang = Number(memberRows[j][3]) || 0;
            var ptsUpdate = ptsSekarang - (Number(rawData.pointsDiscount) || 0) + (Number(rawData.pointsEarned) || 0);
            sheetMembers.getRange(j + 1, 4).setValue(ptsUpdate);
            break;
          }
        }
      }
      return ContentService.createTextOutput(JSON.stringify({ status: "success" })).setMimeType(ContentService.MimeType.JSON);
    }

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: err.toString() })).setMimeType(ContentService.MimeType.JSON);
  }
}

// Fungsi doGet tetap sama untuk GET_PRODUCTS dan GET_MEMBER
function doGet(e) {
  var ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  var action = e.parameter.action;

  if (action === "GET_PRODUCTS") {
    var sheet = ss.getSheetByName("Products");
    if (!sheet) return ContentService.createTextOutput(JSON.stringify([])).setMimeType(ContentService.MimeType.JSON);
    var data = sheet.getDataRange().getValues();
    var headers = data[0];
    var products = [];
    for (var i = 1; i < data.length; i++) {
      var obj = {};
      headers.forEach(function(header, index) {
        var key = header.toLowerCase().replace(/ /g, "_");
        obj[key] = data[i][index];
      });
      products.push(obj);
    }
    return ContentService.createTextOutput(JSON.stringify(products)).setMimeType(ContentService.MimeType.JSON);
  }

  if (action === "GET_MEMBER") {
    var memberId = e.parameter.id;
    var sheet = ss.getSheetByName("Members");
    if (!sheet) return ContentService.createTextOutput(JSON.stringify({ status: "error" })).setMimeType(ContentService.MimeType.JSON);
    var data = sheet.getDataRange().getValues();
    for (var i = 1; i < data.length; i++) {
      if (data[i][0].toString() === memberId) {
        return ContentService.createTextOutput(JSON.stringify({
          status: "success",
          data: { id: data[i][0].toString(), name: data[i][1].toString(), tier: data[i][2].toString(), points: Number(data[i][3]) || 0 }
        })).setMimeType(ContentService.MimeType.JSON);
      }
    }
    return ContentService.createTextOutput(JSON.stringify({ status: "not_found" })).setMimeType(ContentService.MimeType.JSON);
  }
  return HtmlService.createHtmlOutput("VisionPay API v8.0 Ready");
}

