                <p className="text-white font-black text-4xl tracking-tighter">Rp {subtotal.toLocaleString('id-ID')}</p>
             </div>
             <div className="text-right">
                <p className="text-blue-300 font-black text-[10px] uppercase tracking-widest mb-1">Cashback</p>
                <p className="text-white font-black text-xl">+{totalPoints} pts</p>
             </div>
          </div>

          <button 
            disabled={cart.length === 0}
            onClick={handleCheckoutInternal}
            className="w-full py-6 bg-[#5551FF] hover:bg-[#4440FF] disabled:bg-white/10 disabled:text-white/20 text-white rounded-[32px] font-black text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-4 active:scale-[0.98]"
          >
            <CreditCard size={22} />
            Konfirmasi
          </button>
        </div>
      </div>
    </div>
  );
};

export default VisionPOS;

import React, { useRef, useEffect, useState } from 'react';
import { ArrowLeft, Camera, Info, Loader2, Sparkles } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { CartItem } from '../types';

interface ScanningPageProps {
  onBack: () => void;
  onCapture: (detectedItems: CartItem[]) => void;
}

const ScanningPage: React.FC<ScanningPageProps> = ({ onBack, onCapture }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // DAFTAR PRODUK (Cukup definisikan di sini, tidak perlu dataset foto)
  const PRODUCT_CATALOG = `
    Daftar Produk VisionPay:
    1. Nama: Tumbler with flower pattern, ID: 1, Harga: 75000, Poin: 350
    2. Nama: Black and white patterned pillow, ID: 2, Harga: 50000, Poin: 150
    3. Nama: Stainless Steel Fork, ID: 3, Harga: 15000, Poin: 50
  `;

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
  };

  useEffect(() => {
    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: 1280, height: 720 } 
        });
        streamRef.current = s;
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
      } catch (err) {
        console.error("Camera access denied", err);
      }
    }
    setupCamera();
    return () => {
      stopCamera();
    };
  }, []);

  const handleBackInternal = () => {
    stopCamera();
    onBack();
  };

  const handleAnalyze = async () => {
    if (!videoRef.current || !canvasRef.current || isAnalyzing) return;

    setIsAnalyzing(true);
    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (ctx) {
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    }

    const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: `Identifikasi barang-barang yang ada di gambar ini berdasarkan katalog berikut: ${PRODUCT_CATALOG}. 
                       Berikan jawaban HANYA dalam format JSON array: [{"id": "...", "name": "...", "price": 0, "quantity": 1, "points": 0}]. 
                       Jika barang tidak ada di katalog, abaikan saja.` }
            ]
          }
        ],
        config: {
          responseMimeType: "application/json",
        }
      });

      const result = JSON.parse(response.text || "[]");
      if (result.length > 0) {
        stopCamera();
        onCapture(result);
      } else {
        alert("Barang tidak dikenali. Pastikan barang ada dalam katalog dan terlihat jelas.");
      }
    } catch (error) {
      console.error("AI Error:", error);
      alert("Gagal menganalisis gambar. Coba lagi.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F8FAFC] w-full h-screen">
      <canvas ref={canvasRef} className="hidden" />

      <div className="p-6 flex justify-between items-center z-10">
        <button 
          onClick={handleBackInternal}
          className="flex items-center gap-2 px-4 py-2 glass-card rounded-xl text-slate-700 font-bold text-sm shadow-sm"
        >
          <ArrowLeft size={16} />
          Kembali
        </button>
        <div className="flex items-center gap-2 px-3 py-1.5 glass-card rounded-full shadow-sm">
          <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
          <span className="text-[10px] font-bold text-slate-800 tracking-wider uppercase">AI Sensor: Aktif</span>
        </div>
      </div>

      <div className="flex-1 flex items-center justify-center p-4 relative">
        <div className="relative w-full max-w-lg aspect-[3/4] bg-slate-900 rounded-[40px] overflow-hidden vision-shadow border-[8px] border-white">
          <div className="absolute top-0 left-1/2 -translate-x-1/2 z-20">
             <div className="bg-[#5551FF] text-white text-[10px] font-black px-4 py-1.5 rounded-b-xl uppercase tracking-tighter flex items-center gap-2">
                <Sparkles size={12} /> Gemini Vision 3.0
             </div>
          </div>

          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            className={`w-full h-full object-cover transition-all duration-500 ${isAnalyzing ? 'brightness-50 grayscale' : 'brightness-110'}`} 
          />

          <div className="scan-line" />

          <div className="absolute top-10 left-10 w-8 h-8 border-t-4 border-l-4 border-white/60 rounded-tl-lg" />
          <div className="absolute top-10 right-10 w-8 h-8 border-t-4 border-r-4 border-white/60 rounded-tr-lg" />
          <div className="absolute bottom-10 left-10 w-8 h-8 border-b-4 border-l-4 border-white/60 rounded-bl-lg" />
          <div className="absolute bottom-10 right-10 w-8 h-8 border-b-4 border-r-4 border-white/60 rounded-br-lg" />

          {isAnalyzing && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/40 backdrop-blur-sm z-30">
              <Loader2 size={48} className="text-white animate-spin mb-4" />
              <p className="text-white font-black text-sm uppercase tracking-widest">Menganalisis...</p>
            </div>
          )}
        </div>
      </div>

      <div className="pb-12 flex flex-col items-center gap-6">
        <div className="flex flex-col items-center gap-3">
          <button 
            onClick={handleAnalyze}
            disabled={isAnalyzing}
            className="w-24 h-24 bg-[#5551FF] rounded-full flex items-center justify-center vision-shadow ring-8 ring-blue-100 transition-all active:scale-90 hover:bg-[#4440FF] disabled:bg-slate-400 disabled:ring-slate-100"
          >
            {isAnalyzing ? <Loader2 size={40} className="text-white animate-spin" /> : <Camera size={40} className="text-white" />}
          </button>
          <span className="text-sm font-black text-[#5551FF] uppercase tracking-widest animate-pulse">
            {isAnalyzing ? 'Sedang Memproses' : 'Ketuk untuk Deteksi AI'}
          </span>
        </div>

        <div className="bg-white/80 backdrop-blur-md px-6 py-3 rounded-2xl flex items-center gap-3 border border-slate-100 shadow-sm">
          <Info size={16} className="text-slate-400" />
          <span className="text-[11px] font-bold text-slate-500 uppercase tracking-tight">
            Arahkan kamera ke semua belanjaan Anda
          </span>
        </div>
      </div>
    </div>
  );
};

export default ScanningPage;

import React, { useRef, useEffect, useState } from 'react';
import { Camera, ShoppingCart, Trash2, CreditCard, Loader2, BrainCircuit, Scan, ShieldCheck, AlertCircle, RefreshCw, X, Package, Sparkles } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { CartItem } from '../types';

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbxC-MIdsxtbFktGhLU3Yh5dALiDeLoB1QwiFdHsXULB8aKCvgzOVVyIE12pjXePIPhDtA/exec";

interface VisionPOSProps {
  onCheckout: (items: CartItem[]) => void;
  onBack: () => void;
}

const VisionPOS: React.FC<VisionPOSProps> = ({ onCheckout, onBack }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const [cart, setCart] = useState<CartItem[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isLoadingProducts, setIsLoadingProducts] = useState(true);
  const [dynamicCatalog, setDynamicCatalog] = useState<string>("");
  const [statusMsg, setStatusMsg] = useState<string>("Inisialisasi...");
  const [showError, setShowError] = useState(false);
  const [lastDetected, setLastDetected] = useState<string>("");

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
  };

  const fetchProducts = async () => {
    setIsLoadingProducts(true);
    setStatusMsg("Sync Katalog...");
    try {
      const response = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=GET_PRODUCTS`);
      const rawProducts = await response.json();

      if (rawProducts && rawProducts.length > 0) {
        // Normalisasi data agar fleksibel dengan berbagai nama kolom di Spreadsheet
        const normalized = rawProducts.map((p: any) => ({
          id: p.id || p.id_produk || p.no || "",
          nama: p.nama || p.name || p.nama_produk || p.produk || "Tanpa Nama",
          harga: Number(p.harga || p.price || p.nilai || 0),
          poin: Number(p.poin || p.points || p.score || 0),
          foto: p.foto || p.image || p.foto_produk || p.url || "",
          kategori: p.kategori || p.category || "Umum"
        }));

        console.log("Katalog Terdeteksi:");
        console.table(normalized);

        const catalogText = normalized.map((p: any) => 
          `Item [ID: ${p.id}, Nama: ${p.nama}, Harga: ${p.harga}, Poin: ${p.poin}, Kategori: ${p.kategori}]`
        ).join("\n");

        setDynamicCatalog(catalogText);
        setStatusMsg("Katalog Aktif");
      } else {
        setStatusMsg("Sheet Kosong");
        console.warn("Spreadsheet terhubung tapi tidak ada data di sheet 'Products'");
      }
    } catch (err) {
      console.error("Fetch failed", err);
      setStatusMsg("Offline Mode");
    } finally {
      setIsLoadingProducts(false);
    }
  };

  useEffect(() => {
    fetchProducts();
    async function startCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
        });
        streamRef.current = s;
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        console.error("Camera error", err);
        setStatusMsg("Kamera Error");
      }
    }
    startCamera();
    return () => stopCamera();
  }, []);

  const handleCheckoutInternal = () => {
    stopCamera();
    onCheckout(cart);
  };

  const handleBackInternal = () => {
    stopCamera();
    onBack();
  };

  const analyzeFrame = async () => {
    if (!videoRef.current || !canvasRef.current || isAnalyzing || isLoadingProducts) return;

    setIsAnalyzing(true);
    setShowError(false);
    setStatusMsg("AI Menganalisis...");

    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.drawImage(video, 0, 0);

    const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: `SISTEM KASIR VISION AI.
                       Tugas: Identifikasi produk dalam gambar berdasarkan katalog resmi di bawah ini.

                       KATALOG RESMI:
                       ${dynamicCatalog}

                       ATURAN:
                       1. Cocokkan visual gambar dengan Nama dan Deskripsi di katalog.
                       2. Kembalikan data dalam format JSON ARRAY.
                       3. Gunakan field: id, name, price, quantity, points.
                       4. Jika barang tidak ada di katalog di atas, jangan dimasukkan ke list.
                       5. Pastikan properti "name" sama persis dengan yang ada di katalog.` }
            ]
          }
        ],
        config: { 
          responseMimeType: "application/json",
          temperature: 0.1,
        }
      });

      const detected: any[] = JSON.parse(response.text || "[]");

      if (detected.length > 0) {
        setCart(prev => {
          let updated = [...prev];
          detected.forEach(item => {
            const idx = updated.findIndex(i => i.id === item.id || i.name === item.name);
            if (idx > -1) {
              updated[idx].quantity += (item.quantity || 1);
            } else {
              updated.push({
                id: item.id || Math.random().toString(),
                name: item.name,
                price: item.price || 0,
                quantity: item.quantity || 1,
                points: item.points || 0
              });
            }
          });
          return updated;
        });
        setLastDetected(detected.map(d => d.name).join(", "));
        setStatusMsg("Produk Ok!");
        setTimeout(() => setLastDetected(""), 3000);
      } else {
        setStatusMsg("Tidak Dikenali");
        setShowError(true);
      }
    } catch (error) {
      console.error("AI Error:", error);
      setStatusMsg("Error Deteksi");
    } finally {
      setIsAnalyzing(false);
      setTimeout(() => setStatusMsg("Siap Scan"), 2000);
    }
  };

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalPoints = cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);

  return (
    <div className="fixed inset-0 bg-[#F8FAFC] flex overflow-hidden font-['Plus_Jakarta_Sans']">
      <canvas ref={canvasRef} className="hidden" />

      <div className="flex-1 relative flex flex-col bg-white">
        <video ref={videoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover grayscale-[0.2]" />

        <div className="absolute inset-0 pointer-events-none border-[32px] border-white/20">
          <div className="absolute top-10 left-10 flex items-center gap-4 bg-white/90 backdrop-blur-xl p-4 rounded-[28px] shadow-2xl border border-white pointer-events-auto">
             <div className="w-12 h-12 bg-[#5551FF] rounded-2xl flex items-center justify-center shadow-lg">
                <BrainCircuit className="text-white" size={24} />
             </div>
             <div className="pr-4">
                <h1 className="text-slate-900 font-black text-xl tracking-tighter uppercase leading-none">Vision AI</h1>
                <p className="text-[#5551FF] text-[9px] font-black tracking-[0.2em] uppercase mt-1">
                  {isLoadingProducts ? 'Syncing...' : 'Katalog Online'}
                </p>
             </div>
             <button onClick={fetchProducts} className="p-2 hover:bg-slate-100 rounded-xl text-slate-400 transition-colors">
                <RefreshCw size={18} className={isLoadingProducts ? 'animate-spin' : ''} />
             </button>
