  const [dynamicCatalog, setDynamicCatalog] = useState<string>("");
  const [statusMsg, setStatusMsg] = useState<string>("Inisialisasi...");
  const [showError, setShowError] = useState(false);
  const [lastDetected, setLastDetected] = useState<string>("");

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
  };

  const fetchProducts = async () => {
    setIsLoadingProducts(true);
    setStatusMsg("Sync Katalog...");
    try {
      const response = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=GET_PRODUCTS`);
      const rawData = await response.json();

      // Logika Baru: Menangani data Array of Arrays dari Apps Script v8.2
      if (rawData && Array.isArray(rawData) && rawData.length > 1) {
        const headers = rawData[0].map((h: any) => h.toString().toLowerCase().trim());

        // Cari posisi kolom secara dinamis berdasarkan header di spreadsheet
        const idx = {
          id: headers.indexOf('id'),
          nama: headers.indexOf('nama'),
          harga: headers.indexOf('harga'),
          poin: headers.indexOf('poin'),
          foto: headers.indexOf('foto'),
          kat: headers.indexOf('kategori')
        };

        const normalized = rawData.slice(1).map((row: any[]) => ({
          id: row[idx.id] || "",
          nama: row[idx.nama] || "Produk",
          harga: Number(row[idx.harga] || 0),
          poin: Number(row[idx.poin] || 0),
          foto: row[idx.foto] || "",
          kategori: row[idx.kat] || "Umum"
        })).filter(p => p.nama !== "Produk"); // Filter baris kosong

        console.log("Katalog Berhasil Dimuat:", normalized);

        const catalogText = normalized.map((p: any) => 
          `Item [ID: ${p.id}, Nama: ${p.nama}, Harga: ${p.harga}, Poin: ${p.poin}]`
        ).join("\n");

        setDynamicCatalog(catalogText);
        setStatusMsg("Katalog Aktif");
      } else {
        setStatusMsg("Katalog Kosong");
        console.warn("Data produk tidak ditemukan atau format salah.");
      }
    } catch (err) {
      console.error("Fetch failed", err);
      setStatusMsg("Offline Mode");
    } finally {
      setIsLoadingProducts(false);
    }
  };

  useEffect(() => {
    fetchProducts();
    async function startCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
        });
        streamRef.current = s;
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        console.error("Camera error", err);
        setStatusMsg("Kamera Error");
      }
    }
    startCamera();
    return () => stopCamera();
  }, []);

  const handleCheckoutInternal = () => {
    stopCamera();
    onCheckout(cart);
  };

  const handleBackInternal = () => {
    stopCamera();
    onBack();
  };

  const analyzeFrame = async () => {
    if (!videoRef.current || !canvasRef.current || isAnalyzing || isLoadingProducts) return;

    setIsAnalyzing(true);
    setShowError(false);
    setStatusMsg("AI Menganalisis...");

    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.drawImage(video, 0, 0);

    const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: `SISTEM KASIR VISION AI.
                       Tugas: Identifikasi produk dalam gambar berdasarkan katalog resmi di bawah ini.

                       KATALOG RESMI:
                       ${dynamicCatalog}

                       ATURAN:
                       1. Cocokkan visual gambar dengan Nama di katalog.
                       2. Kembalikan data dalam format JSON ARRAY.
                       3. Gunakan field: id, name, price, quantity, points.
                       4. Pastikan properti "name" sama persis dengan yang ada di katalog.` }
            ]
          }
        ],
        config: { 
          responseMimeType: "application/json",
          temperature: 0.1,
        }
      });

      const detected: any[] = JSON.parse(response.text || "[]");

      if (detected.length > 0) {
        setCart(prev => {
          let updated = [...prev];
          detected.forEach(item => {
            const idx = updated.findIndex(i => i.id === item.id || i.name === item.name);
            if (idx > -1) {
              updated[idx].quantity += (item.quantity || 1);
            } else {
              updated.push({
                id: item.id || Math.random().toString(),
                name: item.name,
                price: item.price || 0,
                quantity: item.quantity || 1,
                points: item.points || 0
              });
            }
          });
          return updated;
        });
        setLastDetected(detected.map(d => d.name).join(", "));
        setStatusMsg("Produk Ok!");
        setTimeout(() => setLastDetected(""), 3000);
      } else {
        setStatusMsg("Tidak Dikenali");
        setShowError(true);
      }
    } catch (error) {
      console.error("AI Error:", error);
      setStatusMsg("Error Deteksi");
    } finally {
      setIsAnalyzing(false);
      setTimeout(() => setStatusMsg("Siap Scan"), 2000);
    }
  };

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalPoints = cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);

  return (
    <div className="fixed inset-0 bg-[#F8FAFC] flex overflow-hidden font-['Plus_Jakarta_Sans']">
      <canvas ref={canvasRef} className="hidden" />

      <div className="flex-1 relative flex flex-col bg-white">
        <video ref={videoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover grayscale-[0.2]" />

        <div className="absolute inset-0 pointer-events-none border-[32px] border-white/20">
          <div className="absolute top-10 left-10 flex items-center gap-4 bg-white/90 backdrop-blur-xl p-4 rounded-[28px] shadow-2xl border border-white pointer-events-auto">
             <div className="w-12 h-12 bg-[#5551FF] rounded-2xl flex items-center justify-center shadow-lg">
                <BrainCircuit className="text-white" size={24} />
             </div>
             <div className="pr-4">
                <h1 className="text-slate-900 font-black text-xl tracking-tighter uppercase leading-none">Vision AI</h1>
                <p className="text-[#5551FF] text-[9px] font-black tracking-[0.2em] uppercase mt-1">
                  {isLoadingProducts ? 'Syncing...' : 'Katalog Online'}
                </p>
             </div>
             <button onClick={fetchProducts} className="p-2 hover:bg-slate-100 rounded-xl text-slate-400 transition-colors">
                <RefreshCw size={18} className={isLoadingProducts ? 'animate-spin' : ''} />
             </button>
          </div>

          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[480px] h-[480px]">
             <div className="absolute top-0 left-0 w-24 h-24 border-t-[8px] border-l-[8px] border-[#5551FF] rounded-tl-[50px] opacity-60" />
             <div className="absolute top-0 right-0 w-24 h-24 border-t-[8px] border-r-[8px] border-[#5551FF] rounded-tr-[50px] opacity-60" />
             <div className="absolute bottom-0 left-0 w-24 h-24 border-b-[8px] border-l-[8px] border-[#5551FF] rounded-bl-[50px] opacity-60" />
             <div className="absolute bottom-0 right-0 w-24 h-24 border-b-[8px] border-r-[8px] border-[#5551FF] rounded-br-[50px] opacity-60" />
          </div>
          <div className="scan-line !bg-[#5551FF]/40" />
        </div>

        <button onClick={handleBackInternal} className="absolute top-10 right-10 w-12 h-12 bg-white/90 backdrop-blur-xl rounded-2xl flex items-center justify-center text-slate-400 hover:text-red-500 shadow-xl pointer-events-auto transition-all">
          <X size={24} />
        </button>

        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex flex-col items-center gap-6 z-20 w-full px-12">
          {lastDetected && (
            <div className="bg-green-500 text-white px-10 py-4 rounded-full flex items-center gap-3 animate-in slide-in-from-bottom duration-500 shadow-2xl">
              <ShieldCheck size={20} />
              <span className="font-black text-sm uppercase tracking-widest">Berhasil: {lastDetected}</span>
            </div>
          )}

          {showError && (
            <div className="bg-amber-500 text-white px-10 py-4 rounded-full flex items-center gap-3 animate-in fade-in duration-300 shadow-2xl">
              <AlertCircle size={20} />
              <span className="font-black text-sm uppercase tracking-widest">Tidak ada di Katalog</span>
            </div>
          )}

          <button 
            onClick={analyzeFrame}
            disabled={isAnalyzing || isLoadingProducts}
            className={`w-28 h-28 rounded-full flex items-center justify-center transition-all active:scale-90 shadow-2xl
              ${isAnalyzing ? 'bg-slate-100 text-slate-300' : 'bg-[#5551FF] hover:bg-[#4440FF] text-white ring-[14px] ring-blue-500/10'}
            `}
          >
            {isAnalyzing ? <Loader2 className="animate-spin" size={44} /> : <Scan size={48} />}
          </button>

          <div className="bg-slate-900/80 backdrop-blur-xl px-8 py-3 rounded-2xl border border-white/10 shadow-2xl">
             <span className="text-white text-[11px] font-black uppercase tracking-[0.4em]">{statusMsg}</span>
          </div>
        </div>
      </div>

      <div className="w-[520px] bg-white flex flex-col z-30 shadow-[-40px_0_80px_rgba(0,0,0,0.05)] border-l border-slate-100">
        <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
          <div className="flex items-center gap-5">
            <div className="w-14 h-14 bg-[#5551FF]/10 rounded-[22px] flex items-center justify-center text-[#5551FF]">
              <ShoppingCart size={28} />
            </div>
            <div>
               <h2 className="text-slate-900 font-black text-2xl tracking-tight">AI Checkout</h2>
               <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Database Terhubung</p>
            </div>
          </div>
          <div className="px-5 py-2 bg-slate-900 rounded-full text-white font-black text-[11px] uppercase tracking-widest">
            {cart.length} ITEMS
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-white">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-8 opacity-40">
              <div className="w-32 h-32 bg-slate-50 rounded-[48px] flex items-center justify-center border-2 border-dashed border-slate-200">
                <Package size={48} className="text-slate-200" />
              </div>
              <p className="text-slate-900 font-black text-base uppercase tracking-[0.2em]">Keranjang Kosong</p>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={`${item.id}-${idx}`} className="group relative bg-white border border-slate-100 p-6 rounded-[36px] flex items-center gap-6 transition-all hover:shadow-2xl">
                <div className="w-20 h-20 bg-slate-50 rounded-[24px] overflow-hidden flex items-center justify-center border border-slate-100 shadow-inner group-hover:scale-110 transition-transform duration-500">
                   {item.imageUrl ? (
                     <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" onError={(e) => (e.currentTarget.src = "")} />
                   ) : (
                     <Scan size={24} className="text-slate-200" />
                   )}
                </div>

                <div className="flex-1 min-w-0">
                  <h4 className="text-slate-900 font-black text-base leading-tight truncate">{item.name}</h4>
                  <p className="text-[#5551FF] font-black text-sm mt-1">Rp {item.price.toLocaleString('id-ID')}</p>
                </div>

                <div className="flex flex-col items-end gap-3">
                   <div className="bg-slate-50 px-3 py-1.5 rounded-xl font-black text-slate-900 text-sm border border-slate-100">
                      x{item.quantity}
                   </div>
                   <button 
                     onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))}
                     className="w-10 h-10 rounded-2xl flex items-center justify-center text-slate-300 hover:text-red-500 transition-all"
                   >
                     <Trash2 size={18} />
                   </button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-10 bg-slate-900 text-white rounded-t-[50px] shadow-2xl">
          <div className="flex justify-between items-end mb-10">
             <div className="space-y-1">
                <p className="text-white/40 text-[10px] font-black uppercase tracking-[0.3em]">Total</p>
                <p className="text-white font-black text-4xl tracking-tighter">Rp {subtotal.toLocaleString('id-ID')}</p>
             </div>
             <div className="text-right">
                <p className="text-blue-300 font-black text-[10px] uppercase tracking-widest mb-1">Cashback</p>
                <p className="text-white font-black text-xl">+{totalPoints} pts</p>
             </div>
          </div>

          <button 
            disabled={cart.length === 0}
            onClick={handleCheckoutInternal}
            className="w-full py-6 bg-[#5551FF] hover:bg-[#4440FF] disabled:bg-white/10 disabled:text-white/20 text-white rounded-[32px] font-black text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-4 active:scale-[0.98]"
          >
            <CreditCard size={22} />
            Konfirmasi
          </button>
        </div>
      </div>
    </div>
  );
};

export default VisionPOS;

import React, { useState, useEffect } from 'react';
import { 
  Search, ShoppingCart, User, Package, 
  Plus, Minus, Trash2, Sparkles, 
  ChevronRight, CreditCard, Tag, Loader2, RefreshCw
} from 'lucide-react';
import { CartItem, Product, Voucher } from '../types';

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbxC-MIdsxtbFktGhLU3Yh5dALiDeLoB1QwiFdHsXULB8aKCvgzOVVyIE12pjXePIPhDtA/exec";

interface CashierPOSProps {
  cart: CartItem[];
  onAddToCart: (product: any) => void;
  onUpdateQuantity: (id: string, delta: number) => void;
  onRemoveItem: (id: string) => void;
  onCheckout: () => void;
  onScanAI: () => void;
  isMember: boolean;
  memberInfo: any;
  selectedVoucher: Voucher | null;
  discountAmount: number;
}

const CashierPOS: React.FC<CashierPOSProps> = ({ 
  cart, onAddToCart, onUpdateQuantity, onRemoveItem, onCheckout, onScanAI,
  isMember, memberInfo, selectedVoucher, discountAmount
}) => {
  const [products, setProducts] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  const fetchProducts = async () => {
    setIsLoading(true);
    try {
      const response = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=GET_PRODUCTS`);
      const rawData = await response.json();

      if (rawData && Array.isArray(rawData) && rawData.length > 1) {
        const headers = rawData[0].map((h: any) => h.toString().toLowerCase().trim());

        const idx = {
          id: headers.indexOf('id'),
          nama: headers.indexOf('nama'),
          harga: headers.indexOf('harga'),
          poin: headers.indexOf('poin'),
          foto: headers.indexOf('foto'),
          kat: headers.indexOf('kategori')
        };

        const normalized = rawData.slice(1).map((row: any[]) => ({
          id: row[idx.id] || Math.random().toString(),
          nama: row[idx.nama] || "Item",
          harga: Number(row[idx.harga] || 0),
          poin: Number(row[idx.poin] || 0),
          foto: row[idx.foto] || "",
          kategori: row[idx.kat] || "Umum"
        })).filter(p => p.nama !== "Item");

        setProducts(normalized);
      }
    } catch (error) {
      console.error("Gagal mengambil produk:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  const filteredProducts = products.filter(p => 
    (activeCategory === 'All' || p.kategori === activeCategory) &&
    p.nama.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const categories = ['All', ...new Set(products.map(p => p.kategori).filter(Boolean))];

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const tax = (subtotal - discountAmount) * 0.11;
  const total = (subtotal - discountAmount) + tax;

  return (
    <div className="flex w-full h-[calc(100vh-140px)] gap-6 animate-in fade-in duration-500">
      <div className="flex-1 flex flex-col gap-6 overflow-hidden">
        <div className="flex items-center gap-4 bg-white p-4 rounded-[24px] shadow-sm border border-slate-100">
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input 
              type="text" 
              placeholder="Cari produk..." 
              className="w-full pl-12 pr-4 py-3 bg-slate-50 rounded-xl focus:outline-none font-medium"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            onClick={fetchProducts}
            className="p-3 bg-slate-50 text-slate-400 hover:text-blue-500 rounded-xl transition-all"
          >
            <RefreshCw size={20} className={isLoading ? 'animate-spin' : ''} />
          </button>
          <button 
            onClick={onScanAI}
            className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-xl font-black text-sm uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
          >
            <Sparkles size={18} />
            Magic Scan
          </button>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-6 py-2.5 rounded-full text-xs font-black uppercase tracking-widest transition-all whitespace-nowrap
                ${activeCategory === cat ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-400 hover:bg-slate-50'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto pr-2 grid grid-cols-2 md:grid-cols-3 gap-4">
          {isLoading ? (
            <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-400">
              <Loader2 className="animate-spin mb-4" size={40} />
              <p className="font-bold text-sm uppercase tracking-widest">Sinkronisasi Database...</p>
            </div>
          ) : filteredProducts.length === 0 ? (
            <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-300">
              <Package size={60} strokeWidth={1} />
              <p className="font-black text-xs uppercase tracking-widest mt-4">Produk tidak ditemukan</p>
            </div>
          ) : (
            filteredProducts.map(product => (
              <button
                key={product.id}
                onClick={() => onAddToCart({
                  id: product.id,
                  name: product.nama,
                  price: product.harga,
                  points: product.poin,
                  imageUrl: product.foto
                })}
                className="bg-white p-5 rounded-[32px] border border-slate-100 hover:border-blue-500 hover:shadow-xl transition-all text-left group flex flex-col items-center gap-3 active:scale-95"
              >
                <div className="w-full aspect-square bg-slate-50 rounded-2xl flex items-center justify-center overflow-hidden border border-slate-50">
                  {product.foto ? (
                    <img src={product.foto} alt={product.nama} className="w-full h-full object-cover" />
                  ) : (
                    <Package size={40} className="text-slate-200" />
                  )}
                </div>
                <div className="text-center w-full">
                  <h4 className="font-black text-slate-800 text-sm truncate px-2">{product.nama}</h4>
                  <p className="text-blue-600 font-black text-xs">Rp {product.harga.toLocaleString('id-ID')}</p>
                </div>
              </button>
            ))
          )}
        </div>
      </div>

      <div className="w-[400px] bg-white rounded-[40px] shadow-xl border border-slate-50 flex flex-col overflow-hidden">
        <div className="p-8 border-b border-slate-50 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-50 rounded-xl flex items-center justify-center text-blue-600">
              <ShoppingCart size={20} />
            </div>
            <h3 className="font-black text-slate-800 text-lg">Ringkasan Pesanan</h3>
          </div>
          <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest">
            {cart.length}
          </span>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 opacity-50">
              <Package size={64} strokeWidth={1} />
              <p className="font-black text-xs uppercase tracking-widest mt-4">Keranjang Kosong</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex items-center gap-4 bg-slate-50/50 p-4 rounded-2xl group border border-transparent hover:border-slate-200 transition-all">
                <div className="flex-1">
                  <h5 className="font-bold text-slate-800 text-sm">{item.name}</h5>
                  <p className="text-xs text-blue-600 font-bold">Rp {item.price.toLocaleString('id-ID')}</p>
                </div>
                <div className="flex items-center gap-3 bg-white px-2 py-1 rounded-xl shadow-sm">
                  <button onClick={() => onUpdateQuantity(item.id, -1)} className="text-slate-400 hover:text-red-500"><Minus size={14}/></button>
                  <span className="font-black text-sm w-4 text-center">{item.quantity}</span>
                  <button onClick={() => onUpdateQuantity(item.id, 1)} className="text-slate-400 hover:text-blue-500"><Plus size={14}/></button>
                </div>
                <button onClick={() => onRemoveItem(item.id)} className="text-slate-300 hover:text-red-500"><Trash2 size={16}/></button>
              </div>
            ))
          )}
        </div>

        <div className="p-8 bg-slate-50/80 space-y-4">
          <div className="flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm">
            <div className="flex items-center gap-3">
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${isMember ? 'bg-green-100 text-green-600' : 'bg-slate-100 text-slate-400'}`}>
                <User size={16} />
              </div>
              <div className="flex flex-col">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Customer</span>
                <span className="text-xs font-black text-slate-800">{isMember ? memberInfo.name : 'Guest'}</span>
              </div>
            </div>
            <ChevronRight size={16} className="text-slate-300" />
          </div>

          <div className="flex justify-between items-end mb-4 pt-4 border-t border-slate-200">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Bayar</span>
            <span className="text-2xl font-black text-blue-600">Rp {total.toLocaleString('id-ID')}</span>
          </div>

          <button 
            disabled={cart.length === 0}
            onClick={onCheckout}
            className="w-full py-5 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 text-white rounded-[24px] font-black text-sm uppercase tracking-[0.2em] transition-all shadow-xl active:scale-95 flex items-center justify-center gap-3"
          >
            <CreditCard size={18} />
            Bayar
          </button>
        </div>
      </div>
    </div>
  );
};

export default CashierPOS;

import React, { useRef, useEffect, useState } from 'react';
import { Camera, ShoppingCart, Trash2, CreditCard, Loader2, BrainCircuit, Scan, ShieldCheck, AlertCircle, RefreshCw, X, Package, Sparkles } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { CartItem } from '../types';

const GOOGLE_SHEET_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbxC-MIdsxtbFktGhLU3Yh5dALiDeLoB1QwiFdHsXULB8aKCvgzOVVyIE12pjXePIPhDtA/exec";

interface VisionPOSProps {
  onCheckout: (items: CartItem[]) => void;
  onBack: () => void;
}

const VisionPOS: React.FC<VisionPOSProps> = ({ onCheckout, onBack }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const [cart, setCart] = useState<CartItem[]>([]);
  const [productsList, setProductsList] = useState<any[]>([]); // Simpan data produk lengkap
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isLoadingProducts, setIsLoadingProducts] = useState(true);
  const [dynamicCatalog, setDynamicCatalog] = useState<string>("");
  const [statusMsg, setStatusMsg] = useState<string>("Inisialisasi...");
  const [showError, setShowError] = useState(false);
  const [lastDetected, setLastDetected] = useState<string>("");

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
  };

  const fetchProducts = async () => {
    setIsLoadingProducts(true);
    setStatusMsg("Sync Katalog...");
    try {
      const response = await fetch(`${GOOGLE_SHEET_WEBAPP_URL}?action=GET_PRODUCTS`);
      const rawData = await response.json();

      if (rawData && Array.isArray(rawData) && rawData.length > 1) {
        const headers = rawData[0].map((h: any) => h.toString().toLowerCase().trim());

        const idx = {
          id: headers.indexOf('id'),
          nama: headers.indexOf('nama'),
          harga: headers.indexOf('harga'),
          poin: headers.indexOf('poin'),
          foto: headers.indexOf('foto'),
          kat: headers.indexOf('kategori')
        };

        const normalized = rawData.slice(1).map((row: any[]) => ({
          id: row[idx.id] || "",
          nama: row[idx.nama] || "Produk",
          harga: Number(row[idx.harga] || 0),
          poin: Number(row[idx.poin] || 0),
          foto: row[idx.foto] || "", // Pastikan foto tersimpan di sini
          kategori: row[idx.kat] || "Umum"
        })).filter(p => p.nama !== "Produk");

        setProductsList(normalized); // Simpan ke state untuk pencarian nanti

        const catalogText = normalized.map((p: any) => 
          `Item [ID: ${p.id}, Nama: ${p.nama}, Harga: ${p.harga}, Poin: ${p.poin}]`
        ).join("\n");

        setDynamicCatalog(catalogText);
        setStatusMsg("Katalog Aktif");
      } else {
        setStatusMsg("Katalog Kosong");
      }
    } catch (err) {
      console.error("Fetch failed", err);
      setStatusMsg("Offline Mode");
    } finally {
      setIsLoadingProducts(false);
    }
  };

  useEffect(() => {
    fetchProducts();
    async function startCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
        });
        streamRef.current = s;
        if (videoRef.current) videoRef.current.srcObject = s;
      } catch (err) {
        console.error("Camera error", err);
        setStatusMsg("Kamera Error");
      }
    }
    startCamera();
    return () => stopCamera();
  }, []);

  const handleCheckoutInternal = () => {
    stopCamera();
    onCheckout(cart);
  };

  const handleBackInternal = () => {
    stopCamera();
    onBack();
  };

  const analyzeFrame = async () => {
    if (!videoRef.current || !canvasRef.current || isAnalyzing || isLoadingProducts) return;

    setIsAnalyzing(true);
    setShowError(false);
    setStatusMsg("AI Menganalisis...");

    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.drawImage(video, 0, 0);

    const base64Image = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
              { text: `SISTEM KASIR VISION AI.
                       Tugas: Identifikasi produk dalam gambar berdasarkan katalog resmi di bawah ini.

                       KATALOG RESMI:
                       ${dynamicCatalog}

                       ATURAN:
                       1. Cocokkan visual gambar dengan Nama di katalog.
                       2. Kembalikan data dalam format JSON ARRAY.
                       3. Gunakan field: id, name, price, quantity, points.
                       4. Pastikan properti "name" sama persis dengan yang ada di katalog.` }
            ]
          }
        ],
        config: { 
          responseMimeType: "application/json",
          temperature: 0.1,
        }
      });

      const detected: any[] = JSON.parse(response.text || "[]");

      if (detected.length > 0) {
        setCart(prev => {
          let updated = [...prev];
          detected.forEach(item => {
            // Cari data asli dari productsList untuk mendapatkan imageUrl
            const originalProduct = productsList.find(p => p.id === item.id || p.nama.toLowerCase() === item.name.toLowerCase());

            const idx = updated.findIndex(i => i.id === item.id || i.name === item.name);
            if (idx > -1) {
              updated[idx].quantity += (item.quantity || 1);
            } else {
              updated.push({
                id: item.id || Math.random().toString(),
                name: item.name,
                price: item.price || 0,
                quantity: item.quantity || 1,
                points: item.points || 0,
                imageUrl: originalProduct?.foto || "" // Pasangkan foto di sini!
              });
            }
          });
          return updated;
        });
        setLastDetected(detected.map(d => d.name).join(", "));
        setStatusMsg("Produk Ok!");
        setTimeout(() => setLastDetected(""), 3000);
      } else {
        setStatusMsg("Tidak Dikenali");
        setShowError(true);
      }
    } catch (error) {
      console.error("AI Error:", error);
      setStatusMsg("Error Deteksi");
    } finally {
      setIsAnalyzing(false);
      setTimeout(() => setStatusMsg("Siap Scan"), 2000);
    }
  };

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalPoints = cart.reduce((sum, item) => sum + ((item.points || 0) * item.quantity), 0);

  return (
    <div className="fixed inset-0 bg-[#F8FAFC] flex overflow-hidden font-['Plus_Jakarta_Sans']">
      <canvas ref={canvasRef} className="hidden" />

      <div className="flex-1 relative flex flex-col bg-white">
        <video ref={videoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover grayscale-[0.2]" />

        <div className="absolute inset-0 pointer-events-none border-[32px] border-white/20">
          <div className="absolute top-10 left-10 flex items-center gap-4 bg-white/90 backdrop-blur-xl p-4 rounded-[28px] shadow-2xl border border-white pointer-events-auto">
             <div className="w-12 h-12 bg-[#5551FF] rounded-2xl flex items-center justify-center shadow-lg">
                <BrainCircuit className="text-white" size={24} />
             </div>
             <div className="pr-4">
                <h1 className="text-slate-900 font-black text-xl tracking-tighter uppercase leading-none">Vision AI</h1>
                <p className="text-[#5551FF] text-[9px] font-black tracking-[0.2em] uppercase mt-1">
                  {isLoadingProducts ? 'Syncing...' : 'Katalog Online'}
                </p>
             </div>
             <button onClick={fetchProducts} className="p-2 hover:bg-slate-100 rounded-xl text-slate-400 transition-colors">
                <RefreshCw size={18} className={isLoadingProducts ? 'animate-spin' : ''} />
             </button>
          </div>

          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[480px] h-[480px]">
             <div className="absolute top-0 left-0 w-24 h-24 border-t-[8px] border-l-[8px] border-[#5551FF] rounded-tl-[50px] opacity-60" />
             <div className="absolute top-0 right-0 w-24 h-24 border-t-[8px] border-r-[8px] border-[#5551FF] rounded-tr-[50px] opacity-60" />
             <div className="absolute bottom-0 left-0 w-24 h-24 border-b-[8px] border-l-[8px] border-[#5551FF] rounded-bl-[50px] opacity-60" />
             <div className="absolute bottom-0 right-0 w-24 h-24 border-b-[8px] border-r-[8px] border-[#5551FF] rounded-br-[50px] opacity-60" />
          </div>
          <div className="scan-line !bg-[#5551FF]/40" />
        </div>

        <button onClick={handleBackInternal} className="absolute top-10 right-10 w-12 h-12 bg-white/90 backdrop-blur-xl rounded-2xl flex items-center justify-center text-slate-400 hover:text-red-500 shadow-xl pointer-events-auto transition-all">
          <X size={24} />
        </button>

        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex flex-col items-center gap-6 z-20 w-full px-12">
          {lastDetected && (
            <div className="bg-green-500 text-white px-10 py-4 rounded-full flex items-center gap-3 animate-in slide-in-from-bottom duration-500 shadow-2xl">
              <ShieldCheck size={20} />
              <span className="font-black text-sm uppercase tracking-widest">Berhasil: {lastDetected}</span>
            </div>
          )}

          {showError && (
            <div className="bg-amber-500 text-white px-10 py-4 rounded-full flex items-center gap-3 animate-in fade-in duration-300 shadow-2xl">
              <AlertCircle size={20} />
              <span className="font-black text-sm uppercase tracking-widest">Tidak ada di Katalog</span>
            </div>
          )}

          <button 
            onClick={analyzeFrame}
            disabled={isAnalyzing || isLoadingProducts}
            className={`w-28 h-28 rounded-full flex items-center justify-center transition-all active:scale-90 shadow-2xl
              ${isAnalyzing ? 'bg-slate-100 text-slate-300' : 'bg-[#5551FF] hover:bg-[#4440FF] text-white ring-[14px] ring-blue-500/10'}
            `}
          >
            {isAnalyzing ? <Loader2 className="animate-spin" size={44} /> : <Scan size={48} />}
          </button>

          <div className="bg-slate-900/80 backdrop-blur-xl px-8 py-3 rounded-2xl border border-white/10 shadow-2xl">
             <span className="text-white text-[11px] font-black uppercase tracking-[0.4em]">{statusMsg}</span>
          </div>
        </div>
      </div>

      <div className="w-[520px] bg-white flex flex-col z-30 shadow-[-40px_0_80px_rgba(0,0,0,0.05)] border-l border-slate-100">
        <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
          <div className="flex items-center gap-5">
            <div className="w-14 h-14 bg-[#5551FF]/10 rounded-[22px] flex items-center justify-center text-[#5551FF]">
              <ShoppingCart size={28} />
            </div>
            <div>
               <h2 className="text-slate-900 font-black text-2xl tracking-tight">AI Checkout</h2>
               <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Database Terhubung</p>
            </div>
          </div>
          <div className="px-5 py-2 bg-slate-900 rounded-full text-white font-black text-[11px] uppercase tracking-widest">
            {cart.length} ITEMS
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-white">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-8 opacity-40">
              <div className="w-32 h-32 bg-slate-50 rounded-[48px] flex items-center justify-center border-2 border-dashed border-slate-200">
                <Package size={48} className="text-slate-200" />
              </div>
              <p className="text-slate-900 font-black text-base uppercase tracking-[0.2em]">Keranjang Kosong</p>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={`${item.id}-${idx}`} className="group relative bg-white border border-slate-100 p-6 rounded-[36px] flex items-center gap-6 transition-all hover:shadow-2xl">
                <div className="w-20 h-20 bg-slate-50 rounded-[24px] overflow-hidden flex items-center justify-center border border-slate-100 shadow-inner group-hover:scale-110 transition-transform duration-500">
                   {item.imageUrl ? (
                     <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" onError={(e) => (e.currentTarget.src = "")} />
                   ) : (
                     <Scan size={24} className="text-slate-200" />
                   )}
                </div>

                <div className="flex-1 min-w-0">
                  <h4 className="text-slate-900 font-black text-base leading-tight truncate">{item.name}</h4>
                  <p className="text-[#5551FF] font-black text-sm mt-1">Rp {item.price.toLocaleString('id-ID')}</p>
                </div>

                <div className="flex flex-col items-end gap-3">
                   <div className="bg-slate-50 px-3 py-1.5 rounded-xl font-black text-slate-900 text-sm border border-slate-100">
                      x{item.quantity}
                   </div>
                   <button 
                     onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))}
                     className="w-10 h-10 rounded-2xl flex items-center justify-center text-slate-300 hover:text-red-500 transition-all"
                   >
                     <Trash2 size={18} />
                   </button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-10 bg-slate-900 text-white rounded-t-[50px] shadow-2xl">
          <div className="flex justify-between items-end mb-10">
             <div className="space-y-1">
                <p className="text-white/40 text-[10px] font-black uppercase tracking-[0.3em]">Total</p>
                <p className="text-white font-black text-4xl tracking-tighter">Rp {subtotal.toLocaleString('id-ID')}</p>
             </div>
             <div className="text-right">
                <p className="text-blue-300 font-black text-[10px] uppercase tracking-widest mb-1">Cashback</p>
                <p className="text-white font-black text-xl">+{totalPoints} pts</p>
             </div>
          </div>

          <button 
            disabled={cart.length === 0}
            onClick={handleCheckoutInternal}
            className="w-full py-6 bg-[#5551FF] hover:bg-[#4440FF] disabled:bg-white/10 disabled:text-white/20 text-white rounded-[32px] font-black text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-4 active:scale-[0.98]"
          >
            <CreditCard size={22} />
            Konfirmasi
          </button>
        </div>
      </div>
    </div>
  );
};

export default VisionPOS;

